/// MIN (`is_max=false`) or MAX (`is_max=true`) of a resident int4 column over a filtered set of row
/// indices (the operator axis, doc 19): H2D the surviving u32 indices, H2D the accumulator's identity
/// (i32::MAX for min / i32::MIN for max -- not a memset byte pattern), run the reduction kernel (local
/// min/max per thread + one predicated `atom.min/max.s32`), and D2H the i32. `indices` must be
/// non-empty (an empty MIN/MAX is NULL, hard-errored upstream until M3).
fn launch_cuda_resident_i32_minmax_at_indices(
    resident: &CudaResidentDeviceMemory,
    byte_offset: u64,
    indices: &[u32],
    is_max: bool,
) -> Result<i32, CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    const PTX: &[u8] = include_bytes!("expr_proto.ptx");

    if indices.is_empty() {
        return Err(CudaRuntimeProbeError::InvalidInputLength(0));
    }
    let count = indices.len();
    let idx_bytes = count
        .checked_mul(std::mem::size_of::<u32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(count))?;
    let count_u64 = count as u64;

    let primary = resident.primary();
    primary.set_current()?;
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let htod_async = primary
        .cu_memcpy_htod_async
        .ok_or(CudaRuntimeProbeError::DriverLibraryUnavailable)?;
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let kernel_fn = primary.cached_function(c"gpu_db_resident_i32_minmax_at_indices", &ptx)?;
    let indices_dev = primary.lease_device_buffer(idx_bytes)?;
    let out = primary.lease_device_buffer(std::mem::size_of::<i32>())?;

    // Accumulator identity: min reduces against i32::MAX, max against i32::MIN.
    let init: i32 = if is_max { i32::MIN } else { i32::MAX };
    let op: u32 = u32::from(is_max);

    const BLOCK: u32 = 256;
    let grid = count_u64.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;
    let mut a0 = resident.device_ptr();
    let mut a1 = byte_offset;
    let mut a2 = indices_dev.ptr;
    let mut a3 = count_u64;
    let mut a4 = op;
    let mut a5 = out.ptr;
    let mut args = [
        (&mut a0 as *mut u64).cast::<c_void>(),
        (&mut a1 as *mut u64).cast::<c_void>(),
        (&mut a2 as *mut u64).cast::<c_void>(),
        (&mut a3 as *mut u64).cast::<c_void>(),
        (&mut a4 as *mut u32).cast::<c_void>(),
        (&mut a5 as *mut u64).cast::<c_void>(),
    ];
    launch_on_pooled_stream(resident, None, |stream, _scratch| {
        let rc = unsafe {
            htod_async(
                indices_dev.ptr,
                indices.as_ptr().cast::<c_void>(),
                idx_bytes,
                stream,
            )
        };
        if rc != 0 {
            return rc;
        }
        let rc = unsafe {
            htod_async(
                out.ptr,
                (&init as *const i32).cast::<c_void>(),
                std::mem::size_of::<i32>(),
                stream,
            )
        };
        if rc != 0 {
            return rc;
        }
        unsafe {
            cu_launch_kernel(
                kernel_fn,
                grid,
                1,
                1,
                BLOCK,
                1,
                1,
                0,
                stream,
                args.as_mut_ptr(),
                std::ptr::null_mut(),
            )
        }
    })?;
    let mut result = 0_i32;
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            (&mut result as *mut i32).cast::<c_void>(),
            out.ptr,
            std::mem::size_of::<i32>(),
        )
    })?;
    Ok(result)
}

/// MIN (`is_max=false`) / MAX (`is_max=true`) of a resident INT8 column over a filtered set of row
/// indices (the operator axis, doc 19): H2D the surviving u32 indices, H2D the i64 identity (i64::MAX
/// for min / i64::MIN for max), run the reduction kernel (2x4-byte i64 loads + predicated
/// `atom.min/max.s64`), D2H the i64. `indices` must be non-empty.
fn launch_cuda_resident_i64_minmax_at_indices(
    resident: &CudaResidentDeviceMemory,
    byte_offset: u64,
    indices: &[u32],
    is_max: bool,
) -> Result<i64, CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    const PTX: &[u8] = include_bytes!("expr_proto.ptx");

    if indices.is_empty() {
        return Err(CudaRuntimeProbeError::InvalidInputLength(0));
    }
    let count = indices.len();
    let idx_bytes = count
        .checked_mul(std::mem::size_of::<u32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(count))?;
    let count_u64 = count as u64;

    let primary = resident.primary();
    primary.set_current()?;
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let htod_async = primary
        .cu_memcpy_htod_async
        .ok_or(CudaRuntimeProbeError::DriverLibraryUnavailable)?;
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let kernel_fn = primary.cached_function(c"gpu_db_resident_i64_minmax_at_indices", &ptx)?;
    let indices_dev = primary.lease_device_buffer(idx_bytes)?;
    let out = primary.lease_device_buffer(std::mem::size_of::<i64>())?;

    let init: i64 = if is_max { i64::MIN } else { i64::MAX };
    let op: u32 = u32::from(is_max);

    const BLOCK: u32 = 256;
    let grid = count_u64.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;
    let mut a0 = resident.device_ptr();
    let mut a1 = byte_offset;
    let mut a2 = indices_dev.ptr;
    let mut a3 = count_u64;
    let mut a4 = op;
    let mut a5 = out.ptr;
    let mut args = [
        (&mut a0 as *mut u64).cast::<c_void>(),
        (&mut a1 as *mut u64).cast::<c_void>(),
        (&mut a2 as *mut u64).cast::<c_void>(),
        (&mut a3 as *mut u64).cast::<c_void>(),
        (&mut a4 as *mut u32).cast::<c_void>(),
        (&mut a5 as *mut u64).cast::<c_void>(),
    ];
    launch_on_pooled_stream(resident, None, |stream, _scratch| {
        let rc = unsafe {
            htod_async(
                indices_dev.ptr,
                indices.as_ptr().cast::<c_void>(),
                idx_bytes,
                stream,
            )
        };
        if rc != 0 {
            return rc;
        }
        let rc = unsafe {
            htod_async(
                out.ptr,
                (&init as *const i64).cast::<c_void>(),
                std::mem::size_of::<i64>(),
                stream,
            )
        };
        if rc != 0 {
            return rc;
        }
        unsafe {
            cu_launch_kernel(
                kernel_fn,
                grid,
                1,
                1,
                BLOCK,
                1,
                1,
                0,
                stream,
                args.as_mut_ptr(),
                std::ptr::null_mut(),
            )
        }
    })?;
    let mut result = 0_i64;
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            (&mut result as *mut i64).cast::<c_void>(),
            out.ptr,
            std::mem::size_of::<i64>(),
        )
    })?;
    Ok(result)
}

/// MIN (`is_max=false`) / MAX (`is_max=true`) of a resident NUMERIC (i128 mantissa) column over a
/// filtered set of row indices, returned as the i128 mantissa (the operator axis, doc 19). No native
/// 128-bit atomic min/max, so the kernel runs a BOUNDED grid where each thread reduces its strided
/// slice to a local i128 partial; the host combines the (<= 16384) partials. `indices` must be
/// non-empty.
fn launch_cuda_resident_i128_minmax_partials_at_indices(
    resident: &CudaResidentDeviceMemory,
    byte_offset: u64,
    indices: &[u32],
    is_max: bool,
) -> Result<i128, CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    const PTX: &[u8] = include_bytes!("expr_proto.ptx");

    if indices.is_empty() {
        return Err(CudaRuntimeProbeError::InvalidInputLength(0));
    }
    let count = indices.len();
    let idx_bytes = count
        .checked_mul(std::mem::size_of::<u32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(count))?;
    let count_u64 = count as u64;

    let primary = resident.primary();
    primary.set_current()?;
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let htod_async = primary
        .cu_memcpy_htod_async
        .ok_or(CudaRuntimeProbeError::DriverLibraryUnavailable)?;
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let kernel_fn =
        primary.cached_function(c"gpu_db_resident_i128_minmax_partials_at_indices", &ptx)?;

    // Bounded grid: cap the partials count (and the host combine) at 64 * 256 = 16384.
    const BLOCK: u32 = 256;
    const MAX_GRID: u32 = 64;
    let grid = (count_u64.div_ceil(u64::from(BLOCK)).clamp(1, u64::from(MAX_GRID))) as u32;
    let num_threads = (grid * BLOCK) as usize;
    let partials_bytes = num_threads
        .checked_mul(std::mem::size_of::<i128>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(num_threads))?;
    let indices_dev = primary.lease_device_buffer(idx_bytes)?;
    let partials = primary.lease_device_buffer(partials_bytes)?;

    let op: u32 = u32::from(is_max);
    let mut a0 = resident.device_ptr();
    let mut a1 = byte_offset;
    let mut a2 = indices_dev.ptr;
    let mut a3 = count_u64;
    let mut a4 = op;
    let mut a5 = partials.ptr;
    let mut args = [
        (&mut a0 as *mut u64).cast::<c_void>(),
        (&mut a1 as *mut u64).cast::<c_void>(),
        (&mut a2 as *mut u64).cast::<c_void>(),
        (&mut a3 as *mut u64).cast::<c_void>(),
        (&mut a4 as *mut u32).cast::<c_void>(),
        (&mut a5 as *mut u64).cast::<c_void>(),
    ];
    launch_on_pooled_stream(resident, None, |stream, _scratch| {
        let rc = unsafe {
            htod_async(
                indices_dev.ptr,
                indices.as_ptr().cast::<c_void>(),
                idx_bytes,
                stream,
            )
        };
        if rc != 0 {
            return rc;
        }
        unsafe {
            cu_launch_kernel(
                kernel_fn,
                grid,
                1,
                1,
                BLOCK,
                1,
                1,
                0,
                stream,
                args.as_mut_ptr(),
                std::ptr::null_mut(),
            )
        }
    })?;
    let mut bytes = vec![0u8; partials_bytes];
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            bytes.as_mut_ptr().cast::<c_void>(),
            partials.ptr,
            partials_bytes,
        )
    })?;
    // Host-combine the bounded partials (idle threads wrote the identity, which min/max ignores).
    let mut result: Option<i128> = None;
    for chunk in bytes.chunks_exact(std::mem::size_of::<i128>()) {
        let value = i128::from_le_bytes(chunk.try_into().expect("16-byte chunk"));
        result = Some(match result {
            None => value,
            Some(acc) if is_max => acc.max(value),
            Some(acc) => acc.min(value),
        });
    }
    result.ok_or(CudaRuntimeProbeError::InvalidInputLength(0))
}

/// SUM of a resident NUMERIC (i128 mantissa) column over a filtered set of row indices, as the i128
/// mantissa with CHECKED i128 overflow (the operator axis, doc 19). Bounded-grid partials reduction:
/// each thread sums its strided slice into a local i128 (and sets a device overflow flag if any of
/// its adds overflows i128); the host checked-combines the partials. Either the device flag OR a
/// host-combine overflow yields `NumericFieldOverflow` (PG `numeric field overflow`). `indices`
/// must be non-empty.
fn launch_cuda_resident_i128_sum_partials_at_indices(
    resident: &CudaResidentDeviceMemory,
    byte_offset: u64,
    indices: &[u32],
) -> Result<i128, CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    type CuMemsetD8Async = unsafe extern "C" fn(u64, u8, usize, *mut c_void) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    const PTX: &[u8] = include_bytes!("expr_proto.ptx");

    if indices.is_empty() {
        return Err(CudaRuntimeProbeError::InvalidInputLength(0));
    }
    let count = indices.len();
    let idx_bytes = count
        .checked_mul(std::mem::size_of::<u32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(count))?;
    let count_u64 = count as u64;

    let primary = resident.primary();
    primary.set_current()?;
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let htod_async = primary
        .cu_memcpy_htod_async
        .ok_or(CudaRuntimeProbeError::DriverLibraryUnavailable)?;
    let cu_memset_d8_async = unsafe {
        resident
            .lib()
            .get::<CuMemsetD8Async>(b"cuMemsetD8Async\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let kernel_fn =
        primary.cached_function(c"gpu_db_resident_i128_sum_partials_at_indices", &ptx)?;

    const BLOCK: u32 = 256;
    const MAX_GRID: u32 = 64;
    let grid = (count_u64.div_ceil(u64::from(BLOCK)).clamp(1, u64::from(MAX_GRID))) as u32;
    let num_threads = (grid * BLOCK) as usize;
    let partials_bytes = num_threads
        .checked_mul(std::mem::size_of::<i128>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(num_threads))?;
    let indices_dev = primary.lease_device_buffer(idx_bytes)?;
    let partials = primary.lease_device_buffer(partials_bytes)?;
    let flag = primary.lease_device_buffer(std::mem::size_of::<u32>())?;

    let mut a0 = resident.device_ptr();
    let mut a1 = byte_offset;
    let mut a2 = indices_dev.ptr;
    let mut a3 = count_u64;
    let mut a4 = partials.ptr;
    let mut a5 = flag.ptr;
    let mut args = [
        (&mut a0 as *mut u64).cast::<c_void>(),
        (&mut a1 as *mut u64).cast::<c_void>(),
        (&mut a2 as *mut u64).cast::<c_void>(),
        (&mut a3 as *mut u64).cast::<c_void>(),
        (&mut a4 as *mut u64).cast::<c_void>(),
        (&mut a5 as *mut u64).cast::<c_void>(),
    ];
    launch_on_pooled_stream(resident, None, |stream, _scratch| {
        let rc = unsafe {
            htod_async(
                indices_dev.ptr,
                indices.as_ptr().cast::<c_void>(),
                idx_bytes,
                stream,
            )
        };
        if rc != 0 {
            return rc;
        }
        let rc = unsafe { cu_memset_d8_async(flag.ptr, 0, std::mem::size_of::<u32>(), stream) };
        if rc != 0 {
            return rc;
        }
        unsafe {
            cu_launch_kernel(
                kernel_fn,
                grid,
                1,
                1,
                BLOCK,
                1,
                1,
                0,
                stream,
                args.as_mut_ptr(),
                std::ptr::null_mut(),
            )
        }
    })?;
    let mut flag_host = 0u32;
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            (&mut flag_host as *mut u32).cast::<c_void>(),
            flag.ptr,
            std::mem::size_of::<u32>(),
        )
    })?;
    if flag_host != 0 {
        return Err(CudaRuntimeProbeError::NumericFieldOverflow);
    }
    let mut bytes = vec![0u8; partials_bytes];
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            bytes.as_mut_ptr().cast::<c_void>(),
            partials.ptr,
            partials_bytes,
        )
    })?;
    // Host checked-combine of the bounded partials (idle threads wrote 0). A combine overflow is the
    // same PG `numeric field overflow` as a per-thread overflow.
    let mut sum: i128 = 0;
    for chunk in bytes.chunks_exact(std::mem::size_of::<i128>()) {
        let value = i128::from_le_bytes(chunk.try_into().expect("16-byte chunk"));
        sum = sum
            .checked_add(value)
            .ok_or(CudaRuntimeProbeError::NumericFieldOverflow)?;
    }
    Ok(sum)
}

/// Outcome of [`CudaResidentDeviceMemory::hash_join_inner_i64`]: the matched row-index pairs, or a
/// signal that the build-side join key is not unique (N:N many-to-many fan-out is a follow-up).
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum HashJoinOutcome {
    /// `build_idxs[i]` joins `probe_idxs[i]` (parallel vectors of absolute resident row indices).
    Pairs {
        build_idxs: Vec<u32>,
        probe_idxs: Vec<u32>,
    },
    /// A build-side join key repeated -> the unique-build-key inner join can't represent it yet.
    DuplicateBuildKey,
}

/// One GROUP BY output group: the int4 key, the row COUNT, and the SUM of the value column.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GroupByI32Row {
    /// Group key, widened to i64 (int4 keys are sign-extended; int8 keys are exact). The engine
    /// narrows back to Int4 for an int4 GROUP BY column and keeps Int8 for an int8 one.
    pub key: i64,
    pub count: u64,
    pub sum: i64,
    /// High 64 bits of the per-group SUM when the value is int8 (the sum is accumulated as i128:
    /// `sum_hi:sum`). Zero for int4 sums (which fit `sum` alone). The engine combines them into an
    /// i128 -> numeric for `SUM(bigint)` / `AVG(bigint)`.
    pub sum_hi: i64,
    /// MIN / MAX of the value column per group (sign-extended into i64 slots; the engine narrows back
    /// to int4 / keeps int8). For COUNT(*) (value == key) they are ignored.
    pub min: i64,
    pub max: i64,
    /// High 64 bits of the per-group i128 MIN / MAX when the value is NUMERIC (stored as
    /// `min_hi:min` / `max_hi:max`). Zero for int4 / int8 MIN/MAX (which use `min` / `max` alone).
    pub min_hi: i64,
    pub max_hi: i64,
    /// MIN / MAX of a UUID value column per group, in canonical (memcmp / big-endian) byte order
    /// (`min_uuid[0]` is the first textual uuid byte). Populated only for a `MIN`/`MAX` over a uuid
    /// value (the b128 CAS-loop kernel); `[0; 16]` for every other aggregate/type.
    pub min_uuid: [u8; 16],
    pub max_uuid: [u8; 16],
    /// GROUP BY key when the key column is i128-wide (NUMERIC mantissa or UUID bytes, claimed via
    /// `atom.cas.b128`). The engine reconstructs `SqlValue::Numeric` (mantissa = this) or
    /// `SqlValue::Uuid` (`this.to_le_bytes()` = canonical bytes). `0` for i64-key paths.
    pub key_i128: i128,
}

/// GROUP BY an int4 `key` column, aggregating COUNT(*) and SUM(int4 `sum`) over a filtered set of row
/// indices, via GPU hash aggregation (the operator axis, doc 19). Allocates an open-addressing hash
/// table sized > the row count (so probing terminates), inits slot_keys to EMPTY and the count/sum
/// accumulators to 0, runs the group-by kernel, D2Hs the slots, and host-compacts the occupied groups.
/// For COUNT(*) pass `sum_byte_offset = key_byte_offset` (the summed value is then ignored).
/// `indices` may be empty (-> no groups). NB: this is the correct baseline; a shared-memory two-level
/// kernel (far less atomic contention at low cardinality) and a GPU slot-compaction are follow-ons.
#[allow(unused_assignments)] // f0/f2 are re-read via the raw fill-arg pointers
#[allow(clippy::too_many_arguments)] // kernel launcher: offsets + per-column-type layout flags
fn launch_cuda_group_by_i32_count_sum(
    resident: &CudaResidentDeviceMemory,
    key_byte_offset: u64,
    sum_byte_offset: u64,
    indices: &[u32],
    kernel: &'static CStr,
    value_is_int8: bool,
    key_is_int8: bool,
    value_is_numeric: bool,
    value_is_uuid: bool,
    key_is_i128: bool,
    key_is_text: bool,
    key_offsets_off: u64,
    key_bytes_off: u64,
    value_is_text: bool,
    value_offsets_off: u64,
    value_bytes_off: u64,
    key_base_override: u64,
    value_base_override: u64,
    // General all-fixed COMPOSITE key: comp_w > 0 -> the key is a `comp_w`-byte wide key per row in
    // key_base_override (built by gpu_db_build_wide_key); grouped via a (rep_idx, hash) b128 claim.
    comp_w: u64,
    // General COMPOSITE with TEXT members: n_text members, each (offsets_off, bytes_off) [16 bytes] in
    // text_desc_ptr (a device buffer the CALLER holds alive). 0 = no text members.
    n_text: u64,
    text_desc_ptr: u64,
) -> Result<Vec<GroupByI32Row>, CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    type CuMemsetD8Async = unsafe extern "C" fn(u64, u8, usize, *mut c_void) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    const PTX: &[u8] = include_bytes!("expr_proto.ptx");
    const EMPTY: i64 = i64::MIN;

    if indices.is_empty() {
        return Ok(Vec::new());
    }
    let count = indices.len();
    let idx_bytes = count
        .checked_mul(std::mem::size_of::<u32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(count))?;
    let count_u64 = count as u64;
    // Power-of-two table sized > 2x the rows so linear probing always finds a free slot / the key.
    let nslots = count
        .checked_mul(2)
        .and_then(usize::checked_next_power_of_two)
        .map(|n| n.max(16))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(count))?;
    // One extra slot beyond the power-of-two hash range, dedicated to the i64::MIN key (which
    // collides with the EMPTY sentinel and so cannot live in the hash table). The single-level kernel
    // routes that key to index nslots; for int4 keys (no i64::MIN) it stays empty. Always allocated.
    let alloc_slots = nslots + 1;
    let alloc_slots_u64 = alloc_slots as u64;
    let slot_bytes = alloc_slots
        .checked_mul(std::mem::size_of::<i64>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(nslots))?;
    let mask = (nslots - 1) as u64;

    let primary = resident.primary();
    primary.set_current()?;
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let htod_async = primary
        .cu_memcpy_htod_async
        .ok_or(CudaRuntimeProbeError::DriverLibraryUnavailable)?;
    let cu_memset_d8_async = unsafe {
        resident
            .lib()
            .get::<CuMemsetD8Async>(b"cuMemsetD8Async\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let fill_fn = primary.cached_function(c"gpu_db_fill_i64", &ptx)?;
    // Two-level (shared-mem local aggregation -> global merge): far less global-atomic contention at
    // low cardinality. The single-level `gpu_db_group_by_i32_count_sum` stays as the reference kernel.
    let group_fn = primary.cached_function(kernel, &ptx)?;
    let indices_dev = primary.lease_device_buffer(idx_bytes)?;
    let slot_keys = primary.lease_device_buffer(slot_bytes)?;
    let slot_count = primary.lease_device_buffer(slot_bytes)?;
    let slot_sum = primary.lease_device_buffer(slot_bytes)?;
    // MIN/MAX slots: the single-level kernel fills these per group; the two-level kernel ignores them
    // (they stay at the i64::MAX/MIN identity). Always allocated so the launch signature is uniform.
    let slot_min = primary.lease_device_buffer(slot_bytes)?;
    let slot_max = primary.lease_device_buffer(slot_bytes)?;
    // High 64 bits of the i128 per-group SUM for int8 values (zeroed; the int4 path leaves it 0).
    let slot_sum_hi = primary.lease_device_buffer(slot_bytes)?;
    // A single global flag the kernel `red.global.or`s when a numeric SUM overflows i128 (PG numeric
    // field overflow). Zeroed before launch; only the numeric path ever writes it.
    let overflow_flag = primary.lease_device_buffer(std::mem::size_of::<u64>())?;
    // Numeric MIN/MAX i128 high limbs (pass 1) + a row_slots scratch: row_slots[i] = the slot the
    // i-th row claimed, written by pass 1's numeric branch so the lock-free pass-2 kernel can resolve
    // the i128 LOW limb among the high-limb ties. int4/int8/two-level paths leave these unused.
    let slot_min_hi = primary.lease_device_buffer(slot_bytes)?;
    let slot_max_hi = primary.lease_device_buffer(slot_bytes)?;
    let row_slots_bytes = count
        .checked_mul(std::mem::size_of::<u32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(count))?;
    let row_slots = primary.lease_device_buffer(row_slots_bytes)?;
    // UUID MIN/MAX slots: one b128 (16 bytes) per slot. The single-level kernel's uuid branch CAS-loops
    // into these; every other path leaves them untouched. Always allocated (uniform launch signature),
    // but only memset + D2H'd when the value is a uuid. Identities: MIN = 0xFF..FF (the largest uuid),
    // MAX = 0x00..00 -- so any real uuid replaces the identity on its first CAS.
    let uuid_slot_bytes = alloc_slots
        .checked_mul(16)
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(alloc_slots))?;
    let slot_min_uuid = primary.lease_device_buffer(uuid_slot_bytes)?;
    let slot_max_uuid = primary.lease_device_buffer(uuid_slot_bytes)?;
    // i128 GROUP BY key slots: one b128 (16 bytes) per slot, claimed via atom.cas.b128. Only the
    // numeric/uuid-key path reads/writes these (filled to EMPTY128 = i128::MIN then); leased always for
    // a uniform launch signature. Shares the alloc_slots*16 size with the uuid value slots.
    let slot_keys_i128 = primary.lease_device_buffer(uuid_slot_bytes)?;
    // Text GROUP-BY keys also live in slot_keys_i128 (b128 = (rep_row_idx, text_hash), claimed via
    // atom.cas.b128 with a full-text verify-on-lost-CAS), so the EMPTY128 fill is needed for them too.
    let fill_i128_fn = if key_is_i128 || key_is_text || comp_w > 0 || n_text > 0 {
        Some(primary.cached_function(c"gpu_db_fill_i128", &ptx)?)
    } else {
        None
    };

    const BLOCK: u32 = 256;
    // Fills cover alloc_slots (nslots + the dedicated i64::MIN slot) so that slot is initialized too.
    let fill_grid = alloc_slots_u64.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;
    let group_grid = count_u64.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;

    // Numeric MIN/MAX stores an i128, so its identities are the i128 extremes split into limbs:
    // MIN = i128::MAX (hi i64::MAX, lo u64::MAX), MAX = i128::MIN (hi i64::MIN, lo 0). int4/int8 keep
    // the s64 identities in the LOW limb (hi unused -> 0).
    // Text MIN/MAX stores a ROW INDEX (not a value); both slots start at the EMPTY sentinel u64::MAX
    // (-1) so the first row of each group claims via CAS and later rows compare lexicographically.
    let min_lo_id: u64 = if value_is_text || value_is_numeric {
        u64::MAX
    } else {
        i64::MAX as u64
    };
    let max_lo_id: u64 = if value_is_text {
        u64::MAX
    } else if value_is_numeric {
        0
    } else {
        i64::MIN as u64
    };
    let min_hi_id: u64 = if value_is_numeric { i64::MAX as u64 } else { 0 };
    let max_hi_id: u64 = if value_is_numeric { i64::MIN as u64 } else { 0 };

    // One fill-arg set, mutated between the 3 slot_keys / slot_min / slot_max fills (cuLaunchKernel
    // copies the arg values at call time, so re-launching after mutating f0/f2 is safe).
    let mut f0 = slot_keys.ptr;
    let mut f1 = alloc_slots_u64;
    let mut f2 = EMPTY as u64;
    let mut fill_args = [
        (&mut f0 as *mut u64).cast::<c_void>(),
        (&mut f1 as *mut u64).cast::<c_void>(),
        (&mut f2 as *mut u64).cast::<c_void>(),
    ];
    let mut a0 = resident.device_ptr();
    let mut a1 = key_byte_offset;
    let mut a2 = sum_byte_offset;
    let mut a3 = indices_dev.ptr;
    let mut a4 = count_u64;
    let mut a5 = mask;
    let mut a6 = slot_keys.ptr;
    let mut a7 = slot_count.ptr;
    let mut a8 = slot_sum.ptr;
    let mut a9 = slot_min.ptr;
    let mut a10 = slot_max.ptr;
    let mut a11 = u64::from(value_is_int8);
    let mut a12 = slot_sum_hi.ptr;
    let mut a13 = u64::from(key_is_int8);
    let mut a14 = u64::from(value_is_numeric);
    let mut a15 = overflow_flag.ptr;
    let mut a16 = slot_min_hi.ptr;
    let mut a17 = slot_max_hi.ptr;
    let mut a18 = row_slots.ptr;
    let mut a19 = u64::from(value_is_uuid);
    let mut a20 = slot_min_uuid.ptr;
    let mut a21 = slot_max_uuid.ptr;
    let mut a22 = u64::from(key_is_i128);
    let mut a23 = slot_keys_i128.ptr;
    let mut a24 = u64::from(key_is_text);
    let mut a25 = key_offsets_off;
    let mut a26 = key_bytes_off;
    let mut a27 = u64::from(value_is_text);
    let mut a28 = value_offsets_off;
    let mut a29 = value_bytes_off;
    let mut a30 = key_base_override;
    let mut a31 = value_base_override;
    let mut a32 = comp_w;
    let mut a33 = n_text;
    let mut a34 = text_desc_ptr;
    // gpu_db_fill_i128(slot_keys_i128, alloc_slots, lo=0, hi=i64::MIN) -> EMPTY128 = i128::MIN.
    let mut g0 = slot_keys_i128.ptr;
    let mut g1 = alloc_slots_u64;
    let mut g2 = 0u64;
    let mut g3 = i64::MIN as u64;
    let mut fill128_args = [
        (&mut g0 as *mut u64).cast::<c_void>(),
        (&mut g1 as *mut u64).cast::<c_void>(),
        (&mut g2 as *mut u64).cast::<c_void>(),
        (&mut g3 as *mut u64).cast::<c_void>(),
    ];
    let mut group_args = [
        (&mut a0 as *mut u64).cast::<c_void>(),
        (&mut a1 as *mut u64).cast::<c_void>(),
        (&mut a2 as *mut u64).cast::<c_void>(),
        (&mut a3 as *mut u64).cast::<c_void>(),
        (&mut a4 as *mut u64).cast::<c_void>(),
        (&mut a5 as *mut u64).cast::<c_void>(),
        (&mut a6 as *mut u64).cast::<c_void>(),
        (&mut a7 as *mut u64).cast::<c_void>(),
        (&mut a8 as *mut u64).cast::<c_void>(),
        (&mut a9 as *mut u64).cast::<c_void>(),
        (&mut a10 as *mut u64).cast::<c_void>(),
        (&mut a11 as *mut u64).cast::<c_void>(),
        (&mut a12 as *mut u64).cast::<c_void>(),
        (&mut a13 as *mut u64).cast::<c_void>(),
        (&mut a14 as *mut u64).cast::<c_void>(),
        (&mut a15 as *mut u64).cast::<c_void>(),
        (&mut a16 as *mut u64).cast::<c_void>(),
        (&mut a17 as *mut u64).cast::<c_void>(),
        (&mut a18 as *mut u64).cast::<c_void>(),
        (&mut a19 as *mut u64).cast::<c_void>(),
        (&mut a20 as *mut u64).cast::<c_void>(),
        (&mut a21 as *mut u64).cast::<c_void>(),
        (&mut a22 as *mut u64).cast::<c_void>(),
        (&mut a23 as *mut u64).cast::<c_void>(),
        (&mut a24 as *mut u64).cast::<c_void>(),
        (&mut a25 as *mut u64).cast::<c_void>(),
        (&mut a26 as *mut u64).cast::<c_void>(),
        (&mut a27 as *mut u64).cast::<c_void>(),
        (&mut a28 as *mut u64).cast::<c_void>(),
        (&mut a29 as *mut u64).cast::<c_void>(),
        (&mut a30 as *mut u64).cast::<c_void>(),
        (&mut a31 as *mut u64).cast::<c_void>(),
        (&mut a32 as *mut u64).cast::<c_void>(),
        (&mut a33 as *mut u64).cast::<c_void>(),
        (&mut a34 as *mut u64).cast::<c_void>(),
    ];
    // Pass 2 (numeric MIN/MAX only): a second, LOCK-FREE kernel that resolves the i128 low limb after
    // pass 1 (the main kernel) finalized the high limbs. Cached + its args built only for numeric.
    let pass2_fn = if value_is_numeric {
        Some(primary.cached_function(c"gpu_db_group_by_numeric_minmax_lo", &ptx)?)
    } else {
        None
    };
    let mut q0 = resident.device_ptr();
    let mut q1 = sum_byte_offset;
    let mut q2 = indices_dev.ptr;
    let mut q3 = count_u64;
    let mut q4 = row_slots.ptr;
    let mut q5 = slot_min.ptr;
    let mut q6 = slot_max.ptr;
    let mut q7 = slot_min_hi.ptr;
    let mut q8 = slot_max_hi.ptr;
    let mut pass2_args = [
        (&mut q0 as *mut u64).cast::<c_void>(),
        (&mut q1 as *mut u64).cast::<c_void>(),
        (&mut q2 as *mut u64).cast::<c_void>(),
        (&mut q3 as *mut u64).cast::<c_void>(),
        (&mut q4 as *mut u64).cast::<c_void>(),
        (&mut q5 as *mut u64).cast::<c_void>(),
        (&mut q6 as *mut u64).cast::<c_void>(),
        (&mut q7 as *mut u64).cast::<c_void>(),
        (&mut q8 as *mut u64).cast::<c_void>(),
    ];
    launch_on_pooled_stream(resident, None, |stream, _scratch| {
        let rc = unsafe {
            htod_async(
                indices_dev.ptr,
                indices.as_ptr().cast::<c_void>(),
                idx_bytes,
                stream,
            )
        };
        if rc != 0 {
            return rc;
        }
        let rc = unsafe { cu_memset_d8_async(slot_count.ptr, 0, slot_bytes, stream) };
        if rc != 0 {
            return rc;
        }
        let rc = unsafe { cu_memset_d8_async(slot_sum.ptr, 0, slot_bytes, stream) };
        if rc != 0 {
            return rc;
        }
        let rc = unsafe { cu_memset_d8_async(slot_sum_hi.ptr, 0, slot_bytes, stream) };
        if rc != 0 {
            return rc;
        }
        let rc = unsafe {
            cu_memset_d8_async(overflow_flag.ptr, 0, std::mem::size_of::<u64>(), stream)
        };
        if rc != 0 {
            return rc;
        }
        // UUID MIN/MAX identities: MIN slot = 0xFF..FF (largest uuid), MAX slot = 0x00..00 (smallest).
        // Only the uuid path reads/writes these, so only init them then (the buffers are always leased
        // for a uniform launch signature but stay untouched otherwise).
        if value_is_uuid {
            let rc =
                unsafe { cu_memset_d8_async(slot_min_uuid.ptr, 0xFF, uuid_slot_bytes, stream) };
            if rc != 0 {
                return rc;
            }
            let rc =
                unsafe { cu_memset_d8_async(slot_max_uuid.ptr, 0x00, uuid_slot_bytes, stream) };
            if rc != 0 {
                return rc;
            }
        }
        // i128 GROUP BY keys: fill slot_keys_i128 = EMPTY128 (i128::MIN) before the claim runs.
        if let Some(f) = fill_i128_fn {
            let rc = unsafe {
                cu_launch_kernel(
                    f, fill_grid, 1, 1, BLOCK, 1, 1, 0, stream,
                    fill128_args.as_mut_ptr(), std::ptr::null_mut(),
                )
            };
            if rc != 0 {
                return rc;
            }
        }
        // (row_slots needs no init: pass 1 writes every row's slot before pass 2 reads it.)
        // fill slot_keys = EMPTY
        let rc = unsafe {
            cu_launch_kernel(
                fill_fn, fill_grid, 1, 1, BLOCK, 1, 1, 0, stream,
                fill_args.as_mut_ptr(), std::ptr::null_mut(),
            )
        };
        if rc != 0 {
            return rc;
        }
        // fill slot_min (low limb) = the MIN identity (s64 i64::MAX, or numeric i128::MAX low = u64::MAX)
        f0 = slot_min.ptr;
        f2 = min_lo_id;
        let rc = unsafe {
            cu_launch_kernel(
                fill_fn, fill_grid, 1, 1, BLOCK, 1, 1, 0, stream,
                fill_args.as_mut_ptr(), std::ptr::null_mut(),
            )
        };
        if rc != 0 {
            return rc;
        }
        // fill slot_max (low limb) = the MAX identity (s64 i64::MIN, or numeric i128::MIN low = 0)
        f0 = slot_max.ptr;
        f2 = max_lo_id;
        let rc = unsafe {
            cu_launch_kernel(
                fill_fn, fill_grid, 1, 1, BLOCK, 1, 1, 0, stream,
                fill_args.as_mut_ptr(), std::ptr::null_mut(),
            )
        };
        if rc != 0 {
            return rc;
        }
        // fill slot_min_hi / slot_max_hi (numeric MIN/MAX high limbs; 0 for int4/int8).
        f0 = slot_min_hi.ptr;
        f2 = min_hi_id;
        let rc = unsafe {
            cu_launch_kernel(
                fill_fn, fill_grid, 1, 1, BLOCK, 1, 1, 0, stream,
                fill_args.as_mut_ptr(), std::ptr::null_mut(),
            )
        };
        if rc != 0 {
            return rc;
        }
        f0 = slot_max_hi.ptr;
        f2 = max_hi_id;
        let rc = unsafe {
            cu_launch_kernel(
                fill_fn, fill_grid, 1, 1, BLOCK, 1, 1, 0, stream,
                fill_args.as_mut_ptr(), std::ptr::null_mut(),
            )
        };
        if rc != 0 {
            return rc;
        }
        let rc = unsafe {
            cu_launch_kernel(
                group_fn, group_grid, 1, 1, BLOCK, 1, 1, 0, stream,
                group_args.as_mut_ptr(), std::ptr::null_mut(),
            )
        };
        if rc != 0 {
            return rc;
        }
        // Pass 2 (numeric MIN/MAX): resolve the i128 low limb lock-free, on the same stream.
        if let Some(f) = pass2_fn {
            return unsafe {
                cu_launch_kernel(
                    f, group_grid, 1, 1, BLOCK, 1, 1, 0, stream,
                    pass2_args.as_mut_ptr(), std::ptr::null_mut(),
                )
            };
        }
        rc
    })?;

    // Sized alloc_slots (= nslots + the dedicated i64::MIN slot) -- the D2H copies slot_bytes bytes.
    let mut keys = vec![0i64; alloc_slots];
    let mut counts = vec![0u64; alloc_slots];
    let mut sums = vec![0i64; alloc_slots];
    let mut sum_his = vec![0i64; alloc_slots];
    let mut mins = vec![0i64; alloc_slots];
    let mut maxs = vec![0i64; alloc_slots];
    let mut min_his = vec![0i64; alloc_slots];
    let mut max_his = vec![0i64; alloc_slots];
    check_cuda(unsafe {
        cu_memcpy_dtoh(keys.as_mut_ptr().cast::<c_void>(), slot_keys.ptr, slot_bytes)
    })?;
    check_cuda(unsafe {
        cu_memcpy_dtoh(counts.as_mut_ptr().cast::<c_void>(), slot_count.ptr, slot_bytes)
    })?;
    check_cuda(unsafe {
        cu_memcpy_dtoh(sums.as_mut_ptr().cast::<c_void>(), slot_sum.ptr, slot_bytes)
    })?;
    check_cuda(unsafe {
        cu_memcpy_dtoh(sum_his.as_mut_ptr().cast::<c_void>(), slot_sum_hi.ptr, slot_bytes)
    })?;
    check_cuda(unsafe {
        cu_memcpy_dtoh(mins.as_mut_ptr().cast::<c_void>(), slot_min.ptr, slot_bytes)
    })?;
    check_cuda(unsafe {
        cu_memcpy_dtoh(maxs.as_mut_ptr().cast::<c_void>(), slot_max.ptr, slot_bytes)
    })?;
    check_cuda(unsafe {
        cu_memcpy_dtoh(min_his.as_mut_ptr().cast::<c_void>(), slot_min_hi.ptr, slot_bytes)
    })?;
    check_cuda(unsafe {
        cu_memcpy_dtoh(max_his.as_mut_ptr().cast::<c_void>(), slot_max_hi.ptr, slot_bytes)
    })?;
    // UUID MIN/MAX: copy the b128 result slots back only on the uuid path (empty vecs otherwise, so the
    // accessor returns [0; 16] and adds no D2H to the common path).
    let (mins_uuid, maxs_uuid) = if value_is_uuid {
        let mut mn = vec![0u8; uuid_slot_bytes];
        let mut mx = vec![0u8; uuid_slot_bytes];
        check_cuda(unsafe {
            cu_memcpy_dtoh(mn.as_mut_ptr().cast::<c_void>(), slot_min_uuid.ptr, uuid_slot_bytes)
        })?;
        check_cuda(unsafe {
            cu_memcpy_dtoh(mx.as_mut_ptr().cast::<c_void>(), slot_max_uuid.ptr, uuid_slot_bytes)
        })?;
        (mn, mx)
    } else {
        (Vec::new(), Vec::new())
    };
    // i128 / text GROUP BY keys: copy the b128 key slots back. Each slot's 16 LE bytes are the i128 key
    // (numeric mantissa or uuid bytes), or for a text key the b128 (hi=text hash, lo=representative row
    // index), claimed via atom.cas.b128.
    let keys_i128: Vec<i128> = if key_is_i128 || key_is_text || comp_w > 0 || n_text > 0 {
        let mut k = vec![0i128; alloc_slots];
        check_cuda(unsafe {
            cu_memcpy_dtoh(k.as_mut_ptr().cast::<c_void>(), slot_keys_i128.ptr, uuid_slot_bytes)
        })?;
        k
    } else {
        Vec::new()
    };
    // Rebuild a canonical-order uuid from a slot's 16 device bytes. The kernel stored the b128 as
    // `(uhi << 64) | ulo` with uhi = uuid bytes 0-7 big-endian and ulo = bytes 8-15 big-endian; in LE
    // device memory that is the uuid fully byte-reversed. from_le_bytes recovers ulo/uhi and to_be_bytes
    // restores the canonical (memcmp / textual) order. Returns [0; 16] when not a uuid aggregate.
    let uuid_at = |buf: &[u8], slot: usize| -> [u8; 16] {
        if buf.is_empty() {
            return [0u8; 16];
        }
        let b = &buf[slot * 16..slot * 16 + 16];
        let ulo = u64::from_le_bytes(b[0..8].try_into().unwrap());
        let uhi = u64::from_le_bytes(b[8..16].try_into().unwrap());
        let mut out = [0u8; 16];
        out[0..8].copy_from_slice(&uhi.to_be_bytes());
        out[8..16].copy_from_slice(&ulo.to_be_bytes());
        out
    };
    // Host-compact the occupied slots (slot_keys != EMPTY). A GPU stream-compaction is a follow-on.
    // min/max are the per-group values from the single-level kernel; for the two-level kernel (COUNT/
    // SUM/AVG only) they stay at the i64::MAX/MIN identity and the engine ignores them. sum_hi is the
    // i128 high limb for int8 sums (0 for int4).
    let mut groups = Vec::new();
    for i in 0..nslots {
        // Occupancy: i128 + text keys live in slot_keys_i128 (EMPTY128 = i128::MIN); i64 keys in
        // slot_keys (EMPTY = i64::MIN). The i128/text path never writes the i64 slot_keys, so it must
        // test its own. (A text key never aliases i128::MIN -- the kernel remaps hash i64::MIN->0.)
        let occupied = if key_is_i128 || key_is_text || comp_w > 0 || n_text > 0 {
            keys_i128[i] != i128::MIN
        } else {
            keys[i] != EMPTY
        };
        if occupied {
            groups.push(GroupByI32Row {
                key: keys[i],
                count: counts[i],
                sum: sums[i],
                sum_hi: sum_his[i],
                min: mins[i],
                max: maxs[i],
                min_hi: min_his[i],
                max_hi: max_his[i],
                min_uuid: uuid_at(&mins_uuid, i),
                max_uuid: uuid_at(&maxs_uuid, i),
                key_i128: if key_is_i128 || key_is_text || comp_w > 0 || n_text > 0 {
                    keys_i128[i]
                } else {
                    0
                },
            });
        }
    }
    // The dedicated slot (index nslots) holds the i64::MIN key (== EMPTY, so it can't be detected by
    // the sentinel test above); it is occupied iff its count > 0. Empty for int4 keys.
    if counts[nslots] > 0 {
        groups.push(GroupByI32Row {
            key: i64::MIN,
            count: counts[nslots],
            sum: sums[nslots],
            sum_hi: sum_his[nslots],
            min: mins[nslots],
            max: maxs[nslots],
            min_hi: min_his[nslots],
            max_hi: max_his[nslots],
            min_uuid: uuid_at(&mins_uuid, nslots),
            max_uuid: uuid_at(&maxs_uuid, nslots),
            // The dedicated slot's i128 key (when key_is_i128) is EMPTY128 itself = i128::MIN (the
            // kernel routes that key here without writing slot_keys_i128). 0 for the i64-key paths.
            key_i128: if key_is_i128 { i128::MIN } else { 0 },
        });
    }
    // A numeric SUM that overflowed i128 in any group/thread set this flag on-device -> PG numeric
    // field overflow (never silently wrapped). Checked after the kernel like the scalar numeric SUM.
    let mut overflow = 0u64;
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            (&mut overflow as *mut u64).cast::<c_void>(),
            overflow_flag.ptr,
            std::mem::size_of::<u64>(),
        )
    })?;
    if overflow != 0 {
        return Err(CudaRuntimeProbeError::NumericFieldOverflow);
    }
    Ok(groups)
}

/// Benchmark-only: time JUST the GROUP BY KERNEL (excluding the per-call alloc / H2D / D2H / host
/// compaction that dominate the end-to-end latency) via CUDA events, returning the MIN over `runs`
/// kernel launches plus the result rows (for a correctness check). Sets up once; per run resets the
/// global table (fill + memset) UNTIMED, then events bracket only the group kernel. Null stream.
#[allow(unused_assignments)] // f0/f2 are re-read via the raw fill-arg pointers
fn launch_cuda_group_by_kernel_timed(
    resident: &CudaResidentDeviceMemory,
    key_byte_offset: u64,
    sum_byte_offset: u64,
    indices: &[u32],
    kernel: &'static CStr,
    runs: u32,
) -> Result<(Vec<GroupByI32Row>, f32), CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void, u32, u32, u32, u32, u32, u32, u32, *mut c_void, *mut *mut c_void, *mut *mut c_void,
    ) -> i32;
    type CuMemsetD8 = unsafe extern "C" fn(u64, u8, usize) -> i32;
    type CuMemcpyHtoD = unsafe extern "C" fn(u64, *const c_void, usize) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    type CuStreamSync = unsafe extern "C" fn(*mut c_void) -> i32;
    const PTX: &[u8] = include_bytes!("expr_proto.ptx");
    const EMPTY: i64 = i64::MIN;

    if indices.is_empty() {
        return Ok((Vec::new(), 0.0));
    }
    let count = indices.len();
    let idx_bytes = std::mem::size_of_val(indices);
    let count_u64 = count as u64;
    let nslots = (count * 2).next_power_of_two().max(16);
    let slot_bytes = nslots * std::mem::size_of::<i64>();
    let mask = (nslots - 1) as u64;
    let nslots_u64 = nslots as u64;

    let primary = resident.primary();
    primary.set_current()?;
    let cu_launch = unsafe {
        *resident.lib().get::<CuLaunchKernel>(b"cuLaunchKernel\0").map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memset = unsafe {
        *resident
            .lib()
            .get::<CuMemsetD8>(b"cuMemsetD8_v2\0")
            .or_else(|_| resident.lib().get::<CuMemsetD8>(b"cuMemsetD8\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_htod = unsafe {
        *resident
            .lib()
            .get::<CuMemcpyHtoD>(b"cuMemcpyHtoD_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyHtoD>(b"cuMemcpyHtoD\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_dtoh = unsafe {
        *resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_stream_sync = unsafe {
        *resident.lib().get::<CuStreamSync>(b"cuStreamSynchronize\0").map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };

    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let fill_fn = primary.cached_function(c"gpu_db_fill_i64", &ptx)?;
    let group_fn = primary.cached_function(kernel, &ptx)?;
    let indices_dev = primary.lease_device_buffer(idx_bytes)?;
    let slot_keys = primary.lease_device_buffer(slot_bytes)?;
    let slot_count = primary.lease_device_buffer(slot_bytes)?;
    let slot_sum = primary.lease_device_buffer(slot_bytes)?;
    // min/max slots: the single-level kernel writes them (it dereferences the params); the two-level
    // ignores them. Real buffers required so the single-level kernel does not write to a stray pointer.
    let slot_min = primary.lease_device_buffer(slot_bytes)?;
    let slot_max = primary.lease_device_buffer(slot_bytes)?;
    // slot_sum_hi + overflow_flag + slot_min_hi/max_hi/row_slots: required so the 19-param kernel has
    // valid pointers; unused by the int4 bench (it never takes the int8/numeric branches that write them).
    let slot_sum_hi = primary.lease_device_buffer(slot_bytes)?;
    let overflow_flag = primary.lease_device_buffer(std::mem::size_of::<u64>())?;
    let slot_min_hi = primary.lease_device_buffer(slot_bytes)?;
    let slot_max_hi = primary.lease_device_buffer(slot_bytes)?;
    let row_slots = primary.lease_device_buffer(count.max(1) * std::mem::size_of::<u32>())?;
    // UUID MIN/MAX slots (b128, 16 bytes/slot): valid pointers so the 27-param kernel has no stray arg.
    // The int4 bench never takes the uuid branch (value_is_uuid = 0), so they are never dereferenced.
    let slot_min_uuid = primary.lease_device_buffer(nslots * 16)?;
    let slot_max_uuid = primary.lease_device_buffer(nslots * 16)?;
    // i128 / text GROUP BY key slots (b128): a valid pointer so the 27-param kernel has no stray arg.
    // The int4 bench never takes the i128/text-key branch (key_is_i128 = key_is_text = 0), so it is
    // never dereferenced.
    let slot_keys_i128 = primary.lease_device_buffer(nslots * 16)?;
    check_cuda(unsafe { cu_htod(indices_dev.ptr, indices.as_ptr().cast::<c_void>(), idx_bytes) })?;

    let null = std::ptr::null_mut::<c_void>();
    let mut start = std::ptr::null_mut::<c_void>();
    let mut stop = std::ptr::null_mut::<c_void>();
    check_cuda(unsafe { (primary.cu_event_create)(&mut start, 0) })?;
    check_cuda(unsafe { (primary.cu_event_create)(&mut stop, 0) })?;

    const BLOCK: u32 = 256;
    let fill_grid = nslots_u64.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;
    let group_grid = count_u64.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;
    let mut f0 = slot_keys.ptr;
    let mut f1 = nslots_u64;
    let mut f2 = EMPTY as u64;
    let mut fill_args = [
        (&mut f0 as *mut u64).cast::<c_void>(),
        (&mut f1 as *mut u64).cast::<c_void>(),
        (&mut f2 as *mut u64).cast::<c_void>(),
    ];
    let mut a = [
        resident.device_ptr(), key_byte_offset, sum_byte_offset, indices_dev.ptr, count_u64, mask,
        slot_keys.ptr, slot_count.ptr, slot_sum.ptr, slot_min.ptr, slot_max.ptr,
        0, // value_is_int8 = false: the timed bench always aggregates an int4 value column
        slot_sum_hi.ptr,
        0, // key_is_int8 = false: the timed bench always groups by an int4 key
        0, // value_is_numeric = false
        overflow_flag.ptr,
        slot_min_hi.ptr,
        slot_max_hi.ptr,
        row_slots.ptr,
        0, // value_is_uuid = false: the timed bench never aggregates a uuid value
        slot_min_uuid.ptr,
        slot_max_uuid.ptr,
        0, // key_is_i128 = false: the timed bench always groups by an int4 key
        slot_keys_i128.ptr,
        0, // key_is_text = false: the timed bench always groups by an int4 key
        0, // key_offsets_off (unused)
        0, // key_bytes_off (unused)
        0, // value_is_text = false: the timed bench always aggregates an int4 value
        0, // value_offsets_off (unused)
        0, // value_bytes_off (unused)
        0, // key_base_override = 0: the timed bench uses column keys (no derived-buffer override)
        0, // value_base_override = 0: the timed bench uses column values
        0, // comp_w = 0: the timed bench is not a wide-key composite
        0, // n_text = 0: the timed bench has no text members
        0, // text_desc_ptr = 0
    ];
    let mut group_args: Vec<*mut c_void> =
        a.iter_mut().map(|x| (x as *mut u64).cast::<c_void>()).collect();

    let mut best = f32::MAX;
    for _ in 0..runs {
        check_cuda(unsafe { cu_memset(slot_count.ptr, 0, slot_bytes) })?;
        check_cuda(unsafe { cu_memset(slot_sum.ptr, 0, slot_bytes) })?;
        // fill keys=EMPTY, min=i64::MAX, max=i64::MIN (reset f0/f2 each iteration).
        f0 = slot_keys.ptr;
        f2 = EMPTY as u64;
        check_cuda(unsafe {
            cu_launch(fill_fn, fill_grid, 1, 1, BLOCK, 1, 1, 0, null, fill_args.as_mut_ptr(), null.cast())
        })?;
        f0 = slot_min.ptr;
        f2 = i64::MAX as u64;
        check_cuda(unsafe {
            cu_launch(fill_fn, fill_grid, 1, 1, BLOCK, 1, 1, 0, null, fill_args.as_mut_ptr(), null.cast())
        })?;
        f0 = slot_max.ptr;
        f2 = i64::MIN as u64;
        check_cuda(unsafe {
            cu_launch(fill_fn, fill_grid, 1, 1, BLOCK, 1, 1, 0, null, fill_args.as_mut_ptr(), null.cast())
        })?;
        check_cuda(unsafe { (primary.cu_event_record)(start, null) })?;
        check_cuda(unsafe {
            cu_launch(group_fn, group_grid, 1, 1, BLOCK, 1, 1, 0, null, group_args.as_mut_ptr(), null.cast())
        })?;
        check_cuda(unsafe { (primary.cu_event_record)(stop, null) })?;
        check_cuda(unsafe { cu_stream_sync(null) })?;
        let mut ms = 0f32;
        check_cuda(unsafe { (primary.cu_event_elapsed_time)(&mut ms, start, stop) })?;
        best = best.min(ms);
    }

    let mut keys = vec![0i64; nslots];
    let mut counts = vec![0u64; nslots];
    let mut sums = vec![0i64; nslots];
    check_cuda(unsafe { cu_dtoh(keys.as_mut_ptr().cast::<c_void>(), slot_keys.ptr, slot_bytes) })?;
    check_cuda(unsafe { cu_dtoh(counts.as_mut_ptr().cast::<c_void>(), slot_count.ptr, slot_bytes) })?;
    check_cuda(unsafe { cu_dtoh(sums.as_mut_ptr().cast::<c_void>(), slot_sum.ptr, slot_bytes) })?;
    unsafe {
        (primary.cu_event_destroy)(start);
        (primary.cu_event_destroy)(stop);
    }
    let mut groups = Vec::new();
    for i in 0..nslots {
        if keys[i] != EMPTY {
            // min/max are placeholders here -- the timed bench only validates COUNT/SUM (the two
            // kernels intentionally differ on min/max: single-level computes them, two-level doesn't).
            groups.push(GroupByI32Row { key: keys[i], count: counts[i], sum: sums[i], sum_hi: 0, min: 0, max: 0, min_hi: 0, max_hi: 0, min_uuid: [0u8; 16], max_uuid: [0u8; 16], key_i128: 0 });
        }
    }
    Ok((groups, best))
}


/// Evaluate `text[i] LIKE pattern` over a resident TEXT column to surviving row indices (the type
/// matrix, doc 19): copy the compiled u32 token array H2D into a leased buffer, run
/// `gpu_db_resident_text_like_scalar_to_mask` to a mask, then the shared compactor. The `tokens` host
/// slice outlives the stream's covering sync, so the async H2D source stays valid.
fn launch_cuda_resident_text_like_scalar_filter(
    resident: &CudaResidentDeviceMemory,
    offsets_byte_offset: u64,
    bytes_byte_offset: u64,
    tokens: &[u32],
    n: u64,
) -> Result<Vec<u32>, CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    const PTX: &[u8] = include_bytes!("expr_proto.ptx");

    if n == 0 {
        return Ok(Vec::new());
    }
    let n_usize = usize::try_from(n).map_err(|_| CudaRuntimeProbeError::InvalidInputLength(0))?;
    let mask_bytes = n_usize
        .checked_mul(std::mem::size_of::<i32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(n_usize))?;
    let token_bytes = tokens
        .len()
        .checked_mul(std::mem::size_of::<u32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(tokens.len()))?;

    let primary = resident.primary();
    primary.set_current()?;
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let htod_async = primary
        .cu_memcpy_htod_async
        .ok_or(CudaRuntimeProbeError::DriverLibraryUnavailable)?;
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let match_fn = primary.cached_function(c"gpu_db_resident_text_like_scalar_to_mask", &ptx)?;

    // Token array on device (lease >= 1 byte so the pointer is valid even for the empty pattern, which
    // the kernel never dereferences since ntok == 0).
    let tokens_lease = primary.lease_device_buffer(token_bytes.max(1))?;
    let mask = primary.lease_device_buffer(mask_bytes)?;

    const BLOCK: u32 = 256;
    let grid = n.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;
    let mut a0 = resident.device_ptr();
    let mut a1 = offsets_byte_offset;
    let mut a2 = bytes_byte_offset;
    let mut a3 = tokens_lease.ptr;
    let mut a4 = tokens.len() as u64;
    let mut a5 = n;
    let mut a6 = mask.ptr;
    let mut args = [
        (&mut a0 as *mut u64).cast::<c_void>(),
        (&mut a1 as *mut u64).cast::<c_void>(),
        (&mut a2 as *mut u64).cast::<c_void>(),
        (&mut a3 as *mut u64).cast::<c_void>(),
        (&mut a4 as *mut u64).cast::<c_void>(),
        (&mut a5 as *mut u64).cast::<c_void>(),
        (&mut a6 as *mut u64).cast::<c_void>(),
    ];
    launch_on_pooled_stream(resident, None, |stream, _scratch| {
        if !tokens.is_empty() {
            let rc = unsafe {
                htod_async(
                    tokens_lease.ptr,
                    tokens.as_ptr().cast::<c_void>(),
                    token_bytes,
                    stream,
                )
            };
            if rc != 0 {
                return rc;
            }
        }
        unsafe {
            cu_launch_kernel(
                match_fn,
                grid,
                1,
                1,
                BLOCK,
                1,
                1,
                0,
                stream,
                args.as_mut_ptr(),
                std::ptr::null_mut(),
            )
        }
    })?;
    compact_mask_i32_to_indices(resident, mask.ptr, n)
}

/// Evaluate `a <cmp> b` over two resident numeric (i128) columns to surviving row indices (the type
/// matrix, doc 19): `gpu_db_resident_i128_compare_columns_to_mask` to a mask, then the compactor.
fn launch_cuda_resident_i128_compare_columns_filter(
    resident: &CudaResidentDeviceMemory,
    a_byte_offset: u64,
    b_byte_offset: u64,
    comparison: u32,
    n: u64,
) -> Result<Vec<u32>, CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    const PTX: &[u8] = include_bytes!("expr_proto.ptx");

    if n == 0 {
        return Ok(Vec::new());
    }
    let n_usize = usize::try_from(n).map_err(|_| CudaRuntimeProbeError::InvalidInputLength(0))?;
    let mask_bytes = n_usize
        .checked_mul(std::mem::size_of::<i32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(n_usize))?;

    let primary = resident.primary();
    primary.set_current()?;
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let compare_fn =
        primary.cached_function(c"gpu_db_resident_i128_compare_columns_to_mask", &ptx)?;
    let mask = primary.lease_device_buffer(mask_bytes)?;

    const BLOCK: u32 = 256;
    let grid = n.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;
    let mut a0 = resident.device_ptr();
    let mut a1 = a_byte_offset;
    let mut a2 = b_byte_offset;
    let mut a3 = comparison;
    let mut a4 = n;
    let mut a5 = mask.ptr;
    let mut args = [
        (&mut a0 as *mut u64).cast::<c_void>(),
        (&mut a1 as *mut u64).cast::<c_void>(),
        (&mut a2 as *mut u64).cast::<c_void>(),
        (&mut a3 as *mut u32).cast::<c_void>(),
        (&mut a4 as *mut u64).cast::<c_void>(),
        (&mut a5 as *mut u64).cast::<c_void>(),
    ];
    launch_on_pooled_stream(resident, None, |stream, _scratch| unsafe {
        cu_launch_kernel(
            compare_fn,
            grid,
            1,
            1,
            BLOCK,
            1,
            1,
            0,
            stream,
            args.as_mut_ptr(),
            std::ptr::null_mut(),
        )
    })?;
    compact_mask_i32_to_indices(resident, mask.ptr, n)
}

fn launch_cuda_resident_i32_equal_project(
    resident: &CudaResidentDeviceMemory,
    filters: &[(u64, i32)],
    projection_offsets: &[u64],
    row_count: u64,
) -> Result<Vec<Vec<i32>>, CudaRuntimeProbeError> {
    type CuMemsetD8 = unsafe extern "C" fn(u64, u8, usize) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;

    const MAX_FILTERS: usize = 4;
    const MAX_PROJECTIONS: usize = 4;
    const PTX: &[u8] = br#"
.version 6.0
.target sm_30
.address_size 64

.visible .entry gpu_db_resident_i32_equal_project(
    .param .u64 resident_ptr,
    .param .u64 row_count,
    .param .u32 filter_count,
    .param .u32 projection_count,
    .param .u64 filter_offset0,
    .param .u64 filter_offset1,
    .param .u64 filter_offset2,
    .param .u64 filter_offset3,
    .param .u64 projection_offset0,
    .param .u64 projection_offset1,
    .param .u64 projection_offset2,
    .param .u64 projection_offset3,
    .param .s32 needle0,
    .param .s32 needle1,
    .param .s32 needle2,
    .param .s32 needle3,
    .param .u64 out_values_ptr,
    .param .u64 out_row_indices_ptr,
    .param .u64 out_count_ptr
)
{
    .reg .pred %p_out;
    .reg .pred %p_done;
    .reg .pred %p_match;
    .reg .pred %p_check;
    .reg .u32 %r_tid;
    .reg .u32 %r_block;
    .reg .u32 %r_block_dim;
    .reg .u32 %idx32;
    .reg .u32 %filter_count;
    .reg .u32 %projection_count;
    .reg .u32 %slot;
    .reg .u32 %one;
    .reg .u64 %idx;
    .reg .u64 %rows;
    .reg .u64 %resident;
    .reg .u64 %filter_offset0;
    .reg .u64 %filter_offset1;
    .reg .u64 %filter_offset2;
    .reg .u64 %filter_offset3;
    .reg .u64 %projection_offset0;
    .reg .u64 %projection_offset1;
    .reg .u64 %projection_offset2;
    .reg .u64 %projection_offset3;
    .reg .u64 %out_values;
    .reg .u64 %out_row_indices;
    .reg .u64 %out_count;
    .reg .u64 %row_byte;
    .reg .u64 %addr;
    .reg .u64 %slot64;
    .reg .u64 %projection_count64;
    .reg .u64 %base_slot;
    .reg .u64 %out_addr;
    .reg .s32 %needle0;
    .reg .s32 %needle1;
    .reg .s32 %needle2;
    .reg .s32 %needle3;
    .reg .s32 %r_value;

    ld.param.u64 %resident, [resident_ptr];
    ld.param.u64 %rows, [row_count];
    ld.param.u32 %filter_count, [filter_count];
    ld.param.u32 %projection_count, [projection_count];
    ld.param.u64 %filter_offset0, [filter_offset0];
    ld.param.u64 %filter_offset1, [filter_offset1];
    ld.param.u64 %filter_offset2, [filter_offset2];
    ld.param.u64 %filter_offset3, [filter_offset3];
    ld.param.u64 %projection_offset0, [projection_offset0];
    ld.param.u64 %projection_offset1, [projection_offset1];
    ld.param.u64 %projection_offset2, [projection_offset2];
    ld.param.u64 %projection_offset3, [projection_offset3];
    ld.param.s32 %needle0, [needle0];
    ld.param.s32 %needle1, [needle1];
    ld.param.s32 %needle2, [needle2];
    ld.param.s32 %needle3, [needle3];
    ld.param.u64 %out_values, [out_values_ptr];
    ld.param.u64 %out_row_indices, [out_row_indices_ptr];
    ld.param.u64 %out_count, [out_count_ptr];

    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_block, %ctaid.x;
    mov.u32 %r_block_dim, %ntid.x;
    mad.lo.u32 %idx32, %r_block, %r_block_dim, %r_tid;
    cvt.u64.u32 %idx, %idx32;

    setp.ge.u64 %p_out, %idx, %rows;
    @%p_out bra DONE;
    setp.eq.u32 %p_done, %filter_count, 0;
    @%p_done bra DONE;
    setp.eq.u32 %p_done, %projection_count, 0;
    @%p_done bra DONE;

    mul.lo.u64 %row_byte, %idx, 4;

    add.u64 %addr, %resident, %filter_offset0;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %r_value, [%addr];
    setp.eq.s32 %p_match, %r_value, %needle0;
    @!%p_match bra DONE;

    setp.le.u32 %p_check, %filter_count, 1;
    @%p_check bra MATCHED;
    add.u64 %addr, %resident, %filter_offset1;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %r_value, [%addr];
    setp.eq.s32 %p_match, %r_value, %needle1;
    @!%p_match bra DONE;

    setp.le.u32 %p_check, %filter_count, 2;
    @%p_check bra MATCHED;
    add.u64 %addr, %resident, %filter_offset2;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %r_value, [%addr];
    setp.eq.s32 %p_match, %r_value, %needle2;
    @!%p_match bra DONE;

    setp.le.u32 %p_check, %filter_count, 3;
    @%p_check bra MATCHED;
    add.u64 %addr, %resident, %filter_offset3;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %r_value, [%addr];
    setp.eq.s32 %p_match, %r_value, %needle3;
    @!%p_match bra DONE;

MATCHED:
    mov.u32 %one, 1;
    atom.global.add.u32 %slot, [%out_count], %one;
    cvt.u64.u32 %slot64, %slot;

    mul.lo.u64 %out_addr, %slot64, 8;
    add.u64 %out_addr, %out_row_indices, %out_addr;
    st.global.u64 [%out_addr], %idx;

    cvt.u64.u32 %projection_count64, %projection_count;
    mul.lo.u64 %base_slot, %slot64, %projection_count64;
    mul.lo.u64 %base_slot, %base_slot, 4;

    add.u64 %addr, %resident, %projection_offset0;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %r_value, [%addr];
    add.u64 %out_addr, %out_values, %base_slot;
    st.global.s32 [%out_addr], %r_value;

    setp.le.u32 %p_check, %projection_count, 1;
    @%p_check bra DONE;
    add.u64 %addr, %resident, %projection_offset1;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %r_value, [%addr];
    add.u64 %out_addr, %out_values, %base_slot;
    add.u64 %out_addr, %out_addr, 4;
    st.global.s32 [%out_addr], %r_value;

    setp.le.u32 %p_check, %projection_count, 2;
    @%p_check bra DONE;
    add.u64 %addr, %resident, %projection_offset2;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %r_value, [%addr];
    add.u64 %out_addr, %out_values, %base_slot;
    add.u64 %out_addr, %out_addr, 8;
    st.global.s32 [%out_addr], %r_value;

    setp.le.u32 %p_check, %projection_count, 3;
    @%p_check bra DONE;
    add.u64 %addr, %resident, %projection_offset3;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %r_value, [%addr];
    add.u64 %out_addr, %out_values, %base_slot;
    add.u64 %out_addr, %out_addr, 12;
    st.global.s32 [%out_addr], %r_value;

DONE:
    ret;
}
"#;

    if filters.is_empty() || filters.len() > MAX_FILTERS {
        return Err(CudaRuntimeProbeError::InvalidInputLength(filters.len()));
    }
    if projection_offsets.is_empty() || projection_offsets.len() > MAX_PROJECTIONS {
        return Err(CudaRuntimeProbeError::InvalidInputLength(
            projection_offsets.len(),
        ));
    }
    if row_count == 0 {
        return Ok(Vec::new());
    }
    for (byte_offset, _) in filters {
        let bytes = row_count
            .checked_mul(std::mem::size_of::<i32>() as u64)
            .and_then(|bytes| byte_offset.checked_add(bytes))
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
        if bytes > resident.metadata().allocated_bytes {
            return Err(CudaRuntimeProbeError::InvalidInputLength(bytes as usize));
        }
    }
    for byte_offset in projection_offsets {
        let bytes = row_count
            .checked_mul(std::mem::size_of::<i32>() as u64)
            .and_then(|bytes| byte_offset.checked_add(bytes))
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
        if bytes > resident.metadata().allocated_bytes {
            return Err(CudaRuntimeProbeError::InvalidInputLength(bytes as usize));
        }
    }
    let row_count_u32 = u32::try_from(row_count)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let output_cells = row_count
        .checked_mul(projection_offsets.len() as u64)
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let output_bytes = usize::try_from(
        output_cells
            .checked_mul(std::mem::size_of::<i32>() as u64)
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?,
    )
    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;

    let cu_memset_d8 = unsafe {
        resident
            .lib()
            .get::<CuMemsetD8>(b"cuMemsetD8_v2\0")
            .or_else(|_| resident.lib().get::<CuMemsetD8>(b"cuMemsetD8\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };

    // P2-M2: pooled output buffers (no per-call cuMemAlloc/cuMemFree) — those driver-
    // serialized allocs, sized to worst-case row_count, were the projection routes' c64 wall.
    // Reused buffers are NOT zeroed; only the atomic-append counter is memset, and only
    // [0, count) is read back, so stale bytes in the values buffer are never observed.
    let values_guard = resident.primary().lease_device_buffer(output_bytes)?;
    // Stable-order fix (Thread-3 Stage 4): the kernel now also tags each match with its `row_index`
    // (one `st.global.u64` per match) into this buffer, so the host can sort the atomic-append
    // output into deterministic ASCENDING row order — the same fix `4b750a94` applied to the
    // `row_indices` route. Sized to worst-case row_count; only [0, count) is read back.
    let row_indices_bytes = usize::try_from(
        row_count
            .checked_mul(std::mem::size_of::<u64>() as u64)
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?,
    )
    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let row_indices_guard = resident.primary().lease_device_buffer(row_indices_bytes)?;
    let count_guard = resident
        .primary()
        .lease_device_buffer(std::mem::size_of::<u32>())?;
    check_cuda(unsafe { cu_memset_d8(count_guard.ptr, 0, std::mem::size_of::<u32>()) })?;

    // P2-M2: cached module (no per-launch cuModuleLoadData) — the projection kernel is
    // already parallel (one thread per row + atomic-append); the c64 wall was this per-call
    // orchestration (per-launch JIT + whole-context sync), not the kernel.
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let function = resident
        .primary()
        .cached_function(c"gpu_db_resident_i32_equal_project", &ptx)?;

    let mut resident_arg = resident.device_ptr();
    let mut rows_arg = row_count;
    let mut filter_count_arg = u32::try_from(filters.len())
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(filters.len()))?;
    let mut projection_count_arg = u32::try_from(projection_offsets.len())
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(projection_offsets.len()))?;
    let mut filter_offsets = [0_u64; MAX_FILTERS];
    let mut needles = [0_i32; MAX_FILTERS];
    for (idx, (offset, needle)) in filters.iter().enumerate() {
        filter_offsets[idx] = *offset;
        needles[idx] = *needle;
    }
    let mut projected_offsets = [0_u64; MAX_PROJECTIONS];
    for (idx, offset) in projection_offsets.iter().enumerate() {
        projected_offsets[idx] = *offset;
    }
    let mut output_arg = values_guard.ptr;
    let mut row_indices_arg = row_indices_guard.ptr;
    let mut count_arg = count_guard.ptr;
    let mut args = [
        (&mut resident_arg as *mut u64).cast::<c_void>(),
        (&mut rows_arg as *mut u64).cast::<c_void>(),
        (&mut filter_count_arg as *mut u32).cast::<c_void>(),
        (&mut projection_count_arg as *mut u32).cast::<c_void>(),
        (&mut filter_offsets[0] as *mut u64).cast::<c_void>(),
        (&mut filter_offsets[1] as *mut u64).cast::<c_void>(),
        (&mut filter_offsets[2] as *mut u64).cast::<c_void>(),
        (&mut filter_offsets[3] as *mut u64).cast::<c_void>(),
        (&mut projected_offsets[0] as *mut u64).cast::<c_void>(),
        (&mut projected_offsets[1] as *mut u64).cast::<c_void>(),
        (&mut projected_offsets[2] as *mut u64).cast::<c_void>(),
        (&mut projected_offsets[3] as *mut u64).cast::<c_void>(),
        (&mut needles[0] as *mut i32).cast::<c_void>(),
        (&mut needles[1] as *mut i32).cast::<c_void>(),
        (&mut needles[2] as *mut i32).cast::<c_void>(),
        (&mut needles[3] as *mut i32).cast::<c_void>(),
        (&mut output_arg as *mut u64).cast::<c_void>(),
        (&mut row_indices_arg as *mut u64).cast::<c_void>(),
        (&mut count_arg as *mut u64).cast::<c_void>(),
    ];
    let threads_per_block = 128;
    let blocks = row_count_u32.div_ceil(threads_per_block);
    // P2-M2: launch on a pooled private stream synced individually (no whole-context
    // cuCtxSynchronize); the route owns its values/count buffers, so no pooled scratch.
    launch_on_pooled_stream(resident, None, |stream, _scratch| unsafe {
        cu_launch_kernel(
            function,
            blocks,
            1,
            1,
            threads_per_block,
            1,
            1,
            0,
            stream,
            args.as_mut_ptr(),
            std::ptr::null_mut(),
        )
    })?;

    let mut match_count = 0_u32;
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            (&mut match_count as *mut u32).cast::<c_void>(),
            count_guard.ptr,
            std::mem::size_of::<u32>(),
        )
    })?;
    let match_count = u64::from(match_count);
    if match_count > row_count {
        return Err(CudaRuntimeProbeError::InvalidInputLength(usize::MAX));
    }
    let match_count_usize = usize::try_from(match_count)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let projection_count = projection_offsets.len();
    let mut values = vec![0_i32; match_count_usize.saturating_mul(projection_count)];
    let mut row_indices = vec![0_u64; match_count_usize];
    // The two result arrays (`values` and the Stage-4 `row_indices` order tags) are read back
    // TOGETHER behind ONE covering `cuStreamSynchronize`: both are staged async on the same pooled
    // private stream so the second copy overlaps the first on the copy engine — folding the
    // Stage-4 `row_indices` readback into the existing value transfer with ZERO added synchronous
    // round-trips (it was a separate blocking NULL-stream `cuMemcpyDtoH`, a fixed ~6-7 µs p50
    // regression including the 1-row point lookup, when added as a third serial barrier). On an old
    // driver lacking the async/pinned symbols the route keeps the original blocking copies, so
    // correctness is unconditional and only the overlap is best-effort. `values`/`row_indices` are
    // each read back only over their populated [0, match_count) prefix (`vec![..]` length), so the
    // worst-case device buffers' stale tails are never observed.
    if !values.is_empty() || !row_indices.is_empty() {
        if let Some(dtoh_async) = resident.primary().cu_memcpy_dtoh_async {
            resident.primary().set_current()?;
            struct StreamLease<'a> {
                primary: &'a GpuPrimaryContext,
                pooled: Option<PooledStream>,
            }
            impl Drop for StreamLease<'_> {
                fn drop(&mut self) {
                    if let Some(pooled) = self.pooled.take() {
                        self.primary.release_pooled_stream(pooled);
                    }
                }
            }
            let lease = StreamLease {
                primary: resident.primary(),
                pooled: Some(resident.primary().acquire_pooled_stream()?),
            };
            let stream = lease
                .pooled
                .as_ref()
                .expect("pooled stream just set")
                .stream;
            // Drain the stream FIRST on any error from an enqueued async copy (before the leases
            // unwind), so a buffer is never returned to the pool while a copy is still in flight —
            // the same drain-before-release contract the text route's staged D2H uses.
            let drain_err = |err: CudaRuntimeProbeError| -> CudaRuntimeProbeError {
                unsafe {
                    let _ = (resident.primary().cu_stream_synchronize)(stream);
                }
                err
            };
            let values_pinned = stage_result_dtoh_async(
                resident.primary(),
                dtoh_async,
                stream,
                values_guard.ptr,
                &mut values,
            )
            .map_err(drain_err)?;
            let row_indices_pinned = stage_result_dtoh_async(
                resident.primary(),
                dtoh_async,
                stream,
                row_indices_guard.ptr,
                &mut row_indices,
            )
            .map_err(drain_err)?;
            // Covering sync: drains on its own error too (both copies are still enqueued).
            check_cuda(unsafe { (resident.primary().cu_stream_synchronize)(stream) })
                .map_err(drain_err)?;
            copy_pinned_into(&values_pinned, &mut values);
            copy_pinned_into(&row_indices_pinned, &mut row_indices);
            drop(lease);
        } else {
            // ---- legacy blocking default-stream fallback (old driver: no async/pinned symbols) ----
            if !values.is_empty() {
                check_cuda(unsafe {
                    cu_memcpy_dtoh(
                        values.as_mut_ptr().cast::<c_void>(),
                        values_guard.ptr,
                        values.len() * std::mem::size_of::<i32>(),
                    )
                })?;
            }
            if !row_indices.is_empty() {
                check_cuda(unsafe {
                    cu_memcpy_dtoh(
                        row_indices.as_mut_ptr().cast::<c_void>(),
                        row_indices_guard.ptr,
                        row_indices.len() * std::mem::size_of::<u64>(),
                    )
                })?;
            }
        }
    }

    drop(count_guard);
    drop(row_indices_guard);
    drop(values_guard);
    // Deterministic ASCENDING row order (the `4b750a94` contract for resident projection routes):
    // the kernel appends matches in `atom.global.add` SCHEDULE order, ascending only within a
    // single warp (<=32 matches); for >32 the append order is non-deterministic across warps. Pair
    // each projected row with its tagged `row_index` and sort ascending so this route returns rows
    // identical to the CPU/non-resident reference AND byte-identical to the batched `equal_any`
    // path (which applies the same ascending sort in the engine result assembly). O(k log k)
    // host-side, dominated by the existing per-row D2H gather; for the <=1-row point-lookup shape
    // it is a no-op.
    let mut rows = values
        .chunks_exact(projection_count)
        .zip(row_indices)
        .map(|(row, row_index)| (row_index, row.to_vec()))
        .collect::<Vec<_>>();
    rows.sort_by_key(|(row_index, _)| *row_index);
    Ok(rows.into_iter().map(|(_, row)| row).collect())
}

fn submit_cuda_resident_i32_equal_any_project<R: CudaResidentReadSource>(
    resident: &R,
    filter_offset: u64,
    needles: &[i32],
    projection_offsets: &[u64],
    row_count: u64,
) -> Result<CudaI32EqualAnyProjectSubmission, CudaRuntimeProbeError> {
    // Only the blocking-fallback HtoD/memset and the (always-used) kernel launch are still loaded
    // here; the alloc/free/module/event symbols the un-migrated path used are replaced by the
    // shared pool, the module cache, and the pooled stream's own events.
    type CuMemsetD8 = unsafe extern "C" fn(u64, u8, usize) -> i32;
    type CuMemcpyHtoD = unsafe extern "C" fn(u64, *const c_void, usize) -> i32;
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;

    const MAX_PROJECTIONS: usize = 4;
    const PTX: &[u8] = br#"
.version 6.0
.target sm_30
.address_size 64

.visible .entry gpu_db_resident_i32_equal_any_project(
    .param .u64 resident_ptr,
    .param .u64 row_count,
    .param .u32 needle_count,
    .param .u32 projection_count,
    .param .u64 filter_offset,
    .param .u64 projection_offset0,
    .param .u64 projection_offset1,
    .param .u64 projection_offset2,
    .param .u64 projection_offset3,
    .param .u64 needles_ptr,
    .param .u64 out_values_ptr,
    .param .u64 out_needle_indices_ptr,
    .param .u64 out_row_indices_ptr,
    .param .u64 out_count_ptr
)
{
    .reg .pred %p_out;
    .reg .pred %p_done;
    .reg .pred %p_match;
    .reg .u32 %r_tid;
    .reg .u32 %r_block;
    .reg .u32 %r_block_dim;
    .reg .u32 %idx32;
    .reg .u32 %needle_count;
    .reg .u32 %projection_count;
    .reg .u32 %needle_idx;
    .reg .u32 %slot;
    .reg .u32 %one;
    .reg .u64 %idx;
    .reg .u64 %rows;
    .reg .u64 %resident;
    .reg .u64 %filter_offset;
    .reg .u64 %projection_offset0;
    .reg .u64 %projection_offset1;
    .reg .u64 %projection_offset2;
    .reg .u64 %projection_offset3;
    .reg .u64 %needles;
    .reg .u64 %out_values;
    .reg .u64 %out_needle_indices;
    .reg .u64 %out_row_indices;
    .reg .u64 %out_count;
    .reg .u64 %row_byte;
    .reg .u64 %addr;
    .reg .u64 %needle_byte;
    .reg .u64 %slot64;
    .reg .u64 %projection_count64;
    .reg .u64 %base_slot;
    .reg .u64 %out_addr;
    .reg .s32 %row_value;
    .reg .s32 %needle_value;
    .reg .s32 %projection_value;

    ld.param.u64 %resident, [resident_ptr];
    ld.param.u64 %rows, [row_count];
    ld.param.u32 %needle_count, [needle_count];
    ld.param.u32 %projection_count, [projection_count];
    ld.param.u64 %filter_offset, [filter_offset];
    ld.param.u64 %projection_offset0, [projection_offset0];
    ld.param.u64 %projection_offset1, [projection_offset1];
    ld.param.u64 %projection_offset2, [projection_offset2];
    ld.param.u64 %projection_offset3, [projection_offset3];
    ld.param.u64 %needles, [needles_ptr];
    ld.param.u64 %out_values, [out_values_ptr];
    ld.param.u64 %out_needle_indices, [out_needle_indices_ptr];
    ld.param.u64 %out_row_indices, [out_row_indices_ptr];
    ld.param.u64 %out_count, [out_count_ptr];

    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_block, %ctaid.x;
    mov.u32 %r_block_dim, %ntid.x;
    mad.lo.u32 %idx32, %r_block, %r_block_dim, %r_tid;
    cvt.u64.u32 %idx, %idx32;

    setp.ge.u64 %p_out, %idx, %rows;
    @%p_out bra DONE;
    setp.eq.u32 %p_done, %needle_count, 0;
    @%p_done bra DONE;
    setp.eq.u32 %p_done, %projection_count, 0;
    @%p_done bra DONE;

    mul.lo.u64 %row_byte, %idx, 4;
    add.u64 %addr, %resident, %filter_offset;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %row_value, [%addr];

    mov.u32 %needle_idx, 0;
NEEDLE_LOOP:
    setp.ge.u32 %p_done, %needle_idx, %needle_count;
    @%p_done bra DONE;
    cvt.u64.u32 %needle_byte, %needle_idx;
    mul.lo.u64 %needle_byte, %needle_byte, 4;
    add.u64 %addr, %needles, %needle_byte;
    ld.global.s32 %needle_value, [%addr];
    setp.eq.s32 %p_match, %row_value, %needle_value;
    @%p_match bra MATCHED;
    add.u32 %needle_idx, %needle_idx, 1;
    bra NEEDLE_LOOP;

MATCHED:
    mov.u32 %one, 1;
    atom.global.add.u32 %slot, [%out_count], %one;
    cvt.u64.u32 %slot64, %slot;

    mul.lo.u64 %out_addr, %slot64, 4;
    add.u64 %out_addr, %out_needle_indices, %out_addr;
    st.global.u32 [%out_addr], %needle_idx;

    mul.lo.u64 %out_addr, %slot64, 8;
    add.u64 %out_addr, %out_row_indices, %out_addr;
    st.global.u64 [%out_addr], %idx;

    cvt.u64.u32 %projection_count64, %projection_count;
    mul.lo.u64 %base_slot, %slot64, %projection_count64;
    mul.lo.u64 %base_slot, %base_slot, 4;

    add.u64 %addr, %resident, %projection_offset0;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %projection_value, [%addr];
    add.u64 %out_addr, %out_values, %base_slot;
    st.global.s32 [%out_addr], %projection_value;

    setp.le.u32 %p_done, %projection_count, 1;
    @%p_done bra DONE;
    add.u64 %addr, %resident, %projection_offset1;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %projection_value, [%addr];
    add.u64 %out_addr, %out_values, %base_slot;
    add.u64 %out_addr, %out_addr, 4;
    st.global.s32 [%out_addr], %projection_value;

    setp.le.u32 %p_done, %projection_count, 2;
    @%p_done bra DONE;
    add.u64 %addr, %resident, %projection_offset2;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %projection_value, [%addr];
    add.u64 %out_addr, %out_values, %base_slot;
    add.u64 %out_addr, %out_addr, 8;
    st.global.s32 [%out_addr], %projection_value;

    setp.le.u32 %p_done, %projection_count, 3;
    @%p_done bra DONE;
    add.u64 %addr, %resident, %projection_offset3;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %projection_value, [%addr];
    add.u64 %out_addr, %out_values, %base_slot;
    add.u64 %out_addr, %out_addr, 12;
    st.global.s32 [%out_addr], %projection_value;

DONE:
    ret;
}
"#;

    if needles.is_empty() {
        return Err(CudaRuntimeProbeError::InvalidInputLength(0));
    }
    if projection_offsets.is_empty() || projection_offsets.len() > MAX_PROJECTIONS {
        return Err(CudaRuntimeProbeError::InvalidInputLength(
            projection_offsets.len(),
        ));
    }
    if row_count == 0 {
        return Err(CudaRuntimeProbeError::InvalidInputLength(0));
    }
    let filter_bytes = row_count
        .checked_mul(std::mem::size_of::<i32>() as u64)
        .and_then(|bytes| filter_offset.checked_add(bytes))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    if filter_bytes > resident.metadata().allocated_bytes {
        return Err(CudaRuntimeProbeError::InvalidInputLength(
            filter_bytes as usize,
        ));
    }
    for byte_offset in projection_offsets {
        let bytes = row_count
            .checked_mul(std::mem::size_of::<i32>() as u64)
            .and_then(|bytes| byte_offset.checked_add(bytes))
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
        if bytes > resident.metadata().allocated_bytes {
            return Err(CudaRuntimeProbeError::InvalidInputLength(bytes as usize));
        }
    }
    let row_count_u32 = u32::try_from(row_count)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let needle_count_u32 = u32::try_from(needles.len())
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(needles.len()))?;
    let output_cells = row_count
        .checked_mul(projection_offsets.len() as u64)
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let output_bytes = usize::try_from(
        output_cells
            .checked_mul(std::mem::size_of::<i32>() as u64)
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?,
    )
    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let output_indices_bytes = usize::try_from(
        row_count
            .checked_mul(std::mem::size_of::<u32>() as u64)
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?,
    )
    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let output_row_indices_bytes = usize::try_from(
        row_count
            .checked_mul(std::mem::size_of::<u64>() as u64)
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?,
    )
    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let needle_bytes = needles
        .len()
        .checked_mul(std::mem::size_of::<i32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;

    // P2-M2 (equal_any split-route migration — mirrors the text route's async-on-pooled-stream
    // lever, adapted to this route's deferred `submit`→`complete`). The un-migrated path was the
    // projection-route default-stream wall: per-call `cuMemAlloc`/`cuMemFree` (5 driver-serialized
    // allocs), a blocking default-stream `cuMemcpyHtoD`(needles) + `cuMemsetD8`(count), a per-call
    // `cuModuleLoadData` (re-JIT), and a kernel on the NULL stream — every one a context-wide
    // barrier across concurrent readers. This `submit` now: leases the device buffers from the
    // shared `OutputBufferPool` (no per-call alloc/free), uses the cached module (no re-JIT), and
    // ENQUEUES HtoD(needles) + memset(count) + the kernel on a pooled private stream via the
    // `*Async` variants when present (blocking variants on an old driver) — without syncing, so
    // the kernel overlaps the host work the caller does before `complete`. `complete` syncs the
    // stream and reads the results (async-pinned when available). The pooled buffers + stream are
    // carried as owned (`Arc`-holding) guards because they must outlive this frame.
    //
    // Only `cu_memcpy_htod` / `cu_memset_d8` (blocking fallback) and `cu_launch_kernel` (always)
    // are still loaded here; the alloc/free/module/event symbols are gone — the pool, the module
    // cache, and the pooled stream's own events replace them.
    let cu_memset_d8 = unsafe {
        resident
            .lib()
            .get::<CuMemsetD8>(b"cuMemsetD8_v2\0")
            .or_else(|_| resident.lib().get::<CuMemsetD8>(b"cuMemsetD8\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_htod = unsafe {
        resident
            .lib()
            .get::<CuMemcpyHtoD>(b"cuMemcpyHtoD_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyHtoD>(b"cuMemcpyHtoD\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };

    let primary = resident.primary_arc();
    primary.set_current()?;

    // Pooled device buffers (owned guards — returned to the pool when the submission drops, after
    // `complete` reads them). Reused buffers are NOT zeroed; only the count is memset, the needles
    // buffer is fully overwritten by the HtoD, and every output is read back only over [0, count),
    // so stale bytes are never observed.
    let needles_guard = primary.lease_device_buffer_owned(needle_bytes)?;
    let values_guard = primary.lease_device_buffer_owned(output_bytes)?;
    let indices_guard = primary.lease_device_buffer_owned(output_indices_bytes)?;
    let row_indices_guard = primary.lease_device_buffer_owned(output_row_indices_bytes)?;
    let count_guard = primary.lease_device_buffer_owned(std::mem::size_of::<u32>())?;

    // Cached module (no per-call cuModuleLoadData) — the kernel is already parallel (one thread
    // per row + atomic-append); the wall was this per-call orchestration, not the kernel.
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let function = primary.cached_function(c"gpu_db_resident_i32_equal_any_project", &ptx)?;

    let mut resident_arg = resident.device_ptr();
    let mut rows_arg = row_count;
    let mut needle_count_arg = needle_count_u32;
    let mut projection_count_arg = u32::try_from(projection_offsets.len())
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(projection_offsets.len()))?;
    let mut filter_offset_arg = filter_offset;
    let mut projected_offsets = [0_u64; MAX_PROJECTIONS];
    for (idx, offset) in projection_offsets.iter().enumerate() {
        projected_offsets[idx] = *offset;
    }
    let mut needles_arg = needles_guard.ptr;
    let mut output_arg = values_guard.ptr;
    let mut indices_arg = indices_guard.ptr;
    let mut row_indices_arg = row_indices_guard.ptr;
    let mut count_arg = count_guard.ptr;
    let mut args = [
        (&mut resident_arg as *mut u64).cast::<c_void>(),
        (&mut rows_arg as *mut u64).cast::<c_void>(),
        (&mut needle_count_arg as *mut u32).cast::<c_void>(),
        (&mut projection_count_arg as *mut u32).cast::<c_void>(),
        (&mut filter_offset_arg as *mut u64).cast::<c_void>(),
        (&mut projected_offsets[0] as *mut u64).cast::<c_void>(),
        (&mut projected_offsets[1] as *mut u64).cast::<c_void>(),
        (&mut projected_offsets[2] as *mut u64).cast::<c_void>(),
        (&mut projected_offsets[3] as *mut u64).cast::<c_void>(),
        (&mut needles_arg as *mut u64).cast::<c_void>(),
        (&mut output_arg as *mut u64).cast::<c_void>(),
        (&mut indices_arg as *mut u64).cast::<c_void>(),
        (&mut row_indices_arg as *mut u64).cast::<c_void>(),
        (&mut count_arg as *mut u64).cast::<c_void>(),
    ];
    let threads_per_block = 128;
    let blocks = row_count_u32.div_ceil(threads_per_block);

    // Lease the pooled private stream (owned — held by the submission until `complete`).
    let stream_owned = PooledStreamOwned {
        primary: Arc::clone(&primary),
        pooled: Some(primary.acquire_pooled_stream()?),
    };
    let pooled = stream_owned
        .pooled
        .as_ref()
        .expect("pooled stream just leased");
    let stream = pooled.stream;
    let timed = !pooled.start_event.is_null() && !pooled.stop_event.is_null();

    // Error-path stream drain (same contract as the text route): every op below ENQUEUES async
    // work on `stream`; an early `?` would unwind the owned buffer/stream guards (returning them
    // to their pools) while that work may still be in flight — a use-after-free for the next
    // leaser. `drain_err` blocking-syncs the stream FIRST (at the error site, before any guard
    // Drop), then yields the original error. Zero success-path cost.
    let drain_err = |err: CudaRuntimeProbeError| -> CudaRuntimeProbeError {
        // SAFETY: `stream` is the live pooled stream; a blocking sync on it is valid here (the
        // primary context is current). Result intentionally ignored — best-effort error-path drain.
        unsafe {
            let _ = (primary.cu_stream_synchronize)(stream);
        }
        err
    };

    // Optional stream-ordered transfer symbols; absent → the blocking fallback (still correct,
    // just a default-stream barrier on an old driver). The kernel always launches on the pooled
    // stream regardless.
    let async_ops = match (primary.cu_memcpy_htod_async, primary.cu_memset_d8_async) {
        (Some(htod), Some(memset)) => Some((htod, memset)),
        _ => None,
    };

    if let Some((htod_async, memset_async)) = async_ops {
        check_cuda(unsafe {
            htod_async(
                needles_guard.ptr,
                needles.as_ptr().cast::<c_void>(),
                needle_bytes,
                stream,
            )
        })
        .map_err(drain_err)?;
        check_cuda(unsafe { memset_async(count_guard.ptr, 0, std::mem::size_of::<u32>(), stream) })
            .map_err(drain_err)?;
    } else {
        // Blocking fallback: these default-stream ops complete (host-blocking) before the kernel
        // is enqueued on the pooled stream below, so the kernel still observes the uploaded needles
        // and the zeroed counter.
        check_cuda(unsafe {
            cu_memcpy_htod(
                needles_guard.ptr,
                needles.as_ptr().cast::<c_void>(),
                needle_bytes,
            )
        })
        .map_err(drain_err)?;
        check_cuda(unsafe { cu_memset_d8(count_guard.ptr, 0, std::mem::size_of::<u32>()) })
            .map_err(drain_err)?;
    }

    if timed {
        check_cuda(unsafe { (primary.cu_event_record)(pooled.start_event, stream) })
            .map_err(drain_err)?;
    }
    check_cuda(unsafe {
        cu_launch_kernel(
            function,
            blocks,
            1,
            1,
            threads_per_block,
            1,
            1,
            0,
            stream,
            args.as_mut_ptr(),
            std::ptr::null_mut(),
        )
    })
    .map_err(drain_err)?;
    if timed {
        check_cuda(unsafe { (primary.cu_event_record)(pooled.stop_event, stream) })
            .map_err(drain_err)?;
    }
    // NB: deliberately NOT synced here — `complete` does the single covering sync, so the kernel
    // overlaps the caller's host work between `submit` and `complete`.

    Ok(CudaI32EqualAnyProjectSubmission {
        projection_count: projection_offsets.len(),
        needles_len: needles.len(),
        row_count,
        primary,
        values_guard,
        indices_guard,
        row_indices_guard,
        count_guard,
        _needles_guard: needles_guard,
        stream: Some(stream_owned),
        timed,
    })
}

#[allow(clippy::too_many_arguments)]
fn launch_cuda_resident_i32_equal_any_project_text<R: CudaResidentReadSource>(
    resident: &R,
    filter_offset: u64,
    needles: &[i32],
    projection_offsets: &[u64],
    text_offsets_byte_offset: u64,
    text_bytes_byte_offset: u64,
    text_bytes_len: u64,
    row_count: u64,
) -> Result<Vec<CudaI32TextBatchProjectionRow>, CudaRuntimeProbeError> {
    type CuMemsetD8 = unsafe extern "C" fn(u64, u8, usize) -> i32;
    type CuMemcpyHtoD = unsafe extern "C" fn(u64, *const c_void, usize) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;

    const MAX_PROJECTIONS: usize = 4;
    const PTX: &[u8] = br#"
.version 6.0
.target sm_30
.address_size 64

.visible .entry gpu_db_resident_i32_equal_any_project_text(
    .param .u64 resident_ptr,
    .param .u64 row_count,
    .param .u32 needle_count,
    .param .u32 projection_count,
    .param .u64 filter_offset,
    .param .u64 projection_offset0,
    .param .u64 projection_offset1,
    .param .u64 projection_offset2,
    .param .u64 projection_offset3,
    .param .u64 text_offsets_offset,
    .param .u64 text_bytes_offset,
    .param .u32 text_bytes_len,
    .param .u64 needles_ptr,
    .param .u64 out_values_ptr,
    .param .u64 out_needle_indices_ptr,
    .param .u64 out_row_indices_ptr,
    .param .u64 out_text_starts_ptr,
    .param .u64 out_text_lens_ptr,
    .param .u64 out_text_bytes_ptr,
    .param .u64 out_count_ptr,
    .param .u64 out_text_count_ptr
)
{
    .reg .pred %p_out;
    .reg .pred %p_done;
    .reg .pred %p_match;
    .reg .pred %p_copy_done;
    .reg .u16 %byte_value;
    .reg .u32 %r_tid;
    .reg .u32 %r_block;
    .reg .u32 %r_block_dim;
    .reg .u32 %idx32;
    .reg .u32 %needle_count;
    .reg .u32 %projection_count;
    .reg .u32 %needle_idx;
    .reg .u32 %slot;
    .reg .u32 %text_start32;
    .reg .u32 %text_end32;
    .reg .u32 %text_len;
    .reg .u32 %text_slot;
    .reg .u32 %copy_idx;
    .reg .u32 %one;
    .reg .u64 %idx;
    .reg .u64 %rows;
    .reg .u64 %resident;
    .reg .u64 %filter_offset;
    .reg .u64 %projection_offset0;
    .reg .u64 %projection_offset1;
    .reg .u64 %projection_offset2;
    .reg .u64 %projection_offset3;
    .reg .u64 %text_offsets_offset;
    .reg .u64 %text_bytes_offset;
    .reg .u64 %needles;
    .reg .u64 %out_values;
    .reg .u64 %out_needle_indices;
    .reg .u64 %out_row_indices;
    .reg .u64 %out_text_starts;
    .reg .u64 %out_text_lens;
    .reg .u64 %out_text_bytes;
    .reg .u64 %out_count;
    .reg .u64 %out_text_count;
    .reg .u64 %row_byte;
    .reg .u64 %addr;
    .reg .u64 %addr2;
    .reg .u64 %needle_byte;
    .reg .u64 %slot64;
    .reg .u64 %projection_count64;
    .reg .u64 %base_slot;
    .reg .u64 %out_addr;
    .reg .u64 %text_offset_addr;
    .reg .u64 %text_start64;
    .reg .u64 %text_end64;
    .reg .u64 %text_slot64;
    .reg .u64 %copy64;
    .reg .s32 %row_value;
    .reg .s32 %needle_value;
    .reg .s32 %projection_value;

    ld.param.u64 %resident, [resident_ptr];
    ld.param.u64 %rows, [row_count];
    ld.param.u32 %needle_count, [needle_count];
    ld.param.u32 %projection_count, [projection_count];
    ld.param.u64 %filter_offset, [filter_offset];
    ld.param.u64 %projection_offset0, [projection_offset0];
    ld.param.u64 %projection_offset1, [projection_offset1];
    ld.param.u64 %projection_offset2, [projection_offset2];
    ld.param.u64 %projection_offset3, [projection_offset3];
    ld.param.u64 %text_offsets_offset, [text_offsets_offset];
    ld.param.u64 %text_bytes_offset, [text_bytes_offset];
    ld.param.u64 %needles, [needles_ptr];
    ld.param.u64 %out_values, [out_values_ptr];
    ld.param.u64 %out_needle_indices, [out_needle_indices_ptr];
    ld.param.u64 %out_row_indices, [out_row_indices_ptr];
    ld.param.u64 %out_text_starts, [out_text_starts_ptr];
    ld.param.u64 %out_text_lens, [out_text_lens_ptr];
    ld.param.u64 %out_text_bytes, [out_text_bytes_ptr];
    ld.param.u64 %out_count, [out_count_ptr];
    ld.param.u64 %out_text_count, [out_text_count_ptr];

    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_block, %ctaid.x;
    mov.u32 %r_block_dim, %ntid.x;
    mad.lo.u32 %idx32, %r_block, %r_block_dim, %r_tid;
    cvt.u64.u32 %idx, %idx32;

    setp.ge.u64 %p_out, %idx, %rows;
    @%p_out bra DONE;
    setp.eq.u32 %p_done, %needle_count, 0;
    @%p_done bra DONE;

    mul.lo.u64 %row_byte, %idx, 4;
    add.u64 %addr, %resident, %filter_offset;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %row_value, [%addr];

    mov.u32 %needle_idx, 0;
NEEDLE_LOOP:
    setp.ge.u32 %p_done, %needle_idx, %needle_count;
    @%p_done bra DONE;
    cvt.u64.u32 %needle_byte, %needle_idx;
    mul.lo.u64 %needle_byte, %needle_byte, 4;
    add.u64 %addr, %needles, %needle_byte;
    ld.global.s32 %needle_value, [%addr];
    setp.eq.s32 %p_match, %row_value, %needle_value;
    @%p_match bra MATCHED;
    add.u32 %needle_idx, %needle_idx, 1;
    bra NEEDLE_LOOP;

MATCHED:
    mul.lo.u64 %text_offset_addr, %idx, 8;
    add.u64 %addr, %resident, %text_offsets_offset;
    add.u64 %addr, %addr, %text_offset_addr;
    ld.global.u32 %text_start32, [%addr];
    add.u64 %addr, %addr, 8;
    ld.global.u32 %text_end32, [%addr];
    cvt.u64.u32 %text_start64, %text_start32;
    cvt.u64.u32 %text_end64, %text_end32;
    sub.u32 %text_len, %text_end32, %text_start32;

    mov.u32 %one, 1;
    atom.global.add.u32 %slot, [%out_count], %one;
    cvt.u64.u32 %slot64, %slot;
    atom.global.add.u32 %text_slot, [%out_text_count], %text_len;
    cvt.u64.u32 %text_slot64, %text_slot;

    mul.lo.u64 %out_addr, %slot64, 4;
    add.u64 %out_addr, %out_needle_indices, %out_addr;
    st.global.u32 [%out_addr], %needle_idx;

    mul.lo.u64 %out_addr, %slot64, 8;
    add.u64 %out_addr, %out_row_indices, %out_addr;
    st.global.u64 [%out_addr], %idx;

    mul.lo.u64 %out_addr, %slot64, 4;
    add.u64 %addr, %out_text_starts, %out_addr;
    st.global.u32 [%addr], %text_slot;
    add.u64 %addr, %out_text_lens, %out_addr;
    st.global.u32 [%addr], %text_len;

    setp.eq.u32 %p_done, %projection_count, 0;
    @%p_done bra COPY_TEXT;
    cvt.u64.u32 %projection_count64, %projection_count;
    mul.lo.u64 %base_slot, %slot64, %projection_count64;
    mul.lo.u64 %base_slot, %base_slot, 4;

    add.u64 %addr, %resident, %projection_offset0;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %projection_value, [%addr];
    add.u64 %out_addr, %out_values, %base_slot;
    st.global.s32 [%out_addr], %projection_value;

    setp.le.u32 %p_done, %projection_count, 1;
    @%p_done bra COPY_TEXT;
    add.u64 %addr, %resident, %projection_offset1;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %projection_value, [%addr];
    add.u64 %out_addr, %out_values, %base_slot;
    add.u64 %out_addr, %out_addr, 4;
    st.global.s32 [%out_addr], %projection_value;

    setp.le.u32 %p_done, %projection_count, 2;
    @%p_done bra COPY_TEXT;
    add.u64 %addr, %resident, %projection_offset2;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %projection_value, [%addr];
    add.u64 %out_addr, %out_values, %base_slot;
    add.u64 %out_addr, %out_addr, 8;
    st.global.s32 [%out_addr], %projection_value;

    setp.le.u32 %p_done, %projection_count, 3;
    @%p_done bra COPY_TEXT;
    add.u64 %addr, %resident, %projection_offset3;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %projection_value, [%addr];
    add.u64 %out_addr, %out_values, %base_slot;
    add.u64 %out_addr, %out_addr, 12;
    st.global.s32 [%out_addr], %projection_value;

COPY_TEXT:
    mov.u32 %copy_idx, 0;
COPY_LOOP:
    setp.ge.u32 %p_copy_done, %copy_idx, %text_len;
    @%p_copy_done bra DONE;
    cvt.u64.u32 %copy64, %copy_idx;
    add.u64 %addr, %resident, %text_bytes_offset;
    add.u64 %addr, %addr, %text_start64;
    add.u64 %addr, %addr, %copy64;
    ld.global.u8 %byte_value, [%addr];
    add.u64 %addr2, %out_text_bytes, %text_slot64;
    add.u64 %addr2, %addr2, %copy64;
    st.global.u8 [%addr2], %byte_value;
    add.u32 %copy_idx, %copy_idx, 1;
    bra COPY_LOOP;

DONE:
    ret;
}
"#;

    if needles.is_empty() {
        return Err(CudaRuntimeProbeError::InvalidInputLength(0));
    }
    if projection_offsets.len() > MAX_PROJECTIONS {
        return Err(CudaRuntimeProbeError::InvalidInputLength(
            projection_offsets.len(),
        ));
    }
    if row_count == 0 {
        return Ok(Vec::new());
    }
    let _text_bytes_len_u32 = u32::try_from(text_bytes_len)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let filter_bytes = row_count
        .checked_mul(std::mem::size_of::<i32>() as u64)
        .and_then(|bytes| filter_offset.checked_add(bytes))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let text_offsets_end = row_count
        .checked_add(1)
        .and_then(|count| count.checked_mul(std::mem::size_of::<u64>() as u64))
        .and_then(|bytes| text_offsets_byte_offset.checked_add(bytes))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let text_bytes_end = text_bytes_byte_offset
        .checked_add(text_bytes_len)
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    if filter_bytes > resident.metadata().allocated_bytes
        || text_offsets_end > resident.metadata().allocated_bytes
        || text_bytes_end > resident.metadata().allocated_bytes
    {
        return Err(CudaRuntimeProbeError::InvalidInputLength(
            filter_bytes.max(text_offsets_end).max(text_bytes_end) as usize,
        ));
    }
    for byte_offset in projection_offsets {
        let bytes = row_count
            .checked_mul(std::mem::size_of::<i32>() as u64)
            .and_then(|bytes| byte_offset.checked_add(bytes))
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
        if bytes > resident.metadata().allocated_bytes {
            return Err(CudaRuntimeProbeError::InvalidInputLength(bytes as usize));
        }
    }
    let row_count_u32 = u32::try_from(row_count)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let needle_count_u32 = u32::try_from(needles.len())
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(needles.len()))?;
    let output_cells = row_count
        .checked_mul(projection_offsets.len() as u64)
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let output_bytes = usize::try_from(
        output_cells
            .checked_mul(std::mem::size_of::<i32>() as u64)
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?,
    )
    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?
    .max(1);
    let output_indices_bytes = usize::try_from(
        row_count
            .checked_mul(std::mem::size_of::<u32>() as u64)
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?,
    )
    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let output_row_indices_bytes = usize::try_from(
        row_count
            .checked_mul(std::mem::size_of::<u64>() as u64)
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?,
    )
    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let output_text_bytes = usize::try_from(text_bytes_len)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?
        .max(1);
    let needle_bytes = needles
        .len()
        .checked_mul(std::mem::size_of::<i32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;

    let cu_memset_d8 = unsafe {
        resident
            .lib()
            .get::<CuMemsetD8>(b"cuMemsetD8_v2\0")
            .or_else(|_| resident.lib().get::<CuMemsetD8>(b"cuMemsetD8\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_htod = unsafe {
        resident
            .lib()
            .get::<CuMemcpyHtoD>(b"cuMemcpyHtoD_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyHtoD>(b"cuMemcpyHtoD\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };

    // P2-M2 (text-route async lever): the c64 wall of this route was its 11 synchronous,
    // default/NULL-stream memory ops (1 HtoD + 2 memset + 8 D2H) — the driver serializes those
    // context-wide across concurrent readers, so 64 threads × 11 ops queued behind one barrier
    // (measured 99.7 % of a 12.8 ms c64 wall; the kernel + its private-stream sync were < 0.5 %).
    // The fix moves every one of those ops onto the route's **already-pooled private stream**
    // via the `*Async` variants behind exactly TWO `cuStreamSynchronize` (one after the kernel
    // so the device-computed counts are readable to size the result reads; one after the result
    // D2H). Two extra reductions ride along: the two atomic-append counters are fused into ONE
    // 8-byte device buffer read back in ONE D2H (the count read was the single largest post-fix
    // section because it forces the mid-pipeline sync), and all device→host copies stage through
    // **pooled pinned (page-locked) host buffers** so the async D2H is truly async + DMA-fast.
    // `cuMemAlloc`/`cuMemHostAlloc`/`cuStreamCreate` are themselves driver-serialized, so every
    // buffer (device + pinned-host) and the stream are POOLED — a per-call alloc would
    // re-introduce the very contention this removes (that was why the throwaway knob experiment,
    // which created an un-pooled per-call stream, only reached 1.64× instead of more).
    //
    // The whole async path is gated on the optional async + pinned-host driver symbols; on an
    // old driver lacking them the route keeps the original blocking default-stream path below,
    // so correctness is unconditional and only the acceleration is best-effort.
    let async_ops = match (
        resident.primary().cu_memcpy_htod_async,
        resident.primary().cu_memcpy_dtoh_async,
        resident.primary().cu_memset_d8_async,
    ) {
        (Some(htod), Some(dtoh), Some(memset)) => Some((htod, dtoh, memset)),
        _ => None,
    };

    // Pooled device output buffers (no per-call cuMemAlloc/cuMemFree). Reused buffers are NOT
    // zeroed; only the fused counter buffer is memset, the needles buffer is fully overwritten
    // by the HtoD upload, and every output is read back only over [0, count) — so stale bytes
    // are never observed.
    let needles_guard = resident.primary().lease_device_buffer(needle_bytes)?;
    let values_guard = resident.primary().lease_device_buffer(output_bytes)?;
    let indices_guard = resident
        .primary()
        .lease_device_buffer(output_indices_bytes)?;
    let row_indices_guard = resident
        .primary()
        .lease_device_buffer(output_row_indices_bytes)?;
    let text_starts_guard = resident
        .primary()
        .lease_device_buffer(output_indices_bytes)?;
    let text_lens_guard = resident
        .primary()
        .lease_device_buffer(output_indices_bytes)?;
    let text_bytes_guard = resident.primary().lease_device_buffer(output_text_bytes)?;
    // Fused counters: `count` at +0, `text_count` at +4 of one 8-byte device buffer, so both
    // are zeroed by one memset and read back by one D2H. The kernel still receives two distinct
    // pointers (it does `atom.add` into each independently), so no kernel change is required.
    const COUNT_OFFSET: usize = 0;
    const TEXT_COUNT_OFFSET: usize = std::mem::size_of::<u32>();
    const COUNTERS_BYTES: usize = 2 * std::mem::size_of::<u32>();
    let counters_guard = resident.primary().lease_device_buffer(COUNTERS_BYTES)?;
    let count_ptr = counters_guard.ptr + COUNT_OFFSET as u64;
    let text_count_ptr = counters_guard.ptr + TEXT_COUNT_OFFSET as u64;

    // P2-M2: cached module (no per-launch cuModuleLoadData) — the projection kernel is
    // already parallel (one thread per row + atomic-append); the c64 wall was this per-call
    // orchestration (per-launch JIT + whole-context sync), not the kernel.
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let function = resident
        .primary()
        .cached_function(c"gpu_db_resident_i32_equal_any_project_text", &ptx)?;

    let mut resident_arg = resident.device_ptr();
    let mut rows_arg = row_count;
    let mut needle_count_arg = needle_count_u32;
    let mut projection_count_arg = u32::try_from(projection_offsets.len())
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(projection_offsets.len()))?;
    let mut filter_offset_arg = filter_offset;
    let mut projected_offsets = [0_u64; MAX_PROJECTIONS];
    for (idx, offset) in projection_offsets.iter().enumerate() {
        projected_offsets[idx] = *offset;
    }
    let mut text_offsets_arg = text_offsets_byte_offset;
    let mut text_bytes_arg = text_bytes_byte_offset;
    let mut text_bytes_len_arg = _text_bytes_len_u32;
    let mut needles_arg = needles_guard.ptr;
    let mut output_arg = values_guard.ptr;
    let mut indices_arg = indices_guard.ptr;
    let mut row_indices_arg = row_indices_guard.ptr;
    let mut text_starts_arg = text_starts_guard.ptr;
    let mut text_lens_arg = text_lens_guard.ptr;
    let mut text_output_arg = text_bytes_guard.ptr;
    let mut count_arg = count_ptr;
    let mut text_count_arg = text_count_ptr;
    let mut args = [
        (&mut resident_arg as *mut u64).cast::<c_void>(),
        (&mut rows_arg as *mut u64).cast::<c_void>(),
        (&mut needle_count_arg as *mut u32).cast::<c_void>(),
        (&mut projection_count_arg as *mut u32).cast::<c_void>(),
        (&mut filter_offset_arg as *mut u64).cast::<c_void>(),
        (&mut projected_offsets[0] as *mut u64).cast::<c_void>(),
        (&mut projected_offsets[1] as *mut u64).cast::<c_void>(),
        (&mut projected_offsets[2] as *mut u64).cast::<c_void>(),
        (&mut projected_offsets[3] as *mut u64).cast::<c_void>(),
        (&mut text_offsets_arg as *mut u64).cast::<c_void>(),
        (&mut text_bytes_arg as *mut u64).cast::<c_void>(),
        (&mut text_bytes_len_arg as *mut u32).cast::<c_void>(),
        (&mut needles_arg as *mut u64).cast::<c_void>(),
        (&mut output_arg as *mut u64).cast::<c_void>(),
        (&mut indices_arg as *mut u64).cast::<c_void>(),
        (&mut row_indices_arg as *mut u64).cast::<c_void>(),
        (&mut text_starts_arg as *mut u64).cast::<c_void>(),
        (&mut text_lens_arg as *mut u64).cast::<c_void>(),
        (&mut text_output_arg as *mut u64).cast::<c_void>(),
        (&mut count_arg as *mut u64).cast::<c_void>(),
        (&mut text_count_arg as *mut u64).cast::<c_void>(),
    ];
    let threads_per_block = 128;
    let blocks = row_count_u32.div_ceil(threads_per_block);
    let projection_count = projection_offsets.len();

    // Read back the fused 8-byte counter pair; on the async path it stages through a pooled
    // pinned host buffer, on the blocking path through a plain stack array.
    let mut counters_host = [0_u32; 2];

    let (match_count, compact_text_len) = if let Some((htod_async, dtoh_async, memset_async)) =
        async_ops
    {
        // ---- async-on-pooled-stream path (the lever) ----
        // Bind the shared primary context (idempotent) and lease the pooled private stream.
        resident.primary().set_current()?;
        struct StreamLease<'a> {
            primary: &'a GpuPrimaryContext,
            pooled: Option<PooledStream>,
        }
        impl Drop for StreamLease<'_> {
            fn drop(&mut self) {
                if let Some(pooled) = self.pooled.take() {
                    self.primary.release_pooled_stream(pooled);
                }
            }
        }
        let lease = StreamLease {
            primary: resident.primary(),
            pooled: Some(resident.primary().acquire_pooled_stream()?),
        };
        let pooled = lease.pooled.as_ref().expect("pooled stream just set");
        let stream = pooled.stream;
        let timed = !pooled.start_event.is_null() && !pooled.stop_event.is_null();

        // HARDENING (error-path stream drain): once an async op is enqueued on this private
        // stream, an early `?` would propagate and unwind the locals — returning the device +
        // pinned buffer leases to their pools while enqueued ops may still be in flight, a
        // use-after-free window for whoever leases those buffers next. So every fallible op
        // from the first async enqueue through each covering `cuStreamSynchronize` propagates
        // its error through `drain_err`, which does a best-effort blocking sync (ignoring its
        // result) to drain the stream FIRST, *then* yields the original error.
        //
        // Ordering proof (drain-before-release on EVERY error path): `.map_err(drain_err)`
        // runs the closure at the error site, BEFORE the `?` returns and hence before ANY local
        // Drop runs — so it precedes the release of every lease regardless of scope (the device
        // guards live in the outer fn scope and drop last on unwind; the pinned leases live in
        // this block and drop first). A declaration-order Drop guard could not cover both,
        // because the pinned leases are created incrementally across this region; draining at
        // the error site sidesteps scope/order entirely. Zero success-path cost: `map_err` does
        // not invoke the closure on `Ok`, so a successful op adds nothing — the two explicit
        // syncs below remain the only synchronizations on the hot path. The drain is applied
        // only to ops that may leave async work in flight (enqueues + the covering syncs); the
        // pure-host steps between/after the syncs run when the stream is already idle, so they
        // need no drain.
        let drain_err = |err: CudaRuntimeProbeError| -> CudaRuntimeProbeError {
            // SAFETY: `stream` is the live pooled private stream; a blocking synchronize on it is
            // valid from this thread (the primary context is current). The result is intentionally
            // ignored — this is a best-effort drain on an already-failing path.
            unsafe {
                let _ = (resident.primary().cu_stream_synchronize)(stream);
            }
            err
        };

        // (1) Stream-ordered upload + zero + kernel: HtoD(needles), memset(counters=0), kernel.
        check_cuda(unsafe {
            htod_async(
                needles_guard.ptr,
                needles.as_ptr().cast::<c_void>(),
                needle_bytes,
                stream,
            )
        })
        .map_err(drain_err)?;
        check_cuda(unsafe { memset_async(counters_guard.ptr, 0, COUNTERS_BYTES, stream) })
            .map_err(drain_err)?;
        if timed {
            check_cuda(unsafe { (resident.primary().cu_event_record)(pooled.start_event, stream) })
                .map_err(drain_err)?;
        }
        check_cuda(unsafe {
            cu_launch_kernel(
                function,
                blocks,
                1,
                1,
                threads_per_block,
                1,
                1,
                0,
                stream,
                args.as_mut_ptr(),
                std::ptr::null_mut(),
            )
        })
        .map_err(drain_err)?;
        if timed {
            check_cuda(unsafe { (resident.primary().cu_event_record)(pooled.stop_event, stream) })
                .map_err(drain_err)?;
        }
        // (2) Stream-ordered read of the fused 8-byte counter pair, then sync #1: now the
        // counters (and the kernel) are complete and the result-array sizes are known. The
        // counters stage through a small pooled pinned host buffer for a truly-async DMA.
        let counters_pinned = resident.primary().lease_pinned_host_buffer(COUNTERS_BYTES);
        let counters_dst: *mut c_void = counters_pinned
            .as_ref()
            .map(|p| p.ptr)
            .unwrap_or_else(|| counters_host.as_mut_ptr().cast::<c_void>());
        check_cuda(unsafe { dtoh_async(counters_dst, counters_guard.ptr, COUNTERS_BYTES, stream) })
            .map_err(drain_err)?;
        // Covering sync #1: drains on its own error too (the counter D2H is still enqueued).
        check_cuda(unsafe { (resident.primary().cu_stream_synchronize)(stream) })
            .map_err(drain_err)?;
        if let Some(pinned) = &counters_pinned {
            // SAFETY: the sync above completed the 8-byte D2H into the pinned region; copy the
            // two u32 counters out by typed pointer (no alignment hazard: pinned host memory is
            // page-aligned and we read u32s from a u32-array layout).
            unsafe {
                std::ptr::copy_nonoverlapping(
                    pinned.ptr.cast::<u32>(),
                    counters_host.as_mut_ptr(),
                    counters_host.len(),
                );
            }
        }
        if timed {
            let mut elapsed_ms = 0.0_f32;
            check_cuda(unsafe {
                (resident.primary().cu_event_elapsed_time)(
                    &mut elapsed_ms,
                    pooled.start_event,
                    pooled.stop_event,
                )
            })?;
            resident.record_kernel_event_elapsed_us(Some(
                (f64::from(elapsed_ms) * 1_000.0).ceil() as u64
            ));
        } else {
            resident.record_kernel_event_elapsed_us(None);
        }

        let match_count = u64::from(counters_host[0]);
        let compact_text_len = counters_host[1];
        if match_count > row_count || u64::from(compact_text_len) > text_bytes_len {
            return Err(CudaRuntimeProbeError::InvalidInputLength(usize::MAX));
        }
        let match_count_usize = usize::try_from(match_count)
            .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
        let compact_text_usize = usize::try_from(compact_text_len)
            .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;

        // (3) Stream-ordered result D2H into pooled pinned host buffers (one queued copy per
        // result array, each reading back only the populated [0, count) prefix of its worst-
        // case device buffer), then ONE sync #2 — so the six copies overlap on the copy engine
        // instead of serializing as six blocking default-stream barriers. After the sync, the
        // pinned bytes are copied into owned Vecs (pinned buffers return to the pool on drop).
        let mut values = vec![0_i32; match_count_usize.saturating_mul(projection_count)];
        let mut needle_indices = vec![0_u32; match_count_usize];
        let mut row_indices = vec![0_u64; match_count_usize];
        let mut text_starts = vec![0_u32; match_count_usize];
        let mut text_lens = vec![0_u32; match_count_usize];
        let mut text_bytes = vec![0_u8; compact_text_usize];

        // Each staged D2H enqueues an async copy before it can return `Err`, so its error path
        // drains the stream first (via `drain_err`) before any lease unwinds. Earlier copies in
        // this batch are also still in flight on a later copy's failure — the single covering
        // sync #2 below would normally wait on them, but on the error path we must drain
        // explicitly since that sync is skipped.
        let values_pinned = stage_result_dtoh_async(
            resident.primary(),
            dtoh_async,
            stream,
            values_guard.ptr,
            &mut values,
        )
        .map_err(drain_err)?;
        let needle_indices_pinned = stage_result_dtoh_async(
            resident.primary(),
            dtoh_async,
            stream,
            indices_guard.ptr,
            &mut needle_indices,
        )
        .map_err(drain_err)?;
        let row_indices_pinned = stage_result_dtoh_async(
            resident.primary(),
            dtoh_async,
            stream,
            row_indices_guard.ptr,
            &mut row_indices,
        )
        .map_err(drain_err)?;
        let text_starts_pinned = stage_result_dtoh_async(
            resident.primary(),
            dtoh_async,
            stream,
            text_starts_guard.ptr,
            &mut text_starts,
        )
        .map_err(drain_err)?;
        let text_lens_pinned = stage_result_dtoh_async(
            resident.primary(),
            dtoh_async,
            stream,
            text_lens_guard.ptr,
            &mut text_lens,
        )
        .map_err(drain_err)?;
        let text_bytes_pinned = stage_result_dtoh_async(
            resident.primary(),
            dtoh_async,
            stream,
            text_bytes_guard.ptr,
            &mut text_bytes,
        )
        .map_err(drain_err)?;
        // Covering sync #2: drains on its own error too (six result D2H still enqueued).
        check_cuda(unsafe { (resident.primary().cu_stream_synchronize)(stream) })
            .map_err(drain_err)?;

        copy_pinned_into(&values_pinned, &mut values);
        copy_pinned_into(&needle_indices_pinned, &mut needle_indices);
        copy_pinned_into(&row_indices_pinned, &mut row_indices);
        copy_pinned_into(&text_starts_pinned, &mut text_starts);
        copy_pinned_into(&text_lens_pinned, &mut text_lens);
        copy_pinned_into(&text_bytes_pinned, &mut text_bytes);
        drop(lease);

        return assemble_i32_text_batch_projection_rows(
            needles,
            row_count,
            projection_count,
            &values,
            &needle_indices,
            &row_indices,
            &text_starts,
            &text_lens,
            &text_bytes,
        );
    } else {
        // ---- legacy blocking default-stream fallback (old driver: no async/pinned symbols) ----
        check_cuda(unsafe {
            cu_memcpy_htod(
                needles_guard.ptr,
                needles.as_ptr().cast::<c_void>(),
                needle_bytes,
            )
        })?;
        check_cuda(unsafe { cu_memset_d8(counters_guard.ptr, 0, COUNTERS_BYTES) })?;
        // P2-M2: launch on a pooled private stream synced individually (no whole-context
        // cuCtxSynchronize); the route owns its output buffers, so no pooled scratch.
        launch_on_pooled_stream(resident, None, |stream, _scratch| unsafe {
            cu_launch_kernel(
                function,
                blocks,
                1,
                1,
                threads_per_block,
                1,
                1,
                0,
                stream,
                args.as_mut_ptr(),
                std::ptr::null_mut(),
            )
        })?;
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                counters_host.as_mut_ptr().cast::<c_void>(),
                counters_guard.ptr,
                COUNTERS_BYTES,
            )
        })?;
        let match_count = u64::from(counters_host[0]);
        let compact_text_len = counters_host[1];
        if match_count > row_count || u64::from(compact_text_len) > text_bytes_len {
            return Err(CudaRuntimeProbeError::InvalidInputLength(usize::MAX));
        }
        (match_count, compact_text_len)
    };

    let match_count_usize = usize::try_from(match_count)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let mut values = vec![0_i32; match_count_usize.saturating_mul(projection_count)];
    if !values.is_empty() {
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                values.as_mut_ptr().cast::<c_void>(),
                values_guard.ptr,
                values.len() * std::mem::size_of::<i32>(),
            )
        })?;
    }
    let mut needle_indices = vec![0_u32; match_count_usize];
    if !needle_indices.is_empty() {
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                needle_indices.as_mut_ptr().cast::<c_void>(),
                indices_guard.ptr,
                needle_indices.len() * std::mem::size_of::<u32>(),
            )
        })?;
    }
    let mut row_indices = vec![0_u64; match_count_usize];
    if !row_indices.is_empty() {
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                row_indices.as_mut_ptr().cast::<c_void>(),
                row_indices_guard.ptr,
                row_indices.len() * std::mem::size_of::<u64>(),
            )
        })?;
    }
    let mut text_starts = vec![0_u32; match_count_usize];
    if !text_starts.is_empty() {
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                text_starts.as_mut_ptr().cast::<c_void>(),
                text_starts_guard.ptr,
                text_starts.len() * std::mem::size_of::<u32>(),
            )
        })?;
    }
    let mut text_lens = vec![0_u32; match_count_usize];
    if !text_lens.is_empty() {
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                text_lens.as_mut_ptr().cast::<c_void>(),
                text_lens_guard.ptr,
                text_lens.len() * std::mem::size_of::<u32>(),
            )
        })?;
    }
    let mut text_bytes = vec![
        0_u8;
        usize::try_from(compact_text_len).map_err(|_| {
            CudaRuntimeProbeError::InvalidInputLength(usize::MAX)
        })?
    ];
    if !text_bytes.is_empty() {
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                text_bytes.as_mut_ptr().cast::<c_void>(),
                text_bytes_guard.ptr,
                text_bytes.len(),
            )
        })?;
    }

    drop(counters_guard);
    drop(text_bytes_guard);
    drop(text_lens_guard);
    drop(text_starts_guard);
    drop(row_indices_guard);
    drop(indices_guard);
    drop(values_guard);
    drop(needles_guard);
    assemble_i32_text_batch_projection_rows(
        needles,
        row_count,
        projection_count,
        &values,
        &needle_indices,
        &row_indices,
        &text_starts,
        &text_lens,
        &text_bytes,
    )
}

/// Queue ONE stream-ordered (async) D2H of `dst.len() * size_of::<T>()` bytes from `device_ptr`
/// into a pooled pinned host staging buffer if one can be leased (truly-async + DMA-fast), else
/// directly into `dst` (still async, just from pageable memory). Returns the pinned lease (kept
/// alive by the caller until after the stream sync, then drained by `copy_pinned_into`), or
/// `None` when the copy went straight to `dst`. An empty `dst` queues nothing and returns `None`.
fn stage_result_dtoh_async<'a, T>(
    primary: &'a GpuPrimaryContext,
    dtoh_async: unsafe extern "C" fn(*mut c_void, u64, usize, *mut c_void) -> i32,
    stream: *mut c_void,
    device_ptr: u64,
    dst: &mut [T],
) -> Result<Option<PinnedHostLease<'a>>, CudaRuntimeProbeError> {
    let bytes = std::mem::size_of_val(dst);
    if bytes == 0 {
        return Ok(None);
    }
    match primary.lease_pinned_host_buffer(bytes) {
        Some(pinned) => {
            check_cuda(unsafe { dtoh_async(pinned.ptr, device_ptr, bytes, stream) })?;
            Ok(Some(pinned))
        }
        None => {
            check_cuda(unsafe {
                dtoh_async(dst.as_mut_ptr().cast::<c_void>(), device_ptr, bytes, stream)
            })?;
            Ok(None)
        }
    }
}

/// Copy a completed pinned-host staging buffer into its owned `dst` Vec by typed pointer (no-op
/// when the staged copy went straight to `dst`, i.e. `pinned` is `None`). Must be called only
/// after the stream sync that completed the D2H into the pinned region.
fn copy_pinned_into<T>(pinned: &Option<PinnedHostLease<'_>>, dst: &mut [T]) {
    if let Some(pinned) = pinned {
        // SAFETY: the matching `stage_result_dtoh_async` leased `pinned` with capacity ≥
        // size_of_val(dst) and the stream sync completed the D2H of exactly that many bytes;
        // pinned host memory is page-aligned, so the typed read is well-aligned for `T`.
        unsafe {
            std::ptr::copy_nonoverlapping(pinned.ptr.cast::<T>(), dst.as_mut_ptr(), dst.len());
        }
    }
}

/// Shared row assembler for both the async and blocking text-route paths: validate the
/// device-returned indices and stitch the per-row arrays into `CudaI32TextBatchProjectionRow`s
/// with byte-identical layout to the pre-async path (same field semantics, same column order).
#[allow(clippy::too_many_arguments)]
fn assemble_i32_text_batch_projection_rows(
    needles: &[i32],
    row_count: u64,
    projection_count: usize,
    values: &[i32],
    needle_indices: &[u32],
    row_indices: &[u64],
    text_starts: &[u32],
    text_lens: &[u32],
    text_bytes: &[u8],
) -> Result<Vec<CudaI32TextBatchProjectionRow>, CudaRuntimeProbeError> {
    values
        .chunks_exact(projection_count)
        .zip(needle_indices.iter().copied())
        .zip(row_indices.iter().copied())
        .zip(text_starts.iter().copied())
        .zip(text_lens.iter().copied())
        .map(
            |((((row, needle_index), row_index), text_start), text_len)| {
                let needle_index = usize::try_from(needle_index)
                    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
                if needle_index >= needles.len() {
                    return Err(CudaRuntimeProbeError::InvalidInputLength(needle_index));
                }
                if row_index >= row_count {
                    return Err(CudaRuntimeProbeError::InvalidInputLength(usize::MAX));
                }
                let text_start = usize::try_from(text_start)
                    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
                let text_len = usize::try_from(text_len)
                    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
                let text_end = text_start
                    .checked_add(text_len)
                    .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
                if text_end > text_bytes.len() {
                    return Err(CudaRuntimeProbeError::InvalidInputLength(text_end));
                }
                let text = std::str::from_utf8(&text_bytes[text_start..text_end])
                    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(text_len))?
                    .to_string();
                Ok(CudaI32TextBatchProjectionRow {
                    needle_index,
                    row_index,
                    values: row.to_vec(),
                    text,
                })
            },
        )
        .collect()
}

fn launch_cuda_resident_i32_equal_row_indices(
    resident: &CudaResidentDeviceMemory,
    filters: &[(u64, i32)],
    row_count: u64,
) -> Result<Vec<u64>, CudaRuntimeProbeError> {
    type CuMemsetD8 = unsafe extern "C" fn(u64, u8, usize) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;

    const MAX_FILTERS: usize = 4;
    const PTX: &[u8] = br#"
.version 6.0
.target sm_30
.address_size 64

.visible .entry gpu_db_resident_i32_equal_row_indices(
    .param .u64 resident_ptr,
    .param .u64 row_count,
    .param .u32 filter_count,
    .param .u64 offset0,
    .param .u64 offset1,
    .param .u64 offset2,
    .param .u64 offset3,
    .param .s32 needle0,
    .param .s32 needle1,
    .param .s32 needle2,
    .param .s32 needle3,
    .param .u64 out_indices_ptr,
    .param .u64 out_count_ptr
)
{
    .reg .pred %p_out;
    .reg .pred %p_done;
    .reg .pred %p_match;
    .reg .pred %p_check;
    .reg .u32 %r_tid;
    .reg .u32 %r_block;
    .reg .u32 %r_block_dim;
    .reg .u32 %idx32;
    .reg .u64 %idx;
    .reg .u64 %rows;
    .reg .u32 %filters;
    .reg .u64 %resident;
    .reg .u64 %offset0;
    .reg .u64 %offset1;
    .reg .u64 %offset2;
    .reg .u64 %offset3;
    .reg .s32 %needle0;
    .reg .s32 %needle1;
    .reg .s32 %needle2;
    .reg .s32 %needle3;
    .reg .u64 %out_indices;
    .reg .u64 %out_count;
    .reg .u64 %row_byte;
    .reg .u64 %addr;
    .reg .u32 %slot;
    .reg .u64 %out_addr;
    .reg .u64 %slot64;
    .reg .u32 %one;
    .reg .s32 %r_value;

    ld.param.u64 %resident, [resident_ptr];
    ld.param.u64 %rows, [row_count];
    ld.param.u32 %filters, [filter_count];
    ld.param.u64 %offset0, [offset0];
    ld.param.u64 %offset1, [offset1];
    ld.param.u64 %offset2, [offset2];
    ld.param.u64 %offset3, [offset3];
    ld.param.s32 %needle0, [needle0];
    ld.param.s32 %needle1, [needle1];
    ld.param.s32 %needle2, [needle2];
    ld.param.s32 %needle3, [needle3];
    ld.param.u64 %out_indices, [out_indices_ptr];
    ld.param.u64 %out_count, [out_count_ptr];

    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_block, %ctaid.x;
    mov.u32 %r_block_dim, %ntid.x;
    mad.lo.u32 %idx32, %r_block, %r_block_dim, %r_tid;
    cvt.u64.u32 %idx, %idx32;

    setp.ge.u64 %p_out, %idx, %rows;
    @%p_out bra DONE;

    setp.eq.u32 %p_done, %filters, 0;
    @%p_done bra DONE;

    mul.lo.u64 %row_byte, %idx, 4;

    add.u64 %addr, %resident, %offset0;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %r_value, [%addr];
    setp.eq.s32 %p_match, %r_value, %needle0;
    @!%p_match bra DONE;

    setp.le.u32 %p_check, %filters, 1;
    @%p_check bra MATCHED;
    add.u64 %addr, %resident, %offset1;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %r_value, [%addr];
    setp.eq.s32 %p_match, %r_value, %needle1;
    @!%p_match bra DONE;

    setp.le.u32 %p_check, %filters, 2;
    @%p_check bra MATCHED;
    add.u64 %addr, %resident, %offset2;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %r_value, [%addr];
    setp.eq.s32 %p_match, %r_value, %needle2;
    @!%p_match bra DONE;

    setp.le.u32 %p_check, %filters, 3;
    @%p_check bra MATCHED;
    add.u64 %addr, %resident, %offset3;
    add.u64 %addr, %addr, %row_byte;
    ld.global.s32 %r_value, [%addr];
    setp.eq.s32 %p_match, %r_value, %needle3;
    @!%p_match bra DONE;

MATCHED:
    mov.u32 %one, 1;
    atom.global.add.u32 %slot, [%out_count], %one;
    cvt.u64.u32 %slot64, %slot;
    mul.lo.u64 %out_addr, %slot64, 8;
    add.u64 %out_addr, %out_indices, %out_addr;
    st.global.u64 [%out_addr], %idx;

DONE:
    ret;
}
"#;

    if filters.is_empty() || filters.len() > MAX_FILTERS {
        return Err(CudaRuntimeProbeError::InvalidInputLength(filters.len()));
    }
    if row_count == 0 {
        return Ok(Vec::new());
    }
    for (byte_offset, _) in filters {
        let bytes = row_count
            .checked_mul(std::mem::size_of::<i32>() as u64)
            .and_then(|bytes| byte_offset.checked_add(bytes))
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
        if bytes > resident.metadata().allocated_bytes {
            return Err(CudaRuntimeProbeError::InvalidInputLength(bytes as usize));
        }
    }
    let row_count_u32 = u32::try_from(row_count)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let output_bytes = usize::try_from(
        row_count
            .checked_mul(std::mem::size_of::<u64>() as u64)
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?,
    )
    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;

    // P2-M2 (row-index-gather async lever): this gather route had the same default/NULL-stream-
    // serialized wall as the other resident routes — a per-call `cuMemAlloc` (indices + count) +
    // `cuMemFree`, a blocking default-stream `cuMemsetD8` to zero the atomic-append counter, a
    // per-call `cuModuleLoadData` re-JIT, a whole-context sync (the legacy event-timing helper
    // falls back to `cuCtxSynchronize`, and even its timed path records events on the NULL stream),
    // and two blocking default-stream `cuMemcpyDtoH` (the count, then the indices). The driver
    // serializes those memory ops + the JIT + the whole-context sync across concurrent readers, so
    // a per-section breakdown localized ~73% of the engine's c64 multi-column cascade wall to this
    // single launch (~20.7 ms/call @c64) — no scaling. Unlike the serial compare/range kernels,
    // THIS kernel is already parallel (one thread per row + an `atom.global.add` append), so the
    // wall is purely the per-call orchestration, not the kernel — removing the serializer should
    // restore concurrency. The fix moves the counter-zero (memset), the kernel, and both D2H onto
    // the route's pooled private stream via the `*Async` variants behind exactly TWO
    // `cuStreamSynchronize` (one after the kernel so the device-computed match count is readable to
    // size the indices read; one after the indices D2H), stages both readbacks through pooled
    // pinned (page-locked) host buffers, leases its device output buffers + private stream + module
    // from the shared pools/cache (no per-call alloc/JIT), and removes the whole-context sync. No
    // HtoD is needed: the kernel takes the offsets/needles as scalar params; the count buffer is
    // the only region that must be zeroed (the indices buffer is read back only over [0, count) so
    // pooled stale bytes are never observed). The PTX kernel + grid shape are byte-for-byte
    // unchanged, so the appended indices — and thus the result bytes — are identical.
    //
    // The whole async path is gated on the optional async + pinned-host driver symbols; on an old
    // driver lacking them the route keeps a blocking path (still cached-module + pooled-buffer +
    // pooled-stream, just blocking memset/D2H), so correctness is unconditional and only the
    // acceleration is best-effort.
    let cu_memset_d8 = unsafe {
        resident
            .lib()
            .get::<CuMemsetD8>(b"cuMemsetD8_v2\0")
            .or_else(|_| resident.lib().get::<CuMemsetD8>(b"cuMemsetD8\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };

    let async_ops = match (
        resident.primary().cu_memcpy_dtoh_async,
        resident.primary().cu_memset_d8_async,
    ) {
        (Some(dtoh), Some(memset)) => Some((dtoh, memset)),
        _ => None,
    };

    // Pooled device output buffers (no per-call cuMemAlloc/cuMemFree). Reused buffers are NOT
    // zeroed; only the atomic-append counter is memset, and the indices buffer is read back only
    // over the [0, count) prefix — so stale bytes are never observed.
    let indices_guard = resident
        .primary()
        .lease_device_buffer(output_bytes.max(1))?;
    const COUNT_BYTES: usize = std::mem::size_of::<u32>();
    let count_guard = resident.primary().lease_device_buffer(COUNT_BYTES)?;

    // P2-M2: cached module (no per-launch cuModuleLoadData) — keyed by the kernel entry name and
    // launched concurrently on distinct streams.
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let function = resident
        .primary()
        .cached_function(c"gpu_db_resident_i32_equal_row_indices", &ptx)?;

    let mut resident_arg = resident.device_ptr();
    let mut rows_arg = row_count;
    let mut filter_count_arg = u32::try_from(filters.len())
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(filters.len()))?;
    let mut offsets = [0_u64; MAX_FILTERS];
    let mut needles = [0_i32; MAX_FILTERS];
    for (idx, (offset, needle)) in filters.iter().enumerate() {
        offsets[idx] = *offset;
        needles[idx] = *needle;
    }
    let mut output_arg = indices_guard.ptr;
    let mut count_arg = count_guard.ptr;
    let mut args = [
        (&mut resident_arg as *mut u64).cast::<c_void>(),
        (&mut rows_arg as *mut u64).cast::<c_void>(),
        (&mut filter_count_arg as *mut u32).cast::<c_void>(),
        (&mut offsets[0] as *mut u64).cast::<c_void>(),
        (&mut offsets[1] as *mut u64).cast::<c_void>(),
        (&mut offsets[2] as *mut u64).cast::<c_void>(),
        (&mut offsets[3] as *mut u64).cast::<c_void>(),
        (&mut needles[0] as *mut i32).cast::<c_void>(),
        (&mut needles[1] as *mut i32).cast::<c_void>(),
        (&mut needles[2] as *mut i32).cast::<c_void>(),
        (&mut needles[3] as *mut i32).cast::<c_void>(),
        (&mut output_arg as *mut u64).cast::<c_void>(),
        (&mut count_arg as *mut u64).cast::<c_void>(),
    ];
    let threads_per_block = 128;
    let blocks = row_count_u32.div_ceil(threads_per_block);

    // This kernel is already parallel (one thread per row + an `atom.global.add` ordered append);
    // its grid shape is preserved exactly so the appended order — and thus the result bytes — is
    // identical (the append order is the atomic schedule, which the grid shape does not change).
    if let Some((dtoh_async, memset_async)) = async_ops {
        // ---- async-on-pooled-stream path (the lever) ----
        // Bind the shared primary context (idempotent) and lease the pooled private stream.
        resident.primary().set_current()?;
        struct StreamLease<'a> {
            primary: &'a GpuPrimaryContext,
            pooled: Option<PooledStream>,
        }
        impl Drop for StreamLease<'_> {
            fn drop(&mut self) {
                if let Some(pooled) = self.pooled.take() {
                    self.primary.release_pooled_stream(pooled);
                }
            }
        }
        let lease = StreamLease {
            primary: resident.primary(),
            pooled: Some(resident.primary().acquire_pooled_stream()?),
        };
        let pooled = lease.pooled.as_ref().expect("pooled stream just set");
        let stream = pooled.stream;
        let timed = !pooled.start_event.is_null() && !pooled.stop_event.is_null();

        // HARDENING (error-path stream drain): once an async op is enqueued on this private
        // stream, an early `?` would unwind the locals — returning the device + pinned buffer
        // leases to their shared pools while enqueued ops may still be in flight, a
        // use-after-free window for whoever leases those buffers next. So every fallible op from
        // the first async enqueue through each covering `cuStreamSynchronize` propagates its error
        // through `drain_err`, a best-effort blocking sync (result ignored) that drains the stream
        // FIRST, *then* yields the original error. `map_err` runs the closure at the error site
        // BEFORE `?` returns and hence before ANY local Drop, so it precedes the release of every
        // lease regardless of scope; on `Ok` the closure is not invoked, so the success path adds
        // nothing beyond the two explicit syncs below.
        let drain_err = |err: CudaRuntimeProbeError| -> CudaRuntimeProbeError {
            // SAFETY: `stream` is the live pooled private stream; a blocking synchronize on it is
            // valid from this thread (the primary context is current). The result is intentionally
            // ignored — this is a best-effort drain on an already-failing path.
            unsafe {
                let _ = (resident.primary().cu_stream_synchronize)(stream);
            }
            err
        };

        // (1) Stream-ordered zero of the atomic-append counter, then the kernel launch (no HtoD
        // needed for this route — the offsets/needles are scalar params).
        check_cuda(unsafe { memset_async(count_guard.ptr, 0, COUNT_BYTES, stream) })
            .map_err(drain_err)?;
        if timed {
            check_cuda(unsafe { (resident.primary().cu_event_record)(pooled.start_event, stream) })
                .map_err(drain_err)?;
        }
        check_cuda(unsafe {
            cu_launch_kernel(
                function,
                blocks,
                1,
                1,
                threads_per_block,
                1,
                1,
                0,
                stream,
                args.as_mut_ptr(),
                std::ptr::null_mut(),
            )
        })
        .map_err(drain_err)?;
        if timed {
            check_cuda(unsafe { (resident.primary().cu_event_record)(pooled.stop_event, stream) })
                .map_err(drain_err)?;
        }

        // (2) Stream-ordered read of the 4-byte match count, then sync #1: now the kernel is
        // complete and the count is known, so the indices read can be sized. The count stages
        // through a small pooled pinned host buffer for a truly-async DMA.
        let mut match_count = 0_u32;
        let count_pinned = resident.primary().lease_pinned_host_buffer(COUNT_BYTES);
        let count_dst: *mut c_void = count_pinned
            .as_ref()
            .map(|p| p.ptr)
            .unwrap_or_else(|| (&mut match_count as *mut u32).cast::<c_void>());
        check_cuda(unsafe { dtoh_async(count_dst, count_guard.ptr, COUNT_BYTES, stream) })
            .map_err(drain_err)?;
        // Covering sync #1: drains on its own error too (the count D2H is still enqueued).
        check_cuda(unsafe { (resident.primary().cu_stream_synchronize)(stream) })
            .map_err(drain_err)?;
        if let Some(pinned) = &count_pinned {
            // SAFETY: the sync above completed the 4-byte D2H into the pinned region; read the
            // u32 out by typed pointer (pinned host memory is page-aligned).
            unsafe {
                match_count = pinned.ptr.cast::<u32>().read();
            }
        }
        if timed {
            let mut elapsed_ms = 0.0_f32;
            check_cuda(unsafe {
                (resident.primary().cu_event_elapsed_time)(
                    &mut elapsed_ms,
                    pooled.start_event,
                    pooled.stop_event,
                )
            })?;
            resident.record_kernel_event_elapsed_us(Some(
                (f64::from(elapsed_ms) * 1_000.0).ceil() as u64
            ));
        } else {
            resident.record_kernel_event_elapsed_us(None);
        }

        let match_count = u64::from(match_count);
        if match_count > row_count {
            return Err(CudaRuntimeProbeError::InvalidInputLength(usize::MAX));
        }
        let match_count_usize = usize::try_from(match_count)
            .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;

        // (3) Stream-ordered result D2H of the populated [0, count) indices prefix into a pooled
        // pinned host buffer, then ONE sync #2; copy the pinned bytes into the owned Vec.
        let mut indices = vec![0_u64; match_count_usize];
        let indices_pinned = stage_result_dtoh_async(
            resident.primary(),
            dtoh_async,
            stream,
            indices_guard.ptr,
            &mut indices,
        )
        .map_err(drain_err)?;
        // Covering sync #2: drains on its own error too (the indices D2H is still enqueued).
        check_cuda(unsafe { (resident.primary().cu_stream_synchronize)(stream) })
            .map_err(drain_err)?;
        copy_pinned_into(&indices_pinned, &mut indices);
        drop(lease);
        // Correctness (deterministic ascending order): the kernel appends matching row indices in
        // `atom.global.add` SCHEDULE order, which is ascending only when all matches land in a
        // single warp (<=32). For >32 matches the append order is non-deterministic across warps,
        // so a positional gather would emit rows in a non-deterministic order that diverges from
        // the CPU/non-resident reference (ascending) and breaks the partitioned ascending-merge.
        // Sort host-side over [0, count) so the route always returns ascending indices identical to
        // the reference. Cost is O(k log k) host-side, dominated by the per-row D2H gather above.
        indices.sort_unstable();
        Ok(indices)
    } else {
        // ---- legacy blocking fallback (old driver: no async/pinned symbols) ----
        // Still cached-module + pooled-buffer + pooled-stream (per-stream sync, no whole-context
        // cuCtxSynchronize); just blocking memset/D2H. The route owns its output buffers, so no
        // pooled scratch is requested.
        check_cuda(unsafe { cu_memset_d8(count_guard.ptr, 0, COUNT_BYTES) })?;
        launch_on_pooled_stream(resident, None, |stream, _scratch| unsafe {
            cu_launch_kernel(
                function,
                blocks,
                1,
                1,
                threads_per_block,
                1,
                1,
                0,
                stream,
                args.as_mut_ptr(),
                std::ptr::null_mut(),
            )
        })?;

        let mut match_count = 0_u32;
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                (&mut match_count as *mut u32).cast::<c_void>(),
                count_guard.ptr,
                COUNT_BYTES,
            )
        })?;
        let match_count = u64::from(match_count);
        if match_count > row_count {
            return Err(CudaRuntimeProbeError::InvalidInputLength(usize::MAX));
        }
        let match_count_usize = usize::try_from(match_count)
            .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
        let mut indices = vec![0_u64; match_count_usize];
        if !indices.is_empty() {
            check_cuda(unsafe {
                cu_memcpy_dtoh(
                    indices.as_mut_ptr().cast::<c_void>(),
                    indices_guard.ptr,
                    indices.len() * std::mem::size_of::<u64>(),
                )
            })?;
        }
        // Same deterministic-ascending ordering guarantee as the async path above (the kernel's
        // atom-schedule append order is non-deterministic for >32 matches); sort host-side so this
        // fallback returns indices identical to the CPU/non-resident reference.
        indices.sort_unstable();
        Ok(indices)
    }
}

fn launch_cuda_resident_i32_between_row_indices(
    resident: &CudaResidentDeviceMemory,
    byte_offset: u64,
    row_count: u64,
    lower_inclusive: i32,
    upper_inclusive: i32,
) -> Result<Vec<u64>, CudaRuntimeProbeError> {
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;

    if lower_inclusive > upper_inclusive || row_count == 0 {
        return Ok(Vec::new());
    }
    let bytes = row_count
        .checked_mul(std::mem::size_of::<i32>() as u64)
        .and_then(|bytes| byte_offset.checked_add(bytes))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    if bytes > resident.metadata().allocated_bytes {
        return Err(CudaRuntimeProbeError::InvalidInputLength(bytes as usize));
    }
    let bytes_usize = usize::try_from(bytes - byte_offset)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let mut raw_values = vec![0_u8; bytes_usize];
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            raw_values.as_mut_ptr().cast::<c_void>(),
            resident.device_ptr() + byte_offset,
            bytes_usize,
        )
    })?;

    let mut indices = Vec::new();
    for (idx, chunk) in raw_values
        .chunks_exact(std::mem::size_of::<i32>())
        .enumerate()
    {
        let value = i32::from_le_bytes(
            chunk
                .try_into()
                .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(raw_values.len()))?,
        );
        if value >= lower_inclusive && value <= upper_inclusive {
            indices.push(
                u64::try_from(idx)
                    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?,
            );
        }
    }
    Ok(indices)
}

fn copy_cuda_resident_text_rows(
    resident: &CudaResidentDeviceMemory,
    offsets_byte_offset: u64,
    bytes_byte_offset: u64,
    bytes_len: u64,
    row_indices: &[u64],
) -> Result<Vec<String>, CudaRuntimeProbeError> {
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;

    if row_indices.is_empty() {
        return Ok(Vec::new());
    }

    let min_row_idx = row_indices.iter().copied().min().unwrap_or(0);
    let max_row_idx = row_indices.iter().copied().max().unwrap_or(0);
    let offset_count = max_row_idx
        .checked_sub(min_row_idx)
        .and_then(|span| span.checked_add(2))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let offsets_offset = min_row_idx
        .checked_mul(std::mem::size_of::<u64>() as u64)
        .and_then(|offset| offsets_byte_offset.checked_add(offset))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let offsets_end = offsets_byte_offset
        .checked_add(
            max_row_idx
                .checked_add(2)
                .and_then(|count| count.checked_mul(std::mem::size_of::<u64>() as u64))
                .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?,
        )
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let bytes_end = bytes_byte_offset
        .checked_add(bytes_len)
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    if offsets_end > resident.metadata().allocated_bytes
        || bytes_end > resident.metadata().allocated_bytes
    {
        return Err(CudaRuntimeProbeError::InvalidInputLength(
            offsets_end.max(bytes_end) as usize,
        ));
    }

    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };

    let mut offsets = vec![
        0_u64;
        usize::try_from(offset_count).map_err(|_| {
            CudaRuntimeProbeError::InvalidInputLength(usize::MAX)
        })?
    ];
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            offsets.as_mut_ptr().cast::<c_void>(),
            resident.device_ptr() + offsets_offset,
            offsets
                .len()
                .checked_mul(std::mem::size_of::<u64>())
                .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?,
        )
    })?;

    let mut spans = Vec::with_capacity(row_indices.len());
    let mut min_text_start = u64::MAX;
    let mut max_text_end = 0_u64;
    for row_idx in row_indices {
        let offset_idx = row_idx
            .checked_sub(min_row_idx)
            .and_then(|idx| usize::try_from(idx).ok())
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
        let start = offsets[offset_idx];
        let end = offsets[offset_idx + 1];
        if start > end || end > bytes_len {
            return Err(CudaRuntimeProbeError::InvalidInputLength(end as usize));
        }
        min_text_start = min_text_start.min(start);
        max_text_end = max_text_end.max(end);
        spans.push((start, end));
    }

    let text_span_len = max_text_end
        .checked_sub(min_text_start)
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let mut text_bytes = vec![
        0_u8;
        usize::try_from(text_span_len).map_err(|_| {
            CudaRuntimeProbeError::InvalidInputLength(usize::MAX)
        })?
    ];
    if text_span_len > 0 {
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                text_bytes.as_mut_ptr().cast::<c_void>(),
                resident.device_ptr() + bytes_byte_offset + min_text_start,
                text_bytes.len(),
            )
        })?;
    }

    let mut values = Vec::with_capacity(row_indices.len());
    for (start, end) in spans {
        let value_len = usize::try_from(end - start)
            .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
        let value_start = start
            .checked_sub(min_text_start)
            .and_then(|offset| usize::try_from(offset).ok())
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
        let value_end = value_start
            .checked_add(value_len)
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
        let value = std::str::from_utf8(&text_bytes[value_start..value_end])
            .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(value_len))?;
        values.push(value.to_string());
    }
    Ok(values)
}

fn launch_cuda_resident_i32_sum(
    resident: &CudaResidentDeviceMemory,
    byte_offset: u64,
    row_count: u64,
) -> Result<i64, CudaRuntimeProbeError> {
    type CuMemsetD8Async = unsafe extern "C" fn(u64, u8, usize, *mut c_void) -> i32;
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;

    // P2-M2 — the i32-sum kernel is already a parallel grid-stride reduction (each thread sums a
    // strided slice into an s64, then `atom.global.add.u64`s it into one output). This migrates the
    // LAUNCH off the default/null stream + per-call cuModuleLoadData (re-JIT) + per-call cuMemAlloc
    // onto a pooled private stream with a cached module + async-memset scratch via
    // `launch_on_pooled_stream` (event-timed, covering-synced, drained-on-error). Kernel unchanged.

    const PTX: &[u8] = br#"
.version 6.0
.target sm_30
.address_size 64

.visible .entry gpu_db_resident_i32_sum(
    .param .u64 resident_ptr,
    .param .u64 byte_offset,
    .param .u64 row_count,
    .param .u64 out_ptr
)
{
    .reg .pred %p_done;
    .reg .u64 %resident;
    .reg .u64 %offset;
    .reg .u64 %rows;
    .reg .u64 %out;
    .reg .u64 %base;
    .reg .u64 %idx;
    .reg .u64 %stride;
    .reg .u64 %addr;
    .reg .u32 %r_block;
    .reg .u32 %r_block_dim;
    .reg .u32 %thread;
    .reg .u32 %grid_dim;
    .reg .u64 %wide_block;
    .reg .u64 %wide_thread;
    .reg .u64 %wide_block_dim;
    .reg .u64 %wide_grid_dim;
    .reg .u64 %sum_bits;
    .reg .u64 %ignored;
    .reg .s64 %sum;
    .reg .s64 %wide;
    .reg .s32 %r_value;

    ld.param.u64 %resident, [resident_ptr];
    ld.param.u64 %offset, [byte_offset];
    ld.param.u64 %rows, [row_count];
    ld.param.u64 %out, [out_ptr];

    add.u64 %base, %resident, %offset;
    mov.u32 %r_block, %ctaid.x;
    mov.u32 %r_block_dim, %ntid.x;
    mov.u32 %thread, %tid.x;
    mov.u32 %grid_dim, %nctaid.x;
    cvt.u64.u32 %wide_block, %r_block;
    cvt.u64.u32 %wide_thread, %thread;
    cvt.u64.u32 %wide_block_dim, %r_block_dim;
    cvt.u64.u32 %wide_grid_dim, %grid_dim;
    mul.lo.u64 %idx, %wide_block, %wide_block_dim;
    add.u64 %idx, %idx, %wide_thread;
    mul.lo.u64 %stride, %wide_grid_dim, %wide_block_dim;
    mov.s64 %sum, 0;

loop:
    setp.ge.u64 %p_done, %idx, %rows;
    @%p_done bra done;
    mul.lo.u64 %addr, %idx, 4;
    add.u64 %addr, %base, %addr;
    ld.global.s32 %r_value, [%addr];
    cvt.s64.s32 %wide, %r_value;
    add.s64 %sum, %sum, %wide;
    add.u64 %idx, %idx, %stride;
    bra loop;

done:
    cvt.u64.s64 %sum_bits, %sum;
    atom.global.add.u64 %ignored, [%out], %sum_bits;
    ret;
}
"#;

    let bytes = row_count
        .checked_mul(std::mem::size_of::<i32>() as u64)
        .and_then(|bytes| byte_offset.checked_add(bytes))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    if bytes > resident.metadata().allocated_bytes {
        return Err(CudaRuntimeProbeError::InvalidInputLength(bytes as usize));
    }

    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memset_d8_async = unsafe {
        resident
            .lib()
            .get::<CuMemsetD8Async>(b"cuMemsetD8Async\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };

    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let function = resident
        .primary()
        .cached_function(c"gpu_db_resident_i32_sum", &ptx)?;

    let block_dim = 256_u32;
    let grid_dim = if row_count == 0 {
        1
    } else {
        row_count.div_ceil(u64::from(block_dim)).min(1024) as u32
    };

    let mut output_bytes = [0_u8; std::mem::size_of::<i64>()];
    launch_on_pooled_stream(resident, Some(&mut output_bytes), |stream, output_ptr| {
        // Zero the 8-byte scratch on the stream (the kernel atom-adds into it), ordered before the
        // kernel launch on the same stream.
        let memset_rc =
            unsafe { cu_memset_d8_async(output_ptr, 0, std::mem::size_of::<i64>(), stream) };
        if memset_rc != 0 {
            return memset_rc;
        }
        let mut resident_arg = resident.device_ptr();
        let mut offset_arg = byte_offset;
        let mut rows_arg = row_count;
        let mut output_arg = output_ptr;
        let mut args = [
            (&mut resident_arg as *mut u64).cast::<c_void>(),
            (&mut offset_arg as *mut u64).cast::<c_void>(),
            (&mut rows_arg as *mut u64).cast::<c_void>(),
            (&mut output_arg as *mut u64).cast::<c_void>(),
        ];
        unsafe {
            cu_launch_kernel(
                function,
                grid_dim,
                1,
                1,
                block_dim,
                1,
                1,
                0,
                stream,
                args.as_mut_ptr(),
                std::ptr::null_mut(),
            )
        }
    })?;

    Ok(i64::from_le_bytes(output_bytes))
}

#[repr(C)]
struct CudaI32StatsRaw {
    count: u64,
    sum: i64,
    min: i32,
    max: i32,
}

fn launch_cuda_resident_i32_between_stats(
    resident: &CudaResidentDeviceMemory,
    byte_offset: u64,
    row_count: u64,
    lower_inclusive: i32,
    upper_inclusive: i32,
) -> Result<CudaI32Stats, CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;

    // P2-M2 — the between-stats kernel is already a parallel grid-stride reduction (each thread
    // computes count/sum/min/max for the [lower,upper] predicate, then atomic add count/sum +
    // atomic min/max into one 24-byte output struct). Migrate the LAUNCH off the default/null stream
    // + per-call cuModuleLoadData (re-JIT) + per-call cuMemAlloc + blocking H2D/D2H onto a pooled
    // private stream with a cached module and an ASYNC H2D of the init struct
    // (count=0,sum=0,min=INT_MAX,max=INT_MIN — the min/max sentinels can't be memset like sum's plain
    // zero) into the pooled scratch BEFORE the kernel, via launch_on_pooled_stream (event-timed,
    // covering-synced, drained-on-error). Kernel unchanged.

    const PTX: &[u8] = br#"
.version 6.0
.target sm_30
.address_size 64

.visible .entry gpu_db_resident_i32_between_stats(
    .param .u64 resident_ptr,
    .param .u64 byte_offset,
    .param .u64 row_count,
    .param .s32 lower_inclusive,
    .param .s32 upper_inclusive,
    .param .u64 out_ptr
)
{
    .reg .pred %p_done;
    .reg .pred %p_ge_lower;
    .reg .pred %p_le_upper;
    .reg .pred %p_match;
    .reg .u64 %resident;
    .reg .u64 %offset;
    .reg .u64 %rows;
    .reg .u64 %out;
    .reg .u64 %base;
    .reg .u64 %idx;
    .reg .u64 %stride;
    .reg .u64 %addr;
    .reg .u64 %count_addr;
    .reg .u64 %sum_addr;
    .reg .u64 %min_addr;
    .reg .u64 %max_addr;
    .reg .u32 %r_block;
    .reg .u32 %r_block_dim;
    .reg .u32 %thread;
    .reg .u32 %grid_dim;
    .reg .u64 %wide_block;
    .reg .u64 %wide_thread;
    .reg .u64 %wide_block_dim;
    .reg .u64 %wide_grid_dim;
    .reg .u64 %count;
    .reg .u64 %sum_bits;
    .reg .u64 %ignored64;
    .reg .s32 %ignored32;
    .reg .s64 %sum;
    .reg .s64 %wide;
    .reg .s32 %r_value;
    .reg .s32 %lower;
    .reg .s32 %upper;
    .reg .s32 %min;
    .reg .s32 %max;

    ld.param.u64 %resident, [resident_ptr];
    ld.param.u64 %offset, [byte_offset];
    ld.param.u64 %rows, [row_count];
    ld.param.s32 %lower, [lower_inclusive];
    ld.param.s32 %upper, [upper_inclusive];
    ld.param.u64 %out, [out_ptr];

    add.u64 %base, %resident, %offset;
    mov.u32 %r_block, %ctaid.x;
    mov.u32 %r_block_dim, %ntid.x;
    mov.u32 %thread, %tid.x;
    mov.u32 %grid_dim, %nctaid.x;
    cvt.u64.u32 %wide_block, %r_block;
    cvt.u64.u32 %wide_thread, %thread;
    cvt.u64.u32 %wide_block_dim, %r_block_dim;
    cvt.u64.u32 %wide_grid_dim, %grid_dim;
    mul.lo.u64 %idx, %wide_block, %wide_block_dim;
    add.u64 %idx, %idx, %wide_thread;
    mul.lo.u64 %stride, %wide_grid_dim, %wide_block_dim;
    mov.u64 %count, 0;
    mov.s64 %sum, 0;
    mov.s32 %min, 2147483647;
    mov.s32 %max, -2147483648;

loop:
    setp.ge.u64 %p_done, %idx, %rows;
    @%p_done bra done;
    mul.lo.u64 %addr, %idx, 4;
    add.u64 %addr, %base, %addr;
    ld.global.s32 %r_value, [%addr];
    setp.ge.s32 %p_ge_lower, %r_value, %lower;
    setp.le.s32 %p_le_upper, %r_value, %upper;
    and.pred %p_match, %p_ge_lower, %p_le_upper;
    @!%p_match bra next;

    cvt.s64.s32 %wide, %r_value;
    add.s64 %sum, %sum, %wide;
    add.u64 %count, %count, 1;
    min.s32 %min, %min, %r_value;
    max.s32 %max, %max, %r_value;

next:
    add.u64 %idx, %idx, %stride;
    bra loop;

done:
    setp.eq.u64 %p_done, %count, 0;
    @%p_done bra ret_done;
    mov.u64 %count_addr, %out;
    atom.global.add.u64 %ignored64, [%count_addr], %count;
    add.u64 %sum_addr, %out, 8;
    cvt.u64.s64 %sum_bits, %sum;
    atom.global.add.u64 %ignored64, [%sum_addr], %sum_bits;
    add.u64 %min_addr, %out, 16;
    atom.global.min.s32 %ignored32, [%min_addr], %min;
    add.u64 %max_addr, %out, 20;
    atom.global.max.s32 %ignored32, [%max_addr], %max;

ret_done:
    ret;
}
"#;

    let bytes = row_count
        .checked_mul(std::mem::size_of::<i32>() as u64)
        .and_then(|bytes| byte_offset.checked_add(bytes))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    if bytes > resident.metadata().allocated_bytes {
        return Err(CudaRuntimeProbeError::InvalidInputLength(bytes as usize));
    }

    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let htod_async = resident
        .primary()
        .cu_memcpy_htod_async
        .ok_or(CudaRuntimeProbeError::DriverLibraryUnavailable)?;

    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let function = resident
        .primary()
        .cached_function(c"gpu_db_resident_i32_between_stats", &ptx)?;

    let block_dim = 256_u32;
    let grid_dim = if row_count == 0 {
        1
    } else {
        row_count.div_ceil(u64::from(block_dim)).min(1024) as u32
    };

    // Init struct H2D'd into the scratch on-stream BEFORE the kernel: count/sum start at 0 (atomic
    // add), min/max at the INT sentinels (atomic min/max). `initial` outlives the helper's covering
    // sync, so the async source stays valid until the copy completes.
    let initial = CudaI32StatsRaw {
        count: 0,
        sum: 0,
        min: i32::MAX,
        max: i32::MIN,
    };
    let mut output_bytes = [0_u8; std::mem::size_of::<CudaI32StatsRaw>()];
    launch_on_pooled_stream(resident, Some(&mut output_bytes), |stream, output_ptr| {
        let htod_rc = unsafe {
            htod_async(
                output_ptr,
                (&initial as *const CudaI32StatsRaw).cast::<c_void>(),
                std::mem::size_of::<CudaI32StatsRaw>(),
                stream,
            )
        };
        if htod_rc != 0 {
            return htod_rc;
        }
        let mut resident_arg = resident.device_ptr();
        let mut offset_arg = byte_offset;
        let mut rows_arg = row_count;
        let mut lower_arg = lower_inclusive;
        let mut upper_arg = upper_inclusive;
        let mut output_arg = output_ptr;
        let mut args = [
            (&mut resident_arg as *mut u64).cast::<c_void>(),
            (&mut offset_arg as *mut u64).cast::<c_void>(),
            (&mut rows_arg as *mut u64).cast::<c_void>(),
            (&mut lower_arg as *mut i32).cast::<c_void>(),
            (&mut upper_arg as *mut i32).cast::<c_void>(),
            (&mut output_arg as *mut u64).cast::<c_void>(),
        ];
        unsafe {
            cu_launch_kernel(
                function,
                grid_dim,
                1,
                1,
                block_dim,
                1,
                1,
                0,
                stream,
                args.as_mut_ptr(),
                std::ptr::null_mut(),
            )
        }
    })?;

    let raw = CudaI32StatsRaw {
        count: u64::from_le_bytes(output_bytes[0..8].try_into().unwrap()),
        sum: i64::from_le_bytes(output_bytes[8..16].try_into().unwrap()),
        min: i32::from_le_bytes(output_bytes[16..20].try_into().unwrap()),
        max: i32::from_le_bytes(output_bytes[20..24].try_into().unwrap()),
    };

    Ok(CudaI32Stats {
        count: raw.count,
        sum: raw.sum,
        min: (raw.count > 0).then_some(raw.min),
        max: (raw.count > 0).then_some(raw.max),
    })
}

fn launch_cuda_resident_i32_project(
    resident: &CudaResidentDeviceMemory,
    byte_offset: u64,
    row_count: u64,
) -> Result<Vec<i32>, CudaRuntimeProbeError> {
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;

    // P2-M2 — projecting a resident int4 column is a pure column read: the values returned ARE the
    // resident column bytes. The old route ran a single-thread `(1,1,1)` "identity copy" kernel
    // (resident -> a fresh device buffer) and THEN D2H'd that buffer — a redundant device->device
    // copy (2x memory traffic) behind a per-call `cuModuleLoadData` (re-JIT) + two `cuMemAlloc`. We
    // drop the kernel entirely and D2H the resident column straight into the host result on a pooled
    // private stream: `cu_memcpy_dtoh_async` keeps the copy OFF the synchronizing null stream, and
    // `launch_on_pooled_stream` event-times it (telemetry), covering-syncs, and drains the stream
    // before any error propagates. Blocking fallback for drivers lacking the async symbol. Net: 1x
    // traffic, no kernel, no JIT, no output alloc; the public signature and callers are unchanged.
    let end_offset = row_count
        .checked_mul(std::mem::size_of::<i32>() as u64)
        .and_then(|bytes| byte_offset.checked_add(bytes))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    if end_offset > resident.metadata().allocated_bytes {
        return Err(CudaRuntimeProbeError::InvalidInputLength(
            end_offset as usize,
        ));
    }
    if row_count == 0 {
        return Ok(Vec::new());
    }

    let len = usize::try_from(row_count)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let copy_bytes = len
        .checked_mul(std::mem::size_of::<i32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let src = resident
        .device_ptr()
        .checked_add(byte_offset)
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let mut values = vec![0_i32; len];
    let dst = values.as_mut_ptr().cast::<c_void>();

    if let Some(dtoh_async) = resident.primary().cu_memcpy_dtoh_async {
        // Whole-column D2H staged on a pooled private stream. `dst` is a raw pointer into `values`
        // (no live borrow); the helper covering-syncs before it returns, so the GPU copy completes
        // before `values` is read below — no use-after-free, no observation of partial data.
        launch_on_pooled_stream(resident, None, |stream, _scratch| unsafe {
            dtoh_async(dst, src, copy_bytes, stream)
        })?;
    } else {
        // Old-driver fallback (async D2H symbol absent): one blocking copy.
        let cu_memcpy_dtoh = unsafe {
            resident
                .lib()
                .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
                .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
                .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
        };
        check_cuda(unsafe { cu_memcpy_dtoh(dst, src, copy_bytes) })?;
    }
    Ok(values)
}

/// Single-thread `(1,1,1)` serial identity-copy projection — retained ONLY (under `#[cfg(test)]`)
/// as the on-GPU A/B parity + perf baseline for the P2-M2 kernel-less project migration. The
/// production route is the kernel-less `launch_cuda_resident_i32_project` (a direct pooled-stream
/// D2H of the resident column); this is the previously-shipped device->device copy kernel kept as a
/// device-side reference oracle (no CPU operator re-implementation).
#[cfg(test)]
fn launch_cuda_resident_i32_project_serial(
    resident: &CudaResidentDeviceMemory,
    byte_offset: u64,
    row_count: u64,
) -> Result<Vec<i32>, CudaRuntimeProbeError> {
    type CuMemAlloc = unsafe extern "C" fn(*mut u64, usize) -> i32;
    type CuMemFree = unsafe extern "C" fn(u64) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    type CuModuleLoadData = unsafe extern "C" fn(*mut *mut c_void, *const c_void) -> i32;
    type CuModuleUnload = unsafe extern "C" fn(*mut c_void) -> i32;
    type CuModuleGetFunction =
        unsafe extern "C" fn(*mut *mut c_void, *mut c_void, *const i8) -> i32;
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    type CuCtxSynchronize = unsafe extern "C" fn() -> i32;

    const PTX: &[u8] = br#"
.version 6.0
.target sm_30
.address_size 64

.visible .entry gpu_db_resident_i32_project(
    .param .u64 resident_ptr,
    .param .u64 byte_offset,
    .param .u64 row_count,
    .param .u64 out_values_ptr,
    .param .u64 out_count_ptr
)
{
    .reg .pred %p_done;
    .reg .u64 %resident;
    .reg .u64 %offset;
    .reg .u64 %rows;
    .reg .u64 %out_values;
    .reg .u64 %out_count;
    .reg .u64 %base;
    .reg .u64 %idx;
    .reg .u64 %input_addr;
    .reg .u64 %output_addr;
    .reg .s32 %r_value;

    ld.param.u64 %resident, [resident_ptr];
    ld.param.u64 %offset, [byte_offset];
    ld.param.u64 %rows, [row_count];
    ld.param.u64 %out_values, [out_values_ptr];
    ld.param.u64 %out_count, [out_count_ptr];

    add.u64 %base, %resident, %offset;
    mov.u64 %idx, 0;

loop:
    setp.ge.u64 %p_done, %idx, %rows;
    @%p_done bra done;
    mul.lo.u64 %input_addr, %idx, 4;
    add.u64 %input_addr, %base, %input_addr;
    ld.global.s32 %r_value, [%input_addr];
    mul.lo.u64 %output_addr, %idx, 4;
    add.u64 %output_addr, %out_values, %output_addr;
    st.global.s32 [%output_addr], %r_value;
    add.u64 %idx, %idx, 1;
    bra loop;

done:
    st.global.u64 [%out_count], %rows;
    ret;
}
"#;

    let bytes = row_count
        .checked_mul(std::mem::size_of::<i32>() as u64)
        .and_then(|bytes| byte_offset.checked_add(bytes))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    if bytes > resident.metadata().allocated_bytes {
        return Err(CudaRuntimeProbeError::InvalidInputLength(bytes as usize));
    }
    if row_count == 0 {
        return Ok(Vec::new());
    }

    let cu_mem_alloc = unsafe {
        resident
            .lib()
            .get::<CuMemAlloc>(b"cuMemAlloc_v2\0")
            .or_else(|_| resident.lib().get::<CuMemAlloc>(b"cuMemAlloc\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_mem_free = unsafe {
        resident
            .lib()
            .get::<CuMemFree>(b"cuMemFree_v2\0")
            .or_else(|_| resident.lib().get::<CuMemFree>(b"cuMemFree\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_module_load_data = unsafe {
        resident
            .lib()
            .get::<CuModuleLoadData>(b"cuModuleLoadData\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_module_unload = unsafe {
        resident
            .lib()
            .get::<CuModuleUnload>(b"cuModuleUnload\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_module_get_function = unsafe {
        resident
            .lib()
            .get::<CuModuleGetFunction>(b"cuModuleGetFunction\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_ctx_synchronize = unsafe {
        resident
            .lib()
            .get::<CuCtxSynchronize>(b"cuCtxSynchronize\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };

    let value_bytes = row_count
        .checked_mul(std::mem::size_of::<i32>() as u64)
        .and_then(|bytes| usize::try_from(bytes).ok())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let mut device_values = 0_u64;
    let mut device_count = 0_u64;
    check_cuda(unsafe { cu_mem_alloc(&mut device_values, value_bytes) })?;
    let values_guard = CudaDeviceAllocationGuard {
        ptr: device_values,
        free: *cu_mem_free,
    };
    check_cuda(unsafe { cu_mem_alloc(&mut device_count, std::mem::size_of::<u64>()) })?;
    let count_guard = CudaDeviceAllocationGuard {
        ptr: device_count,
        free: *cu_mem_free,
    };

    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);

    let mut module = std::ptr::null_mut();
    check_cuda(unsafe { cu_module_load_data(&mut module, ptx.as_ptr().cast::<c_void>()) })?;
    let module_guard = CudaModuleGuard {
        module,
        unload: *cu_module_unload,
    };

    let mut function = std::ptr::null_mut();
    check_cuda(unsafe {
        cu_module_get_function(
            &mut function,
            module,
            c"gpu_db_resident_i32_project".as_ptr(),
        )
    })?;

    let mut resident_arg = resident.device_ptr();
    let mut offset_arg = byte_offset;
    let mut rows_arg = row_count;
    let mut values_arg = values_guard.ptr;
    let mut count_arg = count_guard.ptr;
    let mut args = [
        (&mut resident_arg as *mut u64).cast::<c_void>(),
        (&mut offset_arg as *mut u64).cast::<c_void>(),
        (&mut rows_arg as *mut u64).cast::<c_void>(),
        (&mut values_arg as *mut u64).cast::<c_void>(),
        (&mut count_arg as *mut u64).cast::<c_void>(),
    ];
    launch_with_optional_cuda_event_timing(resident, *cu_ctx_synchronize, || unsafe {
        cu_launch_kernel(
            function,
            1,
            1,
            1,
            1,
            1,
            1,
            0,
            std::ptr::null_mut(),
            args.as_mut_ptr(),
            std::ptr::null_mut(),
        )
    })?;

    let mut copied_count = 0_u64;
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            (&mut copied_count as *mut u64).cast::<c_void>(),
            count_guard.ptr,
            std::mem::size_of::<u64>(),
        )
    })?;
    let copied_len = usize::try_from(copied_count)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    if copied_count > row_count {
        return Err(CudaRuntimeProbeError::InvalidInputLength(copied_len));
    }
    let mut values = vec![0_i32; copied_len];
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            values.as_mut_ptr().cast::<c_void>(),
            values_guard.ptr,
            copied_len * std::mem::size_of::<i32>(),
        )
    })?;

    drop(module_guard);
    drop(count_guard);
    drop(values_guard);
    Ok(values)
}

// P2-M2 / S1 — parallel GPU hash aggregation (the GROUP BY operator), replacing the single-thread
// `(1,1,1)` O(rows × groups) linear-probe scan. Three kernels run ordered on one pooled stream:
//   (1) `..._hash_init`   — grid-stride fill the open-addressing table: slots=EMPTY(0),
//       counts/sums=0, mins=INT_MAX, maxs=INT_MIN (the min/max sentinels so atomic min/max work).
//   (2) `..._hash_aggregate` — one thread per row (grid-stride, optional filter). Each slot is a
//       u64 `(occupied<<32)|key`; a single `atom.cas.b64(slot, EMPTY, packed)` claims-or-finds the
//       group with no key-write race, linear-probe on collision; then `atom.add` count/sum +
//       `atom.min/max` from the pre-initialized neutral values, so claimer and finder race cleanly.
//   (3) `..._hash_compact` — gather non-empty slots into the output arrays via `atom.add` append
//       (arbitrary order — correct, since the engine applies ORDER BY; see plan §9.5).
// Output order is unspecified (a GROUP BY has none without ORDER BY); the serial oracle's
// insertion order and this hash order are both valid, so the parity test sorts both by group key.
fn launch_cuda_resident_i32_grouped_stats(
    resident: &CudaResidentDeviceMemory,
    group_byte_offset: u64,
    value_byte_offset: u64,
    filter: Option<(u64, i32, CudaI32Comparison)>,
    row_count: u64,
    post: Option<GroupedI64Post<'_>>,
) -> Result<(Vec<CudaI32GroupedStats>, usize), CudaRuntimeProbeError> {
    // Returns (rows, group_count): `rows` is windowed/ordered when `order` is set, else all groups;
    // `group_count` is the FULL distinct-group count M (the D2H'd-bytes basis for the caller's
    // telemetry, independent of any LIMIT window).
    type CuMemsetD8Async = unsafe extern "C" fn(u64, u8, usize, *mut c_void) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;

    const PTX: &[u8] = br#"
.version 6.0
.target sm_60
.address_size 64

.visible .entry gpu_db_resident_i32_grouped_hash_init(
    .param .u64 slots_ptr,
    .param .u64 counts_ptr,
    .param .u64 sums_ptr,
    .param .u64 mins_ptr,
    .param .u64 maxs_ptr,
    .param .u64 table_size
)
{
    .reg .pred %p_done;
    .reg .u32 %lane;
    .reg .u32 %bdim;
    .reg .u32 %bid;
    .reg .u32 %gdim;
    .reg .u32 %tmp32;
    .reg .u64 %slots;
    .reg .u64 %counts;
    .reg .u64 %sums;
    .reg .u64 %mins;
    .reg .u64 %maxs;
    .reg .u64 %size;
    .reg .u64 %idx;
    .reg .u64 %stride;
    .reg .u64 %addr;
    .reg .u64 %off8;
    .reg .u64 %off4;

    ld.param.u64 %slots, [slots_ptr];
    ld.param.u64 %counts, [counts_ptr];
    ld.param.u64 %sums, [sums_ptr];
    ld.param.u64 %mins, [mins_ptr];
    ld.param.u64 %maxs, [maxs_ptr];
    ld.param.u64 %size, [table_size];

    mov.u32 %lane, %tid.x;
    mov.u32 %bdim, %ntid.x;
    mov.u32 %bid, %ctaid.x;
    mov.u32 %gdim, %nctaid.x;
    mad.lo.u32 %tmp32, %bid, %bdim, %lane;
    cvt.u64.u32 %idx, %tmp32;
    mul.lo.u32 %tmp32, %gdim, %bdim;
    cvt.u64.u32 %stride, %tmp32;

init_loop:
    setp.ge.u64 %p_done, %idx, %size;
    @%p_done bra init_done;
    mul.lo.u64 %off8, %idx, 8;
    mul.lo.u64 %off4, %idx, 4;
    add.u64 %addr, %slots, %off8;
    st.global.u64 [%addr], 0;
    add.u64 %addr, %counts, %off8;
    st.global.u64 [%addr], 0;
    add.u64 %addr, %sums, %off8;
    st.global.u64 [%addr], 0;
    add.u64 %addr, %mins, %off4;
    mov.u32 %tmp32, 2147483647;
    st.global.u32 [%addr], %tmp32;
    add.u64 %addr, %maxs, %off4;
    mov.u32 %tmp32, 2147483648;
    st.global.u32 [%addr], %tmp32;
    add.u64 %idx, %idx, %stride;
    bra init_loop;
init_done:
    ret;
}

.visible .entry gpu_db_resident_i32_grouped_hash_aggregate(
    .param .u64 resident_ptr,
    .param .u64 group_byte_offset,
    .param .u64 value_byte_offset,
    .param .u64 filter_byte_offset,
    .param .u64 row_count,
    .param .s32 needle,
    .param .u32 comparison,
    .param .u64 slots_ptr,
    .param .u64 counts_ptr,
    .param .u64 sums_ptr,
    .param .u64 mins_ptr,
    .param .u64 maxs_ptr,
    .param .u32 table_mask
)
{
    .reg .pred %p_done;
    .reg .pred %p_check;
    .reg .pred %p_match;
    .reg .pred %p_claimed;
    .reg .pred %p_exists;
    .reg .u32 %lane;
    .reg .u32 %bdim;
    .reg .u32 %bid;
    .reg .u32 %gdim;
    .reg .u32 %tmp32;
    .reg .u32 %comparison;
    .reg .u32 %mask;
    .reg .u32 %slot;
    .reg .u32 %hash;
    .reg .u32 %group_u;
    .reg .u64 %resident;
    .reg .u64 %group_base;
    .reg .u64 %value_base;
    .reg .u64 %filter_base;
    .reg .u64 %rows;
    .reg .u64 %slots;
    .reg .u64 %counts;
    .reg .u64 %sums;
    .reg .u64 %mins;
    .reg .u64 %maxs;
    .reg .u64 %idx;
    .reg .u64 %stride;
    .reg .u64 %addr;
    .reg .u64 %roff;
    .reg .u64 %slot64;
    .reg .u64 %off8;
    .reg .u64 %off4;
    .reg .u64 %packed;
    .reg .u64 %cur;
    .reg .u64 %zero;
    .reg .u64 %one;
    .reg .u64 %hibit;
    .reg .u64 %valbits;
    .reg .u64 %ignore64;
    .reg .s64 %val64;
    .reg .s32 %needle;
    .reg .s32 %value;
    .reg .s32 %filter_value;
    .reg .s32 %ignore32;

    ld.param.u64 %resident, [resident_ptr];
    ld.param.u64 %group_base, [group_byte_offset];
    ld.param.u64 %value_base, [value_byte_offset];
    ld.param.u64 %filter_base, [filter_byte_offset];
    ld.param.u64 %rows, [row_count];
    ld.param.s32 %needle, [needle];
    ld.param.u32 %comparison, [comparison];
    ld.param.u64 %slots, [slots_ptr];
    ld.param.u64 %counts, [counts_ptr];
    ld.param.u64 %sums, [sums_ptr];
    ld.param.u64 %mins, [mins_ptr];
    ld.param.u64 %maxs, [maxs_ptr];
    ld.param.u32 %mask, [table_mask];

    add.u64 %group_base, %resident, %group_base;
    add.u64 %value_base, %resident, %value_base;
    add.u64 %filter_base, %resident, %filter_base;
    mov.u64 %zero, 0;
    mov.u64 %one, 1;
    mov.u64 %hibit, 4294967296;

    mov.u32 %lane, %tid.x;
    mov.u32 %bdim, %ntid.x;
    mov.u32 %bid, %ctaid.x;
    mov.u32 %gdim, %nctaid.x;
    mad.lo.u32 %tmp32, %bid, %bdim, %lane;
    cvt.u64.u32 %idx, %tmp32;
    mul.lo.u32 %tmp32, %gdim, %bdim;
    cvt.u64.u32 %stride, %tmp32;

row_loop:
    setp.ge.u64 %p_done, %idx, %rows;
    @%p_done bra agg_done;
    mul.lo.u64 %roff, %idx, 4;

    setp.eq.u32 %p_check, %comparison, 0;
    @%p_check bra do_agg;
    add.u64 %addr, %filter_base, %roff;
    ld.global.s32 %filter_value, [%addr];
    mov.pred %p_match, 0;
    setp.eq.u32 %p_check, %comparison, 1;
    @%p_check bra f_lt;
    setp.eq.u32 %p_check, %comparison, 2;
    @%p_check bra f_lte;
    setp.eq.u32 %p_check, %comparison, 3;
    @%p_check bra f_gt;
    setp.eq.u32 %p_check, %comparison, 4;
    @%p_check bra f_gte;
    bra next_row;
f_lt:
    setp.lt.s32 %p_match, %filter_value, %needle;
    bra f_done;
f_lte:
    setp.le.s32 %p_match, %filter_value, %needle;
    bra f_done;
f_gt:
    setp.gt.s32 %p_match, %filter_value, %needle;
    bra f_done;
f_gte:
    setp.ge.s32 %p_match, %filter_value, %needle;
f_done:
    @!%p_match bra next_row;

do_agg:
    add.u64 %addr, %group_base, %roff;
    ld.global.u32 %group_u, [%addr];
    add.u64 %addr, %value_base, %roff;
    ld.global.s32 %value, [%addr];

    cvt.u64.u32 %packed, %group_u;
    or.b64 %packed, %packed, %hibit;

    mul.lo.u32 %hash, %group_u, 2654435761;
    shr.u32 %tmp32, %hash, 15;
    xor.b32 %hash, %hash, %tmp32;
    and.b32 %slot, %hash, %mask;

probe:
    cvt.u64.u32 %slot64, %slot;
    mul.lo.u64 %off8, %slot64, 8;
    add.u64 %addr, %slots, %off8;
    atom.global.cas.b64 %cur, [%addr], %zero, %packed;
    setp.eq.u64 %p_claimed, %cur, %zero;
    @%p_claimed bra at_slot;
    setp.eq.u64 %p_exists, %cur, %packed;
    @%p_exists bra at_slot;
    add.u32 %slot, %slot, 1;
    and.b32 %slot, %slot, %mask;
    bra probe;

at_slot:
    mul.lo.u64 %off4, %slot64, 4;
    add.u64 %addr, %counts, %off8;
    atom.global.add.u64 %ignore64, [%addr], %one;
    cvt.s64.s32 %val64, %value;
    cvt.u64.s64 %valbits, %val64;
    add.u64 %addr, %sums, %off8;
    atom.global.add.u64 %ignore64, [%addr], %valbits;
    add.u64 %addr, %mins, %off4;
    atom.global.min.s32 %ignore32, [%addr], %value;
    add.u64 %addr, %maxs, %off4;
    atom.global.max.s32 %ignore32, [%addr], %value;

next_row:
    add.u64 %idx, %idx, %stride;
    bra row_loop;

agg_done:
    ret;
}

.visible .entry gpu_db_resident_i32_grouped_hash_compact(
    .param .u64 slots_ptr,
    .param .u64 counts_ptr,
    .param .u64 sums_ptr,
    .param .u64 mins_ptr,
    .param .u64 maxs_ptr,
    .param .u64 table_size,
    .param .u64 out_groups_ptr,
    .param .u64 out_counts_ptr,
    .param .u64 out_sums_ptr,
    .param .u64 out_mins_ptr,
    .param .u64 out_maxs_ptr,
    .param .u64 out_count_ptr
)
{
    .reg .pred %p_done;
    .reg .pred %p_empty;
    .reg .u32 %lane;
    .reg .u32 %bdim;
    .reg .u32 %bid;
    .reg .u32 %gdim;
    .reg .u32 %tmp32;
    .reg .u32 %key;
    .reg .u32 %minval;
    .reg .u32 %maxval;
    .reg .u64 %slots;
    .reg .u64 %counts;
    .reg .u64 %sums;
    .reg .u64 %mins;
    .reg .u64 %maxs;
    .reg .u64 %size;
    .reg .u64 %og;
    .reg .u64 %oc;
    .reg .u64 %os;
    .reg .u64 %omin;
    .reg .u64 %omax;
    .reg .u64 %ocount;
    .reg .u64 %idx;
    .reg .u64 %stride;
    .reg .u64 %addr;
    .reg .u64 %off8;
    .reg .u64 %off4;
    .reg .u64 %slot;
    .reg .u64 %pos;
    .reg .u64 %pos8;
    .reg .u64 %pos4;
    .reg .u64 %one;
    .reg .u64 %cval;
    .reg .u64 %sval;

    ld.param.u64 %slots, [slots_ptr];
    ld.param.u64 %counts, [counts_ptr];
    ld.param.u64 %sums, [sums_ptr];
    ld.param.u64 %mins, [mins_ptr];
    ld.param.u64 %maxs, [maxs_ptr];
    ld.param.u64 %size, [table_size];
    ld.param.u64 %og, [out_groups_ptr];
    ld.param.u64 %oc, [out_counts_ptr];
    ld.param.u64 %os, [out_sums_ptr];
    ld.param.u64 %omin, [out_mins_ptr];
    ld.param.u64 %omax, [out_maxs_ptr];
    ld.param.u64 %ocount, [out_count_ptr];
    mov.u64 %one, 1;

    mov.u32 %lane, %tid.x;
    mov.u32 %bdim, %ntid.x;
    mov.u32 %bid, %ctaid.x;
    mov.u32 %gdim, %nctaid.x;
    mad.lo.u32 %tmp32, %bid, %bdim, %lane;
    cvt.u64.u32 %idx, %tmp32;
    mul.lo.u32 %tmp32, %gdim, %bdim;
    cvt.u64.u32 %stride, %tmp32;

compact_loop:
    setp.ge.u64 %p_done, %idx, %size;
    @%p_done bra compact_done;
    mul.lo.u64 %off8, %idx, 8;
    add.u64 %addr, %slots, %off8;
    ld.global.u64 %slot, [%addr];
    setp.eq.u64 %p_empty, %slot, 0;
    @%p_empty bra compact_next;

    atom.global.add.u64 %pos, [%ocount], %one;
    mul.lo.u64 %pos8, %pos, 8;
    mul.lo.u64 %pos4, %pos, 4;
    cvt.u32.u64 %key, %slot;
    add.u64 %addr, %og, %pos4;
    st.global.u32 [%addr], %key;
    add.u64 %addr, %counts, %off8;
    ld.global.u64 %cval, [%addr];
    add.u64 %addr, %oc, %pos8;
    st.global.u64 [%addr], %cval;
    add.u64 %addr, %sums, %off8;
    ld.global.u64 %sval, [%addr];
    add.u64 %addr, %os, %pos8;
    st.global.u64 [%addr], %sval;
    mul.lo.u64 %off4, %idx, 4;
    add.u64 %addr, %mins, %off4;
    ld.global.u32 %minval, [%addr];
    add.u64 %addr, %omin, %pos4;
    st.global.u32 [%addr], %minval;
    add.u64 %addr, %maxs, %off4;
    ld.global.u32 %maxval, [%addr];
    add.u64 %addr, %omax, %pos4;
    st.global.u32 [%addr], %maxval;

compact_next:
    add.u64 %idx, %idx, %stride;
    bra compact_loop;
compact_done:
    ret;
}
"#;

    // Bounds: group + value columns (and filter column if present) must lie in the resident alloc.
    let group_bytes = row_count
        .checked_mul(std::mem::size_of::<i32>() as u64)
        .and_then(|bytes| group_byte_offset.checked_add(bytes))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let value_bytes = row_count
        .checked_mul(std::mem::size_of::<i32>() as u64)
        .and_then(|bytes| value_byte_offset.checked_add(bytes))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    if group_bytes > resident.metadata().allocated_bytes
        || value_bytes > resident.metadata().allocated_bytes
    {
        return Err(CudaRuntimeProbeError::InvalidInputLength(
            group_bytes.max(value_bytes) as usize,
        ));
    }
    let (filter_byte_offset, needle, comparison_code) =
        if let Some((filter_byte_offset, needle, comparison)) = filter {
            let filter_bytes = row_count
                .checked_mul(std::mem::size_of::<i32>() as u64)
                .and_then(|bytes| filter_byte_offset.checked_add(bytes))
                .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
            if filter_bytes > resident.metadata().allocated_bytes {
                return Err(CudaRuntimeProbeError::InvalidInputLength(
                    filter_bytes as usize,
                ));
            }
            (filter_byte_offset, needle, comparison.code())
        } else {
            (group_byte_offset, 0, 0)
        };
    if row_count == 0 {
        return Ok((Vec::new(), 0));
    }

    // Open-addressing table sized to >= 2x worst-case distinct groups (= row_count) -> load factor
    // <= 0.5, so linear probing terminates and every group fits. Power-of-two for the `& mask` wrap.
    let table_size = row_count
        .checked_mul(2)
        .and_then(|w| w.checked_next_power_of_two())
        .map(|s| s.max(256))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let table_mask = u32::try_from(table_size - 1)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let table_size_usize = usize::try_from(table_size)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let row_count_usize = usize::try_from(row_count)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;

    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memset_d8_async = unsafe {
        resident
            .lib()
            .get::<CuMemsetD8Async>(b"cuMemsetD8Async\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };

    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let init_fn = resident
        .primary()
        .cached_function(c"gpu_db_resident_i32_grouped_hash_init", &ptx)?;
    let aggregate_fn = resident
        .primary()
        .cached_function(c"gpu_db_resident_i32_grouped_hash_aggregate", &ptx)?;
    let compact_fn = resident
        .primary()
        .cached_function(c"gpu_db_resident_i32_grouped_hash_compact", &ptx)?;

    // Pooled device buffers (no per-call cuMemAlloc churn): the 5 table columns + the 5 output
    // columns + the output counter. Sized to the table / worst-case row_count.
    let table_u64_bytes = table_size_usize
        .checked_mul(std::mem::size_of::<u64>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let table_i32_bytes = table_size_usize
        .checked_mul(std::mem::size_of::<i32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let out_i32_bytes = row_count_usize
        .checked_mul(std::mem::size_of::<i32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let out_u64_bytes = row_count_usize
        .checked_mul(std::mem::size_of::<u64>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let primary = resident.primary();
    let slots = primary.lease_device_buffer(table_u64_bytes)?;
    let counts = primary.lease_device_buffer(table_u64_bytes)?;
    let sums = primary.lease_device_buffer(table_u64_bytes)?;
    let mins = primary.lease_device_buffer(table_i32_bytes)?;
    let maxs = primary.lease_device_buffer(table_i32_bytes)?;
    let out_groups = primary.lease_device_buffer(out_i32_bytes)?;
    let out_counts = primary.lease_device_buffer(out_u64_bytes)?;
    let out_sums = primary.lease_device_buffer(out_u64_bytes)?;
    let out_mins = primary.lease_device_buffer(out_i32_bytes)?;
    let out_maxs = primary.lease_device_buffer(out_i32_bytes)?;
    let out_count = primary.lease_device_buffer(std::mem::size_of::<u64>())?;

    primary.set_current()?;
    struct StreamLease<'a> {
        primary: &'a GpuPrimaryContext,
        pooled: Option<PooledStream>,
    }
    impl Drop for StreamLease<'_> {
        fn drop(&mut self) {
            if let Some(pooled) = self.pooled.take() {
                self.primary.release_pooled_stream(pooled);
            }
        }
    }
    let lease = StreamLease {
        primary,
        pooled: Some(primary.acquire_pooled_stream()?),
    };
    let pooled = lease.pooled.as_ref().expect("pooled stream just set");
    let stream = pooled.stream;
    let timed = !pooled.start_event.is_null() && !pooled.stop_event.is_null();
    let drain_err = |err: CudaRuntimeProbeError| -> CudaRuntimeProbeError {
        // SAFETY: best-effort drain on an already-failing path before the leases unwind, so no buffer
        // returns to the pool while a kernel is still reading/writing it (cross-thread UAF guard).
        unsafe {
            let _ = (primary.cu_stream_synchronize)(stream);
        }
        err
    };

    const BLOCK: u32 = 256;
    let init_grid = table_size.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;
    let agg_grid = row_count.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;

    let launch = |function: *mut c_void, grid: u32, args: &mut [*mut c_void]| -> i32 {
        unsafe {
            cu_launch_kernel(
                function,
                grid,
                1,
                1,
                BLOCK,
                1,
                1,
                0,
                stream,
                args.as_mut_ptr(),
                std::ptr::null_mut(),
            )
        }
    };

    if timed {
        check_cuda(unsafe { (primary.cu_event_record)(pooled.start_event, stream) })
            .map_err(drain_err)?;
    }
    // out_count starts at 0 (the compact kernel atom-appends into it), ordered on the stream.
    check_cuda(unsafe { cu_memset_d8_async(out_count.ptr, 0, std::mem::size_of::<u64>(), stream) })
        .map_err(drain_err)?;

    let mut slots_arg = slots.ptr;
    let mut counts_arg = counts.ptr;
    let mut sums_arg = sums.ptr;
    let mut mins_arg = mins.ptr;
    let mut maxs_arg = maxs.ptr;
    let mut table_size_arg = table_size;
    let mut init_args = [
        (&mut slots_arg as *mut u64).cast::<c_void>(),
        (&mut counts_arg as *mut u64).cast::<c_void>(),
        (&mut sums_arg as *mut u64).cast::<c_void>(),
        (&mut mins_arg as *mut u64).cast::<c_void>(),
        (&mut maxs_arg as *mut u64).cast::<c_void>(),
        (&mut table_size_arg as *mut u64).cast::<c_void>(),
    ];
    check_cuda(launch(init_fn, init_grid, &mut init_args)).map_err(drain_err)?;

    let mut resident_arg = resident.device_ptr();
    let mut group_offset_arg = group_byte_offset;
    let mut value_offset_arg = value_byte_offset;
    let mut filter_offset_arg = filter_byte_offset;
    let mut rows_arg = row_count;
    let mut needle_arg = needle;
    let mut comparison_arg = comparison_code;
    let mut mask_arg = table_mask;
    let mut agg_args = [
        (&mut resident_arg as *mut u64).cast::<c_void>(),
        (&mut group_offset_arg as *mut u64).cast::<c_void>(),
        (&mut value_offset_arg as *mut u64).cast::<c_void>(),
        (&mut filter_offset_arg as *mut u64).cast::<c_void>(),
        (&mut rows_arg as *mut u64).cast::<c_void>(),
        (&mut needle_arg as *mut i32).cast::<c_void>(),
        (&mut comparison_arg as *mut u32).cast::<c_void>(),
        (&mut slots_arg as *mut u64).cast::<c_void>(),
        (&mut counts_arg as *mut u64).cast::<c_void>(),
        (&mut sums_arg as *mut u64).cast::<c_void>(),
        (&mut mins_arg as *mut u64).cast::<c_void>(),
        (&mut maxs_arg as *mut u64).cast::<c_void>(),
        (&mut mask_arg as *mut u32).cast::<c_void>(),
    ];
    check_cuda(launch(aggregate_fn, agg_grid, &mut agg_args)).map_err(drain_err)?;

    let mut out_groups_arg = out_groups.ptr;
    let mut out_counts_arg = out_counts.ptr;
    let mut out_sums_arg = out_sums.ptr;
    let mut out_mins_arg = out_mins.ptr;
    let mut out_maxs_arg = out_maxs.ptr;
    let mut out_count_arg = out_count.ptr;
    let mut compact_args = [
        (&mut slots_arg as *mut u64).cast::<c_void>(),
        (&mut counts_arg as *mut u64).cast::<c_void>(),
        (&mut sums_arg as *mut u64).cast::<c_void>(),
        (&mut mins_arg as *mut u64).cast::<c_void>(),
        (&mut maxs_arg as *mut u64).cast::<c_void>(),
        (&mut table_size_arg as *mut u64).cast::<c_void>(),
        (&mut out_groups_arg as *mut u64).cast::<c_void>(),
        (&mut out_counts_arg as *mut u64).cast::<c_void>(),
        (&mut out_sums_arg as *mut u64).cast::<c_void>(),
        (&mut out_mins_arg as *mut u64).cast::<c_void>(),
        (&mut out_maxs_arg as *mut u64).cast::<c_void>(),
        (&mut out_count_arg as *mut u64).cast::<c_void>(),
    ];
    check_cuda(launch(compact_fn, init_grid, &mut compact_args)).map_err(drain_err)?;

    if timed {
        check_cuda(unsafe { (primary.cu_event_record)(pooled.stop_event, stream) })
            .map_err(drain_err)?;
    }
    check_cuda(unsafe { (primary.cu_stream_synchronize)(stream) }).map_err(drain_err)?;
    if timed {
        let mut elapsed_ms = 0.0_f32;
        check_cuda(unsafe {
            (primary.cu_event_elapsed_time)(&mut elapsed_ms, pooled.start_event, pooled.stop_event)
        })?;
        resident
            .record_kernel_event_elapsed_us(Some((f64::from(elapsed_ms) * 1_000.0).ceil() as u64));
    } else {
        resident.record_kernel_event_elapsed_us(None);
    }

    let mut output_count = 0_u64;
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            (&mut output_count as *mut u64).cast::<c_void>(),
            out_count.ptr,
            std::mem::size_of::<u64>(),
        )
    })?;
    if output_count > row_count {
        return Err(CudaRuntimeProbeError::InvalidInputLength(
            usize::try_from(output_count).unwrap_or(usize::MAX),
        ));
    }
    let output_len = usize::try_from(output_count)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;

    // S5a.2: GPU ORDER BY (count/sum) + LIMIT/OFFSET on the RESIDENT compacted output, before D2H —
    // no re-upload. `out_counts` (u64, counts are non-negative ≤ row_count) and `out_sums` (i64) are
    // argsorted directly as i64; the result is the windowed list of compact-order group indices.
    let ordered_indices: Option<Vec<u32>> = match post {
        Some(post) if output_len > 0 => {
            let order = post.order;
            let key_bytes = output_len
                .checked_mul(std::mem::size_of::<i64>())
                .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
            // FULL sorted permutation (no window yet — HAVING filters it first, then we window).
            // Keys narrower than i64 (count u64≤u32, min/max/group i32) are packed with the group
            // into one composite i64 key (direction baked in) so an ASCENDING argsort reproduces the
            // host "agg <dir>, group ASC tie-break" order; SUM (i64) argsorts directly.
            let pack_then_sort = |ptx: &[u8],
                                  name: &'static core::ffi::CStr,
                                  agg_ptr: u64|
             -> Result<Vec<u32>, CudaRuntimeProbeError> {
                let composite = primary.lease_device_buffer(key_bytes)?;
                launch_cuda_resident_pack_grouped_sort_key(
                    resident,
                    ptx,
                    name,
                    agg_ptr,
                    out_groups.ptr,
                    output_count,
                    order.descending,
                    composite.ptr,
                )?;
                launch_cuda_resident_i64_order_by_limit(
                    resident,
                    composite.ptr,
                    output_count,
                    false,
                    0,
                    None,
                )
            };
            let full_perm = match order.column {
                // SUM is a full i64, so (unlike count/min/max/group) the i32 group can't be packed
                // into the same composite sort key. Sort it on-device with a two-key (sum <dir>,
                // group ASC) pass: argsort the groups ASCENDING, gather the sums into that order,
                // then stable-argsort by sum — equal sums keep the group-ascending order. This
                // matches the group-ASC tie-break of count/min/max/group without leaving the device.
                GroupedI64SortColumn::Sum => {
                    let group_i64 = primary.lease_device_buffer(key_bytes)?;
                    launch_cuda_resident_widen_i32_to_i64(
                        resident,
                        out_groups.ptr,
                        output_count,
                        group_i64.ptr,
                    )?;
                    let perm_g = launch_cuda_resident_i64_order_by_limit(
                        resident,
                        group_i64.ptr,
                        output_count,
                        false,
                        0,
                        None,
                    )?;
                    let sums_g = primary.lease_device_buffer(key_bytes)?;
                    launch_cuda_resident_gather_i64_by_u32_perm(
                        resident,
                        out_sums.ptr,
                        &perm_g,
                        sums_g.ptr,
                    )?;
                    let perm_s = launch_cuda_resident_i64_order_by_limit(
                        resident,
                        sums_g.ptr,
                        output_count,
                        order.descending,
                        0,
                        None,
                    )?;
                    perm_s.iter().map(|&s| perm_g[s as usize]).collect()
                }
                GroupedI64SortColumn::Count => pack_then_sort(
                    include_bytes!("pack.ptx"),
                    c"gpu_db_pack_count_group",
                    out_counts.ptr,
                )?,
                GroupedI64SortColumn::Min => pack_then_sort(
                    include_bytes!("pack_i32.ptx"),
                    c"gpu_db_pack_i32agg_group",
                    out_mins.ptr,
                )?,
                GroupedI64SortColumn::Max => pack_then_sort(
                    include_bytes!("pack_i32.ptx"),
                    c"gpu_db_pack_i32agg_group",
                    out_maxs.ptr,
                )?,
                GroupedI64SortColumn::Group => pack_then_sort(
                    include_bytes!("pack_i32.ptx"),
                    c"gpu_db_pack_i32agg_group",
                    out_groups.ptr,
                )?,
            };

            // HAVING (S4p2 GPU DNF filter) over the resident group + aggregate columns widened to
            // i64 -> surviving compact-order indices; filter the ORDER BY perm to them.
            let ordered: Vec<u32> = if let Some((agg_col, clauses)) = post.having {
                let group_i64 = primary.lease_device_buffer(key_bytes)?;
                launch_cuda_resident_widen_i32_to_i64(
                    resident,
                    out_groups.ptr,
                    output_count,
                    group_i64.ptr,
                )?;
                let mut agg_widen = None;
                let agg_ptr = match agg_col {
                    GroupedI64SortColumn::Count => out_counts.ptr,
                    GroupedI64SortColumn::Sum => out_sums.ptr,
                    GroupedI64SortColumn::Min => {
                        let buf = primary.lease_device_buffer(key_bytes)?;
                        launch_cuda_resident_widen_i32_to_i64(
                            resident,
                            out_mins.ptr,
                            output_count,
                            buf.ptr,
                        )?;
                        let ptr = buf.ptr;
                        agg_widen = Some(buf);
                        ptr
                    }
                    GroupedI64SortColumn::Max => {
                        let buf = primary.lease_device_buffer(key_bytes)?;
                        launch_cuda_resident_widen_i32_to_i64(
                            resident,
                            out_maxs.ptr,
                            output_count,
                            buf.ptr,
                        )?;
                        let ptr = buf.ptr;
                        agg_widen = Some(buf);
                        ptr
                    }
                    // HAVING column-1 is always an aggregate, never the group key.
                    GroupedI64SortColumn::Group => {
                        return Err(CudaRuntimeProbeError::InvalidInputLength(usize::MAX));
                    }
                };
                let survivors = launch_cuda_resident_having_filter(
                    resident,
                    group_i64.ptr,
                    agg_ptr,
                    output_count,
                    clauses,
                )?;
                drop(agg_widen);
                let survivor_set: std::collections::HashSet<u32> = survivors.into_iter().collect();
                full_perm
                    .into_iter()
                    .filter(|index| survivor_set.contains(index))
                    .collect()
            } else {
                full_perm
            };

            // OFFSET / LIMIT window on the host (applied after HAVING).
            let start = usize::try_from(order.offset)
                .unwrap_or(usize::MAX)
                .min(ordered.len());
            let end = match order.limit {
                Some(limit) => start
                    .saturating_add(usize::try_from(limit).unwrap_or(usize::MAX))
                    .min(ordered.len()),
                None => ordered.len(),
            };
            Some(ordered[start..end].to_vec())
        }
        Some(_) => Some(Vec::new()),
        None => None,
    };

    let mut groups = vec![0_i32; output_len];
    let mut counts_host = vec![0_u64; output_len];
    let mut sums_host = vec![0_i64; output_len];
    let mut mins_host = vec![0_i32; output_len];
    let mut maxs_host = vec![0_i32; output_len];
    if output_len > 0 {
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                groups.as_mut_ptr().cast::<c_void>(),
                out_groups.ptr,
                output_len * std::mem::size_of::<i32>(),
            )
        })?;
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                counts_host.as_mut_ptr().cast::<c_void>(),
                out_counts.ptr,
                output_len * std::mem::size_of::<u64>(),
            )
        })?;
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                sums_host.as_mut_ptr().cast::<c_void>(),
                out_sums.ptr,
                output_len * std::mem::size_of::<i64>(),
            )
        })?;
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                mins_host.as_mut_ptr().cast::<c_void>(),
                out_mins.ptr,
                output_len * std::mem::size_of::<i32>(),
            )
        })?;
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                maxs_host.as_mut_ptr().cast::<c_void>(),
                out_maxs.ptr,
                output_len * std::mem::size_of::<i32>(),
            )
        })?;
    }
    drop(lease);

    if let Some(indices) = ordered_indices {
        // Materialize only the ordered/windowed groups, in sorted order. `output_len` (the full
        // group count) is returned alongside for the caller's D2H-bytes telemetry.
        return Ok((
            indices
                .into_iter()
                .map(|i| {
                    let i = i as usize;
                    CudaI32GroupedStats {
                        group: groups[i],
                        count: counts_host[i],
                        sum: sums_host[i],
                        min: mins_host[i],
                        max: maxs_host[i],
                    }
                })
                .collect(),
            output_len,
        ));
    }

    Ok((
        groups
            .into_iter()
            .zip(counts_host)
            .zip(sums_host)
            .zip(mins_host)
            .zip(maxs_host)
            .map(|((((group, count), sum), min), max)| CudaI32GroupedStats {
                group,
                count,
                sum,
                min,
                max,
            })
            .collect(),
        output_len,
    ))
}

/// Single-thread `(1,1,1)` serial linear-probe grouped aggregation — retained ONLY (under
/// `#[cfg(test)]`) as the on-GPU parity + benchmark oracle for the P2-M2/S1 parallel hash
/// aggregation. The production route is the parallel `launch_cuda_resident_i32_grouped_stats`
/// (atomic open-addressing hash table). This is the previously-shipped serial kernel kept as a
/// device-side reference (no CPU operator re-implementation). O(rows × groups), single thread.
#[cfg(test)]
fn launch_cuda_resident_i32_grouped_stats_serial(
    resident: &CudaResidentDeviceMemory,
    group_byte_offset: u64,
    value_byte_offset: u64,
    filter: Option<(u64, i32, CudaI32Comparison)>,
    row_count: u64,
) -> Result<Vec<CudaI32GroupedStats>, CudaRuntimeProbeError> {
    type CuMemAlloc = unsafe extern "C" fn(*mut u64, usize) -> i32;
    type CuMemFree = unsafe extern "C" fn(u64) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    type CuModuleLoadData = unsafe extern "C" fn(*mut *mut c_void, *const c_void) -> i32;
    type CuModuleUnload = unsafe extern "C" fn(*mut c_void) -> i32;
    type CuModuleGetFunction =
        unsafe extern "C" fn(*mut *mut c_void, *mut c_void, *const i8) -> i32;
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    type CuCtxSynchronize = unsafe extern "C" fn() -> i32;

    const PTX: &[u8] = br#"
.version 6.0
.target sm_30
.address_size 64

.visible .entry gpu_db_resident_i32_grouped_stats(
    .param .u64 resident_ptr,
    .param .u64 group_byte_offset,
    .param .u64 value_byte_offset,
    .param .u64 filter_byte_offset,
    .param .u64 row_count,
    .param .s32 needle,
    .param .u32 comparison,
    .param .u64 out_groups_ptr,
    .param .u64 out_counts_ptr,
    .param .u64 out_sums_ptr,
    .param .u64 out_mins_ptr,
    .param .u64 out_maxs_ptr,
    .param .u64 out_count_ptr
)
{
    .reg .pred %p_done;
    .reg .pred %p_found;
    .reg .pred %p_scan_done;
    .reg .pred %p_same;
    .reg .u64 %resident;
    .reg .u64 %group_offset;
    .reg .u64 %r_value_offset;
    .reg .u64 %filter_offset;
    .reg .u64 %rows;
    .reg .u64 %out_groups;
    .reg .u64 %out_counts;
    .reg .u64 %out_sums;
    .reg .u64 %out_mins;
    .reg .u64 %out_maxs;
    .reg .u64 %out_count;
    .reg .u64 %group_base;
    .reg .u64 %r_value_base;
    .reg .u64 %filter_base;
    .reg .u64 %idx;
    .reg .u64 %scan;
    .reg .u64 %group_count;
    .reg .u64 %input_addr;
    .reg .u64 %output_addr;
    .reg .s32 %group_value;
    .reg .s32 %r_value;
    .reg .s32 %filter_value;
    .reg .s32 %needle;
    .reg .u32 %comparison;
    .reg .s32 %existing_group;
    .reg .s64 %r_value_wide;
    .reg .u64 %existing_count;
    .reg .u64 %new_count;
    .reg .s64 %existing_sum;
    .reg .s64 %new_sum;
    .reg .s32 %existing_min;
    .reg .s32 %existing_max;
    .reg .pred %p_less;
    .reg .pred %p_greater;
    .reg .pred %p_check;
    .reg .pred %p_match;

    ld.param.u64 %resident, [resident_ptr];
    ld.param.u64 %group_offset, [group_byte_offset];
    ld.param.u64 %r_value_offset, [value_byte_offset];
    ld.param.u64 %filter_offset, [filter_byte_offset];
    ld.param.u64 %rows, [row_count];
    ld.param.s32 %needle, [needle];
    ld.param.u32 %comparison, [comparison];
    ld.param.u64 %out_groups, [out_groups_ptr];
    ld.param.u64 %out_counts, [out_counts_ptr];
    ld.param.u64 %out_sums, [out_sums_ptr];
    ld.param.u64 %out_mins, [out_mins_ptr];
    ld.param.u64 %out_maxs, [out_maxs_ptr];
    ld.param.u64 %out_count, [out_count_ptr];

    add.u64 %group_base, %resident, %group_offset;
    add.u64 %r_value_base, %resident, %r_value_offset;
    add.u64 %filter_base, %resident, %filter_offset;
    mov.u64 %idx, 0;
    mov.u64 %group_count, 0;

row_loop:
    setp.ge.u64 %p_done, %idx, %rows;
    @%p_done bra done;

    setp.eq.u32 %p_check, %comparison, 0;
    @%p_check bra predicate_pass;
    mul.lo.u64 %input_addr, %idx, 4;
    add.u64 %input_addr, %filter_base, %input_addr;
    ld.global.s32 %filter_value, [%input_addr];
    mov.pred %p_match, 0;
    setp.eq.u32 %p_check, %comparison, 1;
    @%p_check bra cmp_lt;
    setp.eq.u32 %p_check, %comparison, 2;
    @%p_check bra cmp_lte;
    setp.eq.u32 %p_check, %comparison, 3;
    @%p_check bra cmp_gt;
    setp.eq.u32 %p_check, %comparison, 4;
    @%p_check bra cmp_gte;
    bra next_row;
cmp_lt:
    setp.lt.s32 %p_match, %filter_value, %needle;
    bra predicate_checked;
cmp_lte:
    setp.le.s32 %p_match, %filter_value, %needle;
    bra predicate_checked;
cmp_gt:
    setp.gt.s32 %p_match, %filter_value, %needle;
    bra predicate_checked;
cmp_gte:
    setp.ge.s32 %p_match, %filter_value, %needle;
predicate_checked:
    @!%p_match bra next_row;

predicate_pass:
    mul.lo.u64 %input_addr, %idx, 4;
    add.u64 %input_addr, %group_base, %input_addr;
    ld.global.s32 %group_value, [%input_addr];
    mul.lo.u64 %input_addr, %idx, 4;
    add.u64 %input_addr, %r_value_base, %input_addr;
    ld.global.s32 %r_value, [%input_addr];
    cvt.s64.s32 %r_value_wide, %r_value;

    mov.u64 %scan, 0;
    mov.pred %p_found, 0;

scan_loop:
    setp.ge.u64 %p_scan_done, %scan, %group_count;
    @%p_scan_done bra insert_or_next;
    mul.lo.u64 %output_addr, %scan, 4;
    add.u64 %output_addr, %out_groups, %output_addr;
    ld.global.s32 %existing_group, [%output_addr];
    setp.eq.s32 %p_same, %existing_group, %group_value;
    @!%p_same bra scan_next;

    mul.lo.u64 %output_addr, %scan, 8;
    add.u64 %output_addr, %out_counts, %output_addr;
    ld.global.u64 %existing_count, [%output_addr];
    add.u64 %new_count, %existing_count, 1;
    st.global.u64 [%output_addr], %new_count;

    mul.lo.u64 %output_addr, %scan, 8;
    add.u64 %output_addr, %out_sums, %output_addr;
    ld.global.s64 %existing_sum, [%output_addr];
    add.s64 %new_sum, %existing_sum, %r_value_wide;
    st.global.s64 [%output_addr], %new_sum;

    mul.lo.u64 %output_addr, %scan, 4;
    add.u64 %output_addr, %out_mins, %output_addr;
    ld.global.s32 %existing_min, [%output_addr];
    setp.lt.s32 %p_less, %r_value, %existing_min;
    @!%p_less bra keep_min;
    st.global.s32 [%output_addr], %r_value;
keep_min:

    mul.lo.u64 %output_addr, %scan, 4;
    add.u64 %output_addr, %out_maxs, %output_addr;
    ld.global.s32 %existing_max, [%output_addr];
    setp.gt.s32 %p_greater, %r_value, %existing_max;
    @!%p_greater bra keep_max;
    st.global.s32 [%output_addr], %r_value;
keep_max:

    mov.pred %p_found, 1;
    bra next_row;

scan_next:
    add.u64 %scan, %scan, 1;
    bra scan_loop;

insert_or_next:
    @%p_found bra next_row;
    mul.lo.u64 %output_addr, %group_count, 4;
    add.u64 %output_addr, %out_groups, %output_addr;
    st.global.s32 [%output_addr], %group_value;
    mul.lo.u64 %output_addr, %group_count, 8;
    add.u64 %output_addr, %out_counts, %output_addr;
    mov.u64 %new_count, 1;
    st.global.u64 [%output_addr], %new_count;
    mul.lo.u64 %output_addr, %group_count, 8;
    add.u64 %output_addr, %out_sums, %output_addr;
    st.global.s64 [%output_addr], %r_value_wide;
    mul.lo.u64 %output_addr, %group_count, 4;
    add.u64 %output_addr, %out_mins, %output_addr;
    st.global.s32 [%output_addr], %r_value;
    mul.lo.u64 %output_addr, %group_count, 4;
    add.u64 %output_addr, %out_maxs, %output_addr;
    st.global.s32 [%output_addr], %r_value;
    add.u64 %group_count, %group_count, 1;

next_row:
    add.u64 %idx, %idx, 1;
    bra row_loop;

done:
    st.global.u64 [%out_count], %group_count;
    ret;
}
"#;

    let group_bytes = row_count
        .checked_mul(std::mem::size_of::<i32>() as u64)
        .and_then(|bytes| group_byte_offset.checked_add(bytes))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let value_bytes = row_count
        .checked_mul(std::mem::size_of::<i32>() as u64)
        .and_then(|bytes| value_byte_offset.checked_add(bytes))
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    if group_bytes > resident.metadata().allocated_bytes {
        return Err(CudaRuntimeProbeError::InvalidInputLength(
            group_bytes as usize,
        ));
    }
    if value_bytes > resident.metadata().allocated_bytes {
        return Err(CudaRuntimeProbeError::InvalidInputLength(
            value_bytes as usize,
        ));
    }
    let (filter_byte_offset, needle, comparison_code) =
        if let Some((filter_byte_offset, needle, comparison)) = filter {
            let filter_bytes = row_count
                .checked_mul(std::mem::size_of::<i32>() as u64)
                .and_then(|bytes| filter_byte_offset.checked_add(bytes))
                .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
            if filter_bytes > resident.metadata().allocated_bytes {
                return Err(CudaRuntimeProbeError::InvalidInputLength(
                    filter_bytes as usize,
                ));
            }
            (filter_byte_offset, needle, comparison.code())
        } else {
            (group_byte_offset, 0, 0)
        };
    if row_count == 0 {
        return Ok(Vec::new());
    }

    let cu_mem_alloc = unsafe {
        resident
            .lib()
            .get::<CuMemAlloc>(b"cuMemAlloc_v2\0")
            .or_else(|_| resident.lib().get::<CuMemAlloc>(b"cuMemAlloc\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_mem_free = unsafe {
        resident
            .lib()
            .get::<CuMemFree>(b"cuMemFree_v2\0")
            .or_else(|_| resident.lib().get::<CuMemFree>(b"cuMemFree\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_module_load_data = unsafe {
        resident
            .lib()
            .get::<CuModuleLoadData>(b"cuModuleLoadData\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_module_unload = unsafe {
        resident
            .lib()
            .get::<CuModuleUnload>(b"cuModuleUnload\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_module_get_function = unsafe {
        resident
            .lib()
            .get::<CuModuleGetFunction>(b"cuModuleGetFunction\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_ctx_synchronize = unsafe {
        resident
            .lib()
            .get::<CuCtxSynchronize>(b"cuCtxSynchronize\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };

    let group_output_bytes = usize::try_from(
        row_count
            .checked_mul(std::mem::size_of::<i32>() as u64)
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?,
    )
    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let sum_output_bytes = usize::try_from(
        row_count
            .checked_mul(std::mem::size_of::<i64>() as u64)
            .ok_or(CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?,
    )
    .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let mut device_groups = 0_u64;
    check_cuda(unsafe { cu_mem_alloc(&mut device_groups, group_output_bytes) })?;
    let groups_guard = CudaDeviceAllocationGuard {
        ptr: device_groups,
        free: *cu_mem_free,
    };
    let counts_output_bytes = sum_output_bytes;
    let mut device_counts = 0_u64;
    check_cuda(unsafe { cu_mem_alloc(&mut device_counts, counts_output_bytes) })?;
    let counts_guard = CudaDeviceAllocationGuard {
        ptr: device_counts,
        free: *cu_mem_free,
    };
    let mut device_sums = 0_u64;
    check_cuda(unsafe { cu_mem_alloc(&mut device_sums, sum_output_bytes) })?;
    let sums_guard = CudaDeviceAllocationGuard {
        ptr: device_sums,
        free: *cu_mem_free,
    };
    let mut device_mins = 0_u64;
    check_cuda(unsafe { cu_mem_alloc(&mut device_mins, group_output_bytes) })?;
    let mins_guard = CudaDeviceAllocationGuard {
        ptr: device_mins,
        free: *cu_mem_free,
    };
    let mut device_maxs = 0_u64;
    check_cuda(unsafe { cu_mem_alloc(&mut device_maxs, group_output_bytes) })?;
    let maxs_guard = CudaDeviceAllocationGuard {
        ptr: device_maxs,
        free: *cu_mem_free,
    };
    let mut device_count = 0_u64;
    check_cuda(unsafe { cu_mem_alloc(&mut device_count, std::mem::size_of::<u64>()) })?;
    let count_guard = CudaDeviceAllocationGuard {
        ptr: device_count,
        free: *cu_mem_free,
    };

    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);

    let mut module = std::ptr::null_mut();
    check_cuda(unsafe { cu_module_load_data(&mut module, ptx.as_ptr().cast::<c_void>()) })?;
    let module_guard = CudaModuleGuard {
        module,
        unload: *cu_module_unload,
    };

    let mut function = std::ptr::null_mut();
    check_cuda(unsafe {
        cu_module_get_function(
            &mut function,
            module,
            c"gpu_db_resident_i32_grouped_stats".as_ptr(),
        )
    })?;

    let mut resident_arg = resident.device_ptr();
    let mut group_offset_arg = group_byte_offset;
    let mut value_offset_arg = value_byte_offset;
    let mut filter_offset_arg = filter_byte_offset;
    let mut rows_arg = row_count;
    let mut needle_arg = needle;
    let mut comparison_arg = comparison_code;
    let mut groups_arg = groups_guard.ptr;
    let mut counts_arg = counts_guard.ptr;
    let mut sums_arg = sums_guard.ptr;
    let mut mins_arg = mins_guard.ptr;
    let mut maxs_arg = maxs_guard.ptr;
    let mut count_arg = count_guard.ptr;
    let mut args = [
        (&mut resident_arg as *mut u64).cast::<c_void>(),
        (&mut group_offset_arg as *mut u64).cast::<c_void>(),
        (&mut value_offset_arg as *mut u64).cast::<c_void>(),
        (&mut filter_offset_arg as *mut u64).cast::<c_void>(),
        (&mut rows_arg as *mut u64).cast::<c_void>(),
        (&mut needle_arg as *mut i32).cast::<c_void>(),
        (&mut comparison_arg as *mut u32).cast::<c_void>(),
        (&mut groups_arg as *mut u64).cast::<c_void>(),
        (&mut counts_arg as *mut u64).cast::<c_void>(),
        (&mut sums_arg as *mut u64).cast::<c_void>(),
        (&mut mins_arg as *mut u64).cast::<c_void>(),
        (&mut maxs_arg as *mut u64).cast::<c_void>(),
        (&mut count_arg as *mut u64).cast::<c_void>(),
    ];
    launch_with_optional_cuda_event_timing(resident, *cu_ctx_synchronize, || unsafe {
        cu_launch_kernel(
            function,
            1,
            1,
            1,
            1,
            1,
            1,
            0,
            std::ptr::null_mut(),
            args.as_mut_ptr(),
            std::ptr::null_mut(),
        )
    })?;

    let mut output_count = 0_u64;
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            (&mut output_count as *mut u64).cast::<c_void>(),
            count_guard.ptr,
            std::mem::size_of::<u64>(),
        )
    })?;
    if output_count > row_count {
        return Err(CudaRuntimeProbeError::InvalidInputLength(
            usize::try_from(output_count).unwrap_or(usize::MAX),
        ));
    }

    let output_len = usize::try_from(output_count)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(usize::MAX))?;
    let mut groups = vec![0_i32; output_len];
    let mut counts = vec![0_u64; output_len];
    let mut sums = vec![0_i64; output_len];
    let mut mins = vec![0_i32; output_len];
    let mut maxs = vec![0_i32; output_len];
    if output_len > 0 {
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                groups.as_mut_ptr().cast::<c_void>(),
                groups_guard.ptr,
                output_len * std::mem::size_of::<i32>(),
            )
        })?;
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                counts.as_mut_ptr().cast::<c_void>(),
                counts_guard.ptr,
                output_len * std::mem::size_of::<u64>(),
            )
        })?;
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                sums.as_mut_ptr().cast::<c_void>(),
                sums_guard.ptr,
                output_len * std::mem::size_of::<i64>(),
            )
        })?;
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                mins.as_mut_ptr().cast::<c_void>(),
                mins_guard.ptr,
                output_len * std::mem::size_of::<i32>(),
            )
        })?;
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                maxs.as_mut_ptr().cast::<c_void>(),
                maxs_guard.ptr,
                output_len * std::mem::size_of::<i32>(),
            )
        })?;
    }

    drop(module_guard);
    drop(count_guard);
    drop(maxs_guard);
    drop(mins_guard);
    drop(sums_guard);
    drop(counts_guard);
    drop(groups_guard);
    Ok(groups
        .into_iter()
        .zip(counts)
        .zip(sums)
        .zip(mins)
        .zip(maxs)
        .map(|((((group, count), sum), min), max)| CudaI32GroupedStats {
            group,
            count,
            sum,
            min,
            max,
        })
        .collect())
}

/// §9.5/S5a.3 (slices 2–3) — pack a grouped aggregate + its group into one i64 sort key per group so
/// that an ASCENDING argsort reproduces the host "ORDER BY agg <dir>, group ASC tie-break" order: the
/// direction is baked into the high 32 bits (DESC => 0xFFFFFFFF-key), the group is u32-biased into the
/// low 32 bits (ascending), and the composite is XOR 0x8000…0 so signed-i64 sort == the intended sort.
/// Writes `out_key_device_ptr[0..n]` (i64). `ptx_source`/`kernel_name` pick the aggregate width:
/// `pack.ptx`/`gpu_db_pack_count_group` (count u64≤u32) or `pack_i32.ptx`/`gpu_db_pack_i32agg_group`
/// (i32 min/max, or group-by-group). Caller ensures count keys fit u32 (row_count ≤ u32::MAX).
#[allow(clippy::too_many_arguments)]
fn launch_cuda_resident_pack_grouped_sort_key(
    resident: &CudaResidentDeviceMemory,
    ptx_source: &[u8],
    kernel_name: &'static core::ffi::CStr,
    agg_device_ptr: u64,
    groups_device_ptr: u64,
    n: u64,
    descending: bool,
    out_key_device_ptr: u64,
) -> Result<(), CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;

    if n == 0 {
        return Ok(());
    }
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let mut ptx = Vec::with_capacity(ptx_source.len() + 1);
    ptx.extend_from_slice(ptx_source);
    ptx.push(0);
    let kernel_fn = resident.primary().cached_function(kernel_name, &ptx)?;

    let primary = resident.primary();
    primary.set_current()?;
    struct StreamLease<'a> {
        primary: &'a GpuPrimaryContext,
        pooled: Option<PooledStream>,
    }
    impl Drop for StreamLease<'_> {
        fn drop(&mut self) {
            if let Some(pooled) = self.pooled.take() {
                self.primary.release_pooled_stream(pooled);
            }
        }
    }
    let lease = StreamLease {
        primary,
        pooled: Some(primary.acquire_pooled_stream()?),
    };
    let stream = lease
        .pooled
        .as_ref()
        .expect("pooled stream just set")
        .stream;
    let drain_err = |err: CudaRuntimeProbeError| -> CudaRuntimeProbeError {
        unsafe {
            let _ = (primary.cu_stream_synchronize)(stream);
        }
        err
    };

    const BLOCK: u32 = 256;
    let grid = n.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;
    let mut agg_arg = agg_device_ptr;
    let mut groups_arg = groups_device_ptr;
    let mut n_arg = n;
    let mut desc_arg = u32::from(descending);
    let mut outk_arg = out_key_device_ptr;
    let mut args = [
        (&mut agg_arg as *mut u64).cast::<c_void>(),
        (&mut groups_arg as *mut u64).cast::<c_void>(),
        (&mut n_arg as *mut u64).cast::<c_void>(),
        (&mut desc_arg as *mut u32).cast::<c_void>(),
        (&mut outk_arg as *mut u64).cast::<c_void>(),
    ];
    check_cuda(unsafe {
        cu_launch_kernel(
            kernel_fn,
            grid,
            1,
            1,
            BLOCK,
            1,
            1,
            0,
            stream,
            args.as_mut_ptr(),
            std::ptr::null_mut(),
        )
    })
    .map_err(drain_err)?;
    check_cuda(unsafe { (primary.cu_stream_synchronize)(stream) }).map_err(drain_err)?;
    resident.record_kernel_event_elapsed_us(None);
    drop(lease);
    Ok(())
}

/// §9.5/S5a.3 slice 4 — widen an i32 device column (`src_device_ptr[0..n]`) to i64 (sign-extend) into
/// `dst_device_ptr[0..n]`, so the grouped result's i32 group/min/max columns can be fed to the GPU
/// HAVING filter (which compares i64 group + i64 aggregate).
fn launch_cuda_resident_widen_i32_to_i64(
    resident: &CudaResidentDeviceMemory,
    src_device_ptr: u64,
    n: u64,
    dst_device_ptr: u64,
) -> Result<(), CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    const PTX: &[u8] = include_bytes!("widen.ptx");

    if n == 0 {
        return Ok(());
    }
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let kernel_fn = resident
        .primary()
        .cached_function(c"gpu_db_widen_i32_to_i64", &ptx)?;

    let primary = resident.primary();
    primary.set_current()?;
    struct StreamLease<'a> {
        primary: &'a GpuPrimaryContext,
        pooled: Option<PooledStream>,
    }
    impl Drop for StreamLease<'_> {
        fn drop(&mut self) {
            if let Some(pooled) = self.pooled.take() {
                self.primary.release_pooled_stream(pooled);
            }
        }
    }
    let lease = StreamLease {
        primary,
        pooled: Some(primary.acquire_pooled_stream()?),
    };
    let stream = lease
        .pooled
        .as_ref()
        .expect("pooled stream just set")
        .stream;
    let drain_err = |err: CudaRuntimeProbeError| -> CudaRuntimeProbeError {
        unsafe {
            let _ = (primary.cu_stream_synchronize)(stream);
        }
        err
    };

    const BLOCK: u32 = 256;
    let grid = n.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;
    let mut src_arg = src_device_ptr;
    let mut n_arg = n;
    let mut dst_arg = dst_device_ptr;
    let mut args = [
        (&mut src_arg as *mut u64).cast::<c_void>(),
        (&mut n_arg as *mut u64).cast::<c_void>(),
        (&mut dst_arg as *mut u64).cast::<c_void>(),
    ];
    check_cuda(unsafe {
        cu_launch_kernel(
            kernel_fn,
            grid,
            1,
            1,
            BLOCK,
            1,
            1,
            0,
            stream,
            args.as_mut_ptr(),
            std::ptr::null_mut(),
        )
    })
    .map_err(drain_err)?;
    check_cuda(unsafe { (primary.cu_stream_synchronize)(stream) }).map_err(drain_err)?;
    resident.record_kernel_event_elapsed_us(None);
    drop(lease);
    Ok(())
}

// Gather i64 values by a host u32 permutation: out[i] = in[perm[i]]. Uploads the (small, M-group)
// permutation to the device, then runs the grid-stride gather on a pooled private stream. Used by
// the on-device two-key SUM sort to reorder the SUM column into group-ascending order before the
// stable SUM argsort, so equal sums break by group ASC fully on-device (SUM is a full i64 and can't
// be packed with the group into a composite key like count/min/max/group).
fn launch_cuda_resident_gather_i64_by_u32_perm(
    resident: &CudaResidentDeviceMemory,
    in_device_ptr: u64,
    perm: &[u32],
    out_device_ptr: u64,
) -> Result<(), CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    type CuMemcpyHtoD = unsafe extern "C" fn(u64, *const c_void, usize) -> i32;
    const PTX: &[u8] = include_bytes!("gather.ptx");

    let n = perm.len() as u64;
    if n == 0 {
        return Ok(());
    }
    let primary = resident.primary();
    primary.set_current()?;
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_htod = unsafe {
        resident
            .lib()
            .get::<CuMemcpyHtoD>(b"cuMemcpyHtoD_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyHtoD>(b"cuMemcpyHtoD\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let kernel_fn = primary.cached_function(c"gpu_db_gather_i64_by_u32_perm", &ptx)?;

    let perm_bytes = std::mem::size_of_val(perm);
    let perm_buf = primary.lease_device_buffer(perm_bytes)?;
    check_cuda(unsafe {
        cu_memcpy_htod(perm_buf.ptr, perm.as_ptr().cast::<c_void>(), perm_bytes)
    })?;

    const BLOCK: u32 = 256;
    let grid = n.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;
    let mut in_arg = in_device_ptr;
    let mut perm_arg = perm_buf.ptr;
    let mut n_arg = n;
    let mut out_arg = out_device_ptr;
    let mut args = [
        (&mut in_arg as *mut u64).cast::<c_void>(),
        (&mut perm_arg as *mut u64).cast::<c_void>(),
        (&mut n_arg as *mut u64).cast::<c_void>(),
        (&mut out_arg as *mut u64).cast::<c_void>(),
    ];
    launch_on_pooled_stream(resident, None, |stream, _scratch| unsafe {
        cu_launch_kernel(
            kernel_fn,
            grid,
            1,
            1,
            BLOCK,
            1,
            1,
            0,
            stream,
            args.as_mut_ptr(),
            std::ptr::null_mut(),
        )
    })
}

// PROTOTYPE — general GPU executor (docs/architecture/17-general-gpu-executor.md §5).
// Evaluates the predicate `(a <op> b) <cmp> needle` over two resident int4 columns by COMPOSING two
// buffer->buffer primitives on one pooled stream — the vectorized-interpreter model that replaces
// hand-coded per-shape kernels:
//   (1) `gpu_db_resident_i32_binary_elementwise` writes the INTERMEDIATE `t = a <op> b` into a leased
//       device buffer (the key generalization: `t` is not a resident payload column);
//   (2) `gpu_db_buffer_i32_compare_to_indices` scans the intermediate `t` and atomic-appends the
//       matching row indices.
// Returns the matching row indices, host-sorted ascending for determinism (the atomic-append order is
// the non-deterministic GPU schedule; same pattern as `..._equal_row_indices`). The caller gathers
// the projected column at these indices via the existing `project_i32_rows_from_payload`. This is a
// proof of the buffer-intermediate + Expr-lowering + primitive-composition models, NOT a new shape
// method — the predicate is interpreted, and arbitrary trees lower to longer pipelines of the same
// primitives.
fn launch_cuda_resident_expr_two_col_filter(
    resident: &CudaResidentDeviceMemory,
    a_byte_offset: u64,
    b_byte_offset: u64,
    op_code: u32,
    n: u64,
    needle: i32,
    comparison: u32,
) -> Result<Vec<u32>, CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    type CuMemcpyHtoD = unsafe extern "C" fn(u64, *const c_void, usize) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    const PTX: &[u8] = include_bytes!("expr_proto.ptx");

    if n == 0 {
        return Ok(Vec::new());
    }
    let n_usize = usize::try_from(n).map_err(|_| CudaRuntimeProbeError::InvalidInputLength(0))?;
    let byte_len = n_usize
        .checked_mul(std::mem::size_of::<i32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(n_usize))?;

    let primary = resident.primary();
    primary.set_current()?;
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_htod = unsafe {
        resident
            .lib()
            .get::<CuMemcpyHtoD>(b"cuMemcpyHtoD_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyHtoD>(b"cuMemcpyHtoD\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let elementwise_fn =
        primary.cached_function(c"gpu_db_resident_i32_binary_elementwise", &ptx)?;
    let compare_fn = primary.cached_function(c"gpu_db_buffer_i32_compare_to_indices", &ptx)?;

    // Intermediate `t` buffer, the matching-index output buffer, and the atomic counter.
    let intermediate = primary.lease_device_buffer(byte_len)?;
    let indices_buf = primary.lease_device_buffer(byte_len)?;
    let count_buf = primary.lease_device_buffer(std::mem::size_of::<u32>())?;
    // CHECKED int4 arithmetic (Charter rule 2 PG-fidelity): the elementwise kernel ORs 1 into this
    // flag if `a <op> b` overflows int32; the host raises `integer out of range` after the launches.
    let overflow_buf = primary.lease_device_buffer(std::mem::size_of::<u32>())?;
    // Zero the atomic counter AND the overflow flag with blocking HtoDs before the kernels
    // (synchronous, so they complete before the pooled-stream launches read/write them).
    let zero = 0_u32;
    check_cuda(unsafe {
        cu_memcpy_htod(
            count_buf.ptr,
            (&zero as *const u32).cast::<c_void>(),
            std::mem::size_of::<u32>(),
        )
    })?;
    check_cuda(unsafe {
        cu_memcpy_htod(
            overflow_buf.ptr,
            (&zero as *const u32).cast::<c_void>(),
            std::mem::size_of::<u32>(),
        )
    })?;

    const BLOCK: u32 = 256;
    let grid = n.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;

    let mut res_arg = resident.device_ptr();
    let mut a_arg = a_byte_offset;
    let mut b_arg = b_byte_offset;
    let mut n_arg = n;
    let mut op_arg = op_code;
    let mut t_arg = intermediate.ptr;
    let mut ovf_arg = overflow_buf.ptr;
    let mut ew_args = [
        (&mut res_arg as *mut u64).cast::<c_void>(),
        (&mut a_arg as *mut u64).cast::<c_void>(),
        (&mut b_arg as *mut u64).cast::<c_void>(),
        (&mut n_arg as *mut u64).cast::<c_void>(),
        (&mut op_arg as *mut u32).cast::<c_void>(),
        (&mut t_arg as *mut u64).cast::<c_void>(),
        (&mut ovf_arg as *mut u64).cast::<c_void>(),
    ];

    let mut in_arg = intermediate.ptr;
    let mut n2_arg = n;
    let mut needle_arg = needle;
    let mut cmp_arg = comparison;
    let mut count_arg = count_buf.ptr;
    let mut idx_arg = indices_buf.ptr;
    let mut cmp_args = [
        (&mut in_arg as *mut u64).cast::<c_void>(),
        (&mut n2_arg as *mut u64).cast::<c_void>(),
        (&mut needle_arg as *mut i32).cast::<c_void>(),
        (&mut cmp_arg as *mut u32).cast::<c_void>(),
        (&mut count_arg as *mut u64).cast::<c_void>(),
        (&mut idx_arg as *mut u64).cast::<c_void>(),
    ];

    // Both kernels on ONE pooled stream: stream order makes the compare read `t` only after the
    // elementwise write completes. `launch_on_pooled_stream` syncs (and drains on error) before
    // returning, so the blocking readback below sees finished work.
    launch_on_pooled_stream(resident, None, |stream, _scratch| {
        let first = unsafe {
            cu_launch_kernel(
                elementwise_fn,
                grid,
                1,
                1,
                BLOCK,
                1,
                1,
                0,
                stream,
                ew_args.as_mut_ptr(),
                std::ptr::null_mut(),
            )
        };
        if first != 0 {
            return first;
        }
        unsafe {
            cu_launch_kernel(
                compare_fn,
                grid,
                1,
                1,
                BLOCK,
                1,
                1,
                0,
                stream,
                cmp_args.as_mut_ptr(),
                std::ptr::null_mut(),
            )
        }
    })?;

    // PG-fidelity: if any row's `a <op> b` overflowed int32, the elementwise kernel set the flag.
    // Raise `integer out of range` and discard the (now-untrustworthy) comparison result, exactly as
    // Postgres aborts the statement. Read before the count so an overflow never returns rows.
    let mut overflow = 0_u32;
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            (&mut overflow as *mut u32).cast::<c_void>(),
            overflow_buf.ptr,
            std::mem::size_of::<u32>(),
        )
    })?;
    if overflow != 0 {
        return Err(CudaRuntimeProbeError::IntegerOutOfRange);
    }

    let mut match_count = 0_u32;
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            (&mut match_count as *mut u32).cast::<c_void>(),
            count_buf.ptr,
            std::mem::size_of::<u32>(),
        )
    })?;
    let match_count = usize::try_from(match_count)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(0))?
        .min(n_usize);
    let mut indices = vec![0_u32; match_count];
    if match_count > 0 {
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                indices.as_mut_ptr().cast::<c_void>(),
                indices_buf.ptr,
                match_count * std::mem::size_of::<u32>(),
            )
        })?;
    }
    // Atomic-append order is the GPU schedule; sort for a deterministic result (matches the engine's
    // stable row order and the `..._equal_row_indices` host-sort).
    indices.sort_unstable();
    Ok(indices)
}

/// One step of the resident expression bytecode (docs/architecture/17 section 2.3): a postfix
/// program over a stack of device buffers. Value steps build an int4 arithmetic expression into a
/// value buffer; comparison steps turn value buffer(s) into a 0/1 MASK buffer; `MaskBinary` combines
/// masks. A boolean predicate program leaves one mask (compacted to indices by the predicate VM); the
/// arithmetic / col-vs-col filters use only the value steps and fuse the terminal comparison. `op` is
/// 0=add/1=sub/2=mul (arithmetic) or 0=and/1=or (mask); `cmp` is 0=eq/1=lt/2=le/3=gt/4=ge/5=ne.
#[derive(Debug, Clone, Copy)]
pub enum ExprStep {
    /// Push the resident int4 column at `byte_offset` (loaded into a fresh buffer).
    LoadColumn { byte_offset: u64 },
    /// Pop b, pop a, push `a <op> b` (buffer x buffer).
    BufferBinary { op: u32 },
    /// Pop a, push `a <op> scalar` (or `scalar <op> a` if `scalar_on_left`) — folds an immediate
    /// literal operand without materializing a constant buffer.
    ScalarBinary {
        op: u32,
        scalar: i32,
        scalar_on_left: bool,
    },
    /// Pop a (value), push the mask `(scalar_on_left ? scalar <cmp> a : a <cmp> scalar) ? 1 : 0`.
    CompareScalar {
        cmp: u32,
        scalar: i32,
        scalar_on_left: bool,
    },
    /// Pop b, pop a (values), push the mask `(a <cmp> b) ? 1 : 0`.
    CompareBuffers { cmp: u32 },
    /// Pop b, pop a (masks), push `op==0 ? a&&b : a||b` (0/1).
    MaskBinary { op: u32 },
}

/// Compare an int4 value buffer (absolute device ptr) to `needle` and return the matching row
/// indices, host-sorted ascending. Shared compare-and-compact tail for the arithmetic VM (the 2-col
/// fast-path launcher keeps its own fused copy). `comparison`: 0=eq, 1=lt, 2=le, 3=gt, 4=ge.
fn compact_buffer_i32_compare_to_indices(
    resident: &CudaResidentDeviceMemory,
    value_device_ptr: u64,
    n: u64,
    needle: i32,
    comparison: u32,
) -> Result<Vec<u32>, CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    type CuMemcpyHtoD = unsafe extern "C" fn(u64, *const c_void, usize) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    const PTX: &[u8] = include_bytes!("expr_proto.ptx");

    // The scalar compact kernel switches on codes 0=eq..4=ge only; reject 5=ne (mask-path only) so a
    // caller gets an error, not a silently-empty result.
    if comparison > 4 {
        return Err(CudaRuntimeProbeError::UnsupportedComparison(comparison));
    }
    if n == 0 {
        return Ok(Vec::new());
    }
    let n_usize = usize::try_from(n).map_err(|_| CudaRuntimeProbeError::InvalidInputLength(0))?;
    let byte_len = n_usize
        .checked_mul(std::mem::size_of::<i32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(n_usize))?;

    let primary = resident.primary();
    primary.set_current()?;
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_htod = unsafe {
        resident
            .lib()
            .get::<CuMemcpyHtoD>(b"cuMemcpyHtoD_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyHtoD>(b"cuMemcpyHtoD\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let compare_fn = primary.cached_function(c"gpu_db_buffer_i32_compare_to_indices", &ptx)?;

    let indices_buf = primary.lease_device_buffer(byte_len)?;
    let count_buf = primary.lease_device_buffer(std::mem::size_of::<u32>())?;
    let zero = 0_u32;
    check_cuda(unsafe {
        cu_memcpy_htod(
            count_buf.ptr,
            (&zero as *const u32).cast::<c_void>(),
            std::mem::size_of::<u32>(),
        )
    })?;

    const BLOCK: u32 = 256;
    let grid = n.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;
    let mut in_arg = value_device_ptr;
    let mut n_arg = n;
    let mut needle_arg = needle;
    let mut cmp_arg = comparison;
    let mut count_arg = count_buf.ptr;
    let mut idx_arg = indices_buf.ptr;
    let mut args = [
        (&mut in_arg as *mut u64).cast::<c_void>(),
        (&mut n_arg as *mut u64).cast::<c_void>(),
        (&mut needle_arg as *mut i32).cast::<c_void>(),
        (&mut cmp_arg as *mut u32).cast::<c_void>(),
        (&mut count_arg as *mut u64).cast::<c_void>(),
        (&mut idx_arg as *mut u64).cast::<c_void>(),
    ];
    launch_on_pooled_stream(resident, None, |stream, _scratch| unsafe {
        cu_launch_kernel(
            compare_fn,
            grid,
            1,
            1,
            BLOCK,
            1,
            1,
            0,
            stream,
            args.as_mut_ptr(),
            std::ptr::null_mut(),
        )
    })?;

    let mut match_count = 0_u32;
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            (&mut match_count as *mut u32).cast::<c_void>(),
            count_buf.ptr,
            std::mem::size_of::<u32>(),
        )
    })?;
    let match_count = usize::try_from(match_count)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(0))?
        .min(n_usize);
    let mut indices = vec![0_u32; match_count];
    if match_count > 0 {
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                indices.as_mut_ptr().cast::<c_void>(),
                indices_buf.ptr,
                match_count * std::mem::size_of::<u32>(),
            )
        })?;
    }
    indices.sort_unstable();
    Ok(indices)
}

/// PROTOTYPE — the resident arithmetic bytecode VM (docs/architecture/17 section 2.3). Runs a postfix
/// `program` over a stack of leased device buffers to evaluate an ARBITRARY int4 arithmetic tree on
/// device (each step launches one buffer->buffer primitive), then compares the single result buffer
/// to `needle` and returns the matching row indices. This is the general recursive interpreter that
/// generalizes the fixed 2-col fast-path: arbitrary depth lowers to a longer program of the same
/// primitives. Correctness-first: each step runs on a pooled stream that syncs, so an intermediate
/// is valid before the next step reads it (pipelining/fusion is a later perf lever).
/// Compare two int4 value buffers (absolute device ptrs) elementwise and return the matching row
/// indices, host-sorted ascending. The col-vs-col / expr-vs-expr analogue of
/// `compact_buffer_i32_compare_to_indices`. `comparison`: 0=eq, 1=lt, 2=le, 3=gt, 4=ge.
fn compact_buffers_i32_compare_to_indices(
    resident: &CudaResidentDeviceMemory,
    lhs_device_ptr: u64,
    rhs_device_ptr: u64,
    n: u64,
    comparison: u32,
) -> Result<Vec<u32>, CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    type CuMemcpyHtoD = unsafe extern "C" fn(u64, *const c_void, usize) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    const PTX: &[u8] = include_bytes!("expr_proto.ptx");

    // The buffer compact kernel switches on codes 0=eq..4=ge only; reject 5=ne (mask-path only).
    if comparison > 4 {
        return Err(CudaRuntimeProbeError::UnsupportedComparison(comparison));
    }
    if n == 0 {
        return Ok(Vec::new());
    }
    let n_usize = usize::try_from(n).map_err(|_| CudaRuntimeProbeError::InvalidInputLength(0))?;
    let byte_len = n_usize
        .checked_mul(std::mem::size_of::<i32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(n_usize))?;

    let primary = resident.primary();
    primary.set_current()?;
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_htod = unsafe {
        resident
            .lib()
            .get::<CuMemcpyHtoD>(b"cuMemcpyHtoD_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyHtoD>(b"cuMemcpyHtoD\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let compare_fn = primary.cached_function(c"gpu_db_buffer_i32_compare_buffers_to_indices", &ptx)?;

    let indices_buf = primary.lease_device_buffer(byte_len)?;
    let count_buf = primary.lease_device_buffer(std::mem::size_of::<u32>())?;
    let zero = 0_u32;
    check_cuda(unsafe {
        cu_memcpy_htod(
            count_buf.ptr,
            (&zero as *const u32).cast::<c_void>(),
            std::mem::size_of::<u32>(),
        )
    })?;

    const BLOCK: u32 = 256;
    let grid = n.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;
    let mut a_arg = lhs_device_ptr;
    let mut b_arg = rhs_device_ptr;
    let mut n_arg = n;
    let mut cmp_arg = comparison;
    let mut count_arg = count_buf.ptr;
    let mut idx_arg = indices_buf.ptr;
    let mut args = [
        (&mut a_arg as *mut u64).cast::<c_void>(),
        (&mut b_arg as *mut u64).cast::<c_void>(),
        (&mut n_arg as *mut u64).cast::<c_void>(),
        (&mut cmp_arg as *mut u32).cast::<c_void>(),
        (&mut count_arg as *mut u64).cast::<c_void>(),
        (&mut idx_arg as *mut u64).cast::<c_void>(),
    ];
    launch_on_pooled_stream(resident, None, |stream, _scratch| unsafe {
        cu_launch_kernel(
            compare_fn,
            grid,
            1,
            1,
            BLOCK,
            1,
            1,
            0,
            stream,
            args.as_mut_ptr(),
            std::ptr::null_mut(),
        )
    })?;

    let mut match_count = 0_u32;
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            (&mut match_count as *mut u32).cast::<c_void>(),
            count_buf.ptr,
            std::mem::size_of::<u32>(),
        )
    })?;
    let match_count = usize::try_from(match_count)
        .map_err(|_| CudaRuntimeProbeError::InvalidInputLength(0))?
        .min(n_usize);
    let mut indices = vec![0_u32; match_count];
    if match_count > 0 {
        check_cuda(unsafe {
            cu_memcpy_dtoh(
                indices.as_mut_ptr().cast::<c_void>(),
                indices_buf.ptr,
                match_count * std::mem::size_of::<u32>(),
            )
        })?;
    }
    indices.sort_unstable();
    Ok(indices)
}

/// Execute an arithmetic bytecode `program` over a stack of leased device buffers and return the
/// resulting stack (each step launches one buffer->buffer primitive on a syncing pooled stream). The
/// returned leases borrow `resident`; the caller consumes the stack (one value for a scalar compare,
/// two for a buffer-vs-buffer compare). Callers handle `n == 0` before calling.
/// The element type of a resident arithmetic VM program (the type matrix, doc 19): int4 buffers
/// (s32, 4 bytes), int8 buffers (s64, 8 bytes), or numeric buffers (i128, 16 bytes). A program is
/// mono-typed; the VM selects per-step kernels + intermediate-buffer sizes by this. The mask AND/OR +
/// mask->indices compaction stages are type-agnostic (they operate on i32 0/1 masks) and are shared.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ResidentElemType {
    I32,
    I64,
    I128,
}

impl ResidentElemType {
    fn elem_size(self) -> usize {
        match self {
            Self::I32 => std::mem::size_of::<i32>(),
            Self::I64 => std::mem::size_of::<i64>(),
            Self::I128 => std::mem::size_of::<i128>(),
        }
    }
}

fn run_resident_arith_program<'r>(
    resident: &'r CudaResidentDeviceMemory,
    program: &[ExprStep],
    n: u64,
    elem: ResidentElemType,
) -> Result<Vec<PooledBufferLease<'r>>, CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    type CuMemcpyHtoD = unsafe extern "C" fn(u64, *const c_void, usize) -> i32;
    type CuMemcpyDtoH = unsafe extern "C" fn(*mut c_void, u64, usize) -> i32;
    const PTX: &[u8] = include_bytes!("expr_proto.ptx");

    let n_usize = usize::try_from(n).map_err(|_| CudaRuntimeProbeError::InvalidInputLength(0))?;
    let byte_len = n_usize
        .checked_mul(elem.elem_size())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(n_usize))?;

    let primary = resident.primary();
    primary.set_current()?;
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_htod = unsafe {
        resident
            .lib()
            .get::<CuMemcpyHtoD>(b"cuMemcpyHtoD_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyHtoD>(b"cuMemcpyHtoD\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let cu_memcpy_dtoh = unsafe {
        resident
            .lib()
            .get::<CuMemcpyDtoH>(b"cuMemcpyDtoH_v2\0")
            .or_else(|_| resident.lib().get::<CuMemcpyDtoH>(b"cuMemcpyDtoH\0"))
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    // Per-element-type kernels (the type matrix, doc 19); the mask-binary stage is type-agnostic.
    let (load_name, binary_name, scalar_name, compare_scalar_name, compare_buffers_name) = match elem
    {
        ResidentElemType::I32 => (
            c"gpu_db_resident_i32_load_column",
            c"gpu_db_buffer_i32_binary",
            c"gpu_db_buffer_i32_binary_scalar",
            c"gpu_db_buffer_i32_compare_scalar_to_mask",
            c"gpu_db_buffer_i32_compare_buffers_to_mask",
        ),
        ResidentElemType::I64 => (
            c"gpu_db_resident_i64_load_column",
            c"gpu_db_buffer_i64_binary",
            c"gpu_db_buffer_i64_binary_scalar",
            c"gpu_db_buffer_i64_compare_scalar_to_mask",
            c"gpu_db_buffer_i64_compare_buffers_to_mask",
        ),
        ResidentElemType::I128 => (
            c"gpu_db_resident_i128_load_column",
            c"gpu_db_buffer_i128_binary",
            c"gpu_db_buffer_i128_binary_scalar",
            c"gpu_db_buffer_i128_compare_scalar_to_mask",
            c"gpu_db_buffer_i128_compare_buffers_to_mask",
        ),
    };
    let load_fn = primary.cached_function(load_name, &ptx)?;
    let buffer_binary_fn = primary.cached_function(binary_name, &ptx)?;
    let scalar_binary_fn = primary.cached_function(scalar_name, &ptx)?;
    let compare_scalar_mask_fn = primary.cached_function(compare_scalar_name, &ptx)?;
    let compare_buffers_mask_fn = primary.cached_function(compare_buffers_name, &ptx)?;
    let mask_binary_fn = primary.cached_function(c"gpu_db_mask_binary", &ptx)?;
    // numeric (i128) multiply is a SEPARATE kernel — the signed 128x128->256 product is too large to
    // inline into the add/sub binary kernel — loaded only for I128. int4/int8 multiply lives in their
    // binary kernel (mul.hi), so this stays None there.
    let i128_mul_scalar_fn = match elem {
        ResidentElemType::I128 => {
            Some(primary.cached_function(c"gpu_db_buffer_i128_mul_scalar", &ptx)?)
        }
        ResidentElemType::I32 | ResidentElemType::I64 => None,
    };
    // column*column multiply for I128 is its own kernel too; None for int4/int8 (their binary kernel
    // handles multiply), so the BufferBinary arm keeps using buffer_binary_fn there.
    let i128_mul_buffer_fn = match elem {
        ResidentElemType::I128 => Some(primary.cached_function(c"gpu_db_buffer_i128_mul", &ptx)?),
        ResidentElemType::I32 | ResidentElemType::I64 => None,
    };

    // CHECKED int4 arithmetic (Charter rule 2 PG-fidelity): ONE overflow flag shared by every
    // arithmetic step of the program. The checked kernels OR 1 into it when an op overflows int32;
    // after the program runs (each pooled-stream launch syncs) the host reads it once and raises
    // `integer out of range`, exactly like Postgres — never a silent wrap, and on-device (no CPU
    // fallback). Zeroed with a blocking HtoD so it is initialized before the first launch reads it.
    let overflow_buf = primary.lease_device_buffer(std::mem::size_of::<u32>())?;
    let overflow_zero = 0_u32;
    check_cuda(unsafe {
        cu_memcpy_htod(
            overflow_buf.ptr,
            (&overflow_zero as *const u32).cast::<c_void>(),
            std::mem::size_of::<u32>(),
        )
    })?;

    const BLOCK: u32 = 256;
    let grid = n.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;
    let resident_base = resident.device_ptr();
    let launch = |function: *mut c_void, args: &mut [*mut c_void]| -> Result<(), CudaRuntimeProbeError> {
        launch_on_pooled_stream(resident, None, |stream, _scratch| unsafe {
            cu_launch_kernel(
                function,
                grid,
                1,
                1,
                BLOCK,
                1,
                1,
                0,
                stream,
                args.as_mut_ptr(),
                std::ptr::null_mut(),
            )
        })
    };

    // Stack of leased intermediate buffers. Popped operands drop (return to the pool) after their
    // consuming step's stream has synced, so the pool churns at most ~tree-depth live buffers.
    let mut stack: Vec<PooledBufferLease> = Vec::new();
    for step in program {
        match *step {
            ExprStep::LoadColumn { byte_offset } => {
                let out = primary.lease_device_buffer(byte_len)?;
                let mut a0 = resident_base;
                let mut a1 = byte_offset;
                let mut a2 = n;
                let mut a3 = out.ptr;
                let mut args = [
                    (&mut a0 as *mut u64).cast::<c_void>(),
                    (&mut a1 as *mut u64).cast::<c_void>(),
                    (&mut a2 as *mut u64).cast::<c_void>(),
                    (&mut a3 as *mut u64).cast::<c_void>(),
                ];
                launch(load_fn, &mut args)?;
                stack.push(out);
            }
            ExprStep::BufferBinary { op } => {
                let rhs = stack
                    .pop()
                    .ok_or(CudaRuntimeProbeError::InvalidInputLength(0))?;
                let lhs = stack
                    .pop()
                    .ok_or(CudaRuntimeProbeError::InvalidInputLength(0))?;
                let out = primary.lease_device_buffer(byte_len)?;
                let mut a0 = lhs.ptr;
                let mut a1 = rhs.ptr;
                let mut a2 = op;
                let mut a3 = n;
                let mut a4 = out.ptr;
                let mut a5 = overflow_buf.ptr;
                let mut args = [
                    (&mut a0 as *mut u64).cast::<c_void>(),
                    (&mut a1 as *mut u64).cast::<c_void>(),
                    (&mut a2 as *mut u32).cast::<c_void>(),
                    (&mut a3 as *mut u64).cast::<c_void>(),
                    (&mut a4 as *mut u64).cast::<c_void>(),
                    (&mut a5 as *mut u64).cast::<c_void>(),
                ];
                // op 2 (multiply) over two i128 buffers uses the dedicated i128 column*column mul
                // kernel; add/sub (and all int4/int8 ops, where i128_mul_buffer_fn is None) use the
                // binary kernel.
                let function = match i128_mul_buffer_fn {
                    Some(mul_fn) if op == 2 => mul_fn,
                    _ => buffer_binary_fn,
                };
                launch(function, &mut args)?;
                stack.push(out);
            }
            ExprStep::ScalarBinary {
                op,
                scalar,
                scalar_on_left,
            } => {
                let lhs = stack
                    .pop()
                    .ok_or(CudaRuntimeProbeError::InvalidInputLength(0))?;
                let out = primary.lease_device_buffer(byte_len)?;
                let mut a0 = lhs.ptr;
                let mut a2 = op;
                let mut a3 = u32::from(scalar_on_left);
                let mut a4 = n;
                let mut a5 = out.ptr;
                let mut a6 = overflow_buf.ptr;
                // The scalar param is s32 (int4 kernel), s64 (int8 kernel), or two u64 limbs (the
                // numeric i128 kernel). The i32 ExprStep literal widens to the element type (PG's
                // int4->int8 / int4->numeric coercion).
                match elem {
                    ResidentElemType::I32 => {
                        let mut a1 = scalar;
                        let mut args = [
                            (&mut a0 as *mut u64).cast::<c_void>(),
                            (&mut a1 as *mut i32).cast::<c_void>(),
                            (&mut a2 as *mut u32).cast::<c_void>(),
                            (&mut a3 as *mut u32).cast::<c_void>(),
                            (&mut a4 as *mut u64).cast::<c_void>(),
                            (&mut a5 as *mut u64).cast::<c_void>(),
                            (&mut a6 as *mut u64).cast::<c_void>(),
                        ];
                        launch(scalar_binary_fn, &mut args)?;
                    }
                    ResidentElemType::I64 => {
                        let mut a1 = i64::from(scalar);
                        let mut args = [
                            (&mut a0 as *mut u64).cast::<c_void>(),
                            (&mut a1 as *mut i64).cast::<c_void>(),
                            (&mut a2 as *mut u32).cast::<c_void>(),
                            (&mut a3 as *mut u32).cast::<c_void>(),
                            (&mut a4 as *mut u64).cast::<c_void>(),
                            (&mut a5 as *mut u64).cast::<c_void>(),
                            (&mut a6 as *mut u64).cast::<c_void>(),
                        ];
                        launch(scalar_binary_fn, &mut args)?;
                    }
                    ResidentElemType::I128 => {
                        let s = i128::from(scalar);
                        let mut s_lo = s as u64;
                        let mut s_hi = (s >> 64) as u64;
                        let mut args = [
                            (&mut a0 as *mut u64).cast::<c_void>(),
                            (&mut s_lo as *mut u64).cast::<c_void>(),
                            (&mut s_hi as *mut u64).cast::<c_void>(),
                            (&mut a2 as *mut u32).cast::<c_void>(),
                            (&mut a3 as *mut u32).cast::<c_void>(),
                            (&mut a4 as *mut u64).cast::<c_void>(),
                            (&mut a5 as *mut u64).cast::<c_void>(),
                            (&mut a6 as *mut u64).cast::<c_void>(),
                        ];
                        // op 2 (multiply) uses the dedicated i128 mul kernel; add/sub the binary kernel.
                        let function = if op == 2 {
                            i128_mul_scalar_fn.ok_or(CudaRuntimeProbeError::InvalidInputLength(0))?
                        } else {
                            scalar_binary_fn
                        };
                        launch(function, &mut args)?;
                    }
                }
                stack.push(out);
            }
            ExprStep::CompareScalar {
                cmp,
                scalar,
                scalar_on_left,
            } => {
                let value = stack
                    .pop()
                    .ok_or(CudaRuntimeProbeError::InvalidInputLength(0))?;
                let out = primary.lease_device_buffer(byte_len)?;
                let mut a0 = value.ptr;
                let mut a2 = u32::from(scalar_on_left);
                let mut a3 = cmp;
                let mut a4 = n;
                let mut a5 = out.ptr;
                match elem {
                    ResidentElemType::I32 => {
                        let mut a1 = scalar;
                        let mut args = [
                            (&mut a0 as *mut u64).cast::<c_void>(),
                            (&mut a1 as *mut i32).cast::<c_void>(),
                            (&mut a2 as *mut u32).cast::<c_void>(),
                            (&mut a3 as *mut u32).cast::<c_void>(),
                            (&mut a4 as *mut u64).cast::<c_void>(),
                            (&mut a5 as *mut u64).cast::<c_void>(),
                        ];
                        launch(compare_scalar_mask_fn, &mut args)?;
                    }
                    ResidentElemType::I64 => {
                        let mut a1 = i64::from(scalar);
                        let mut args = [
                            (&mut a0 as *mut u64).cast::<c_void>(),
                            (&mut a1 as *mut i64).cast::<c_void>(),
                            (&mut a2 as *mut u32).cast::<c_void>(),
                            (&mut a3 as *mut u32).cast::<c_void>(),
                            (&mut a4 as *mut u64).cast::<c_void>(),
                            (&mut a5 as *mut u64).cast::<c_void>(),
                        ];
                        launch(compare_scalar_mask_fn, &mut args)?;
                    }
                    ResidentElemType::I128 => {
                        let s = i128::from(scalar);
                        let mut s_lo = s as u64;
                        let mut s_hi = (s >> 64) as u64;
                        let mut args = [
                            (&mut a0 as *mut u64).cast::<c_void>(),
                            (&mut s_lo as *mut u64).cast::<c_void>(),
                            (&mut s_hi as *mut u64).cast::<c_void>(),
                            (&mut a2 as *mut u32).cast::<c_void>(),
                            (&mut a3 as *mut u32).cast::<c_void>(),
                            (&mut a4 as *mut u64).cast::<c_void>(),
                            (&mut a5 as *mut u64).cast::<c_void>(),
                        ];
                        launch(compare_scalar_mask_fn, &mut args)?;
                    }
                }
                stack.push(out);
            }
            ExprStep::CompareBuffers { cmp } => {
                let rhs = stack
                    .pop()
                    .ok_or(CudaRuntimeProbeError::InvalidInputLength(0))?;
                let lhs = stack
                    .pop()
                    .ok_or(CudaRuntimeProbeError::InvalidInputLength(0))?;
                let out = primary.lease_device_buffer(byte_len)?;
                let mut a0 = lhs.ptr;
                let mut a1 = rhs.ptr;
                let mut a2 = cmp;
                let mut a3 = n;
                let mut a4 = out.ptr;
                let mut args = [
                    (&mut a0 as *mut u64).cast::<c_void>(),
                    (&mut a1 as *mut u64).cast::<c_void>(),
                    (&mut a2 as *mut u32).cast::<c_void>(),
                    (&mut a3 as *mut u64).cast::<c_void>(),
                    (&mut a4 as *mut u64).cast::<c_void>(),
                ];
                launch(compare_buffers_mask_fn, &mut args)?;
                stack.push(out);
            }
            ExprStep::MaskBinary { op } => {
                let rhs = stack
                    .pop()
                    .ok_or(CudaRuntimeProbeError::InvalidInputLength(0))?;
                let lhs = stack
                    .pop()
                    .ok_or(CudaRuntimeProbeError::InvalidInputLength(0))?;
                let out = primary.lease_device_buffer(byte_len)?;
                let mut a0 = lhs.ptr;
                let mut a1 = rhs.ptr;
                let mut a2 = op;
                let mut a3 = n;
                let mut a4 = out.ptr;
                let mut args = [
                    (&mut a0 as *mut u64).cast::<c_void>(),
                    (&mut a1 as *mut u64).cast::<c_void>(),
                    (&mut a2 as *mut u32).cast::<c_void>(),
                    (&mut a3 as *mut u64).cast::<c_void>(),
                    (&mut a4 as *mut u64).cast::<c_void>(),
                ];
                launch(mask_binary_fn, &mut args)?;
                stack.push(out);
            }
        }
    }

    // Every arithmetic launch has synced; read the shared overflow flag once. Any overflowing op set
    // it, so the whole query must error like Postgres (int4 -> "integer out of range", int8 ->
    // "bigint out of range") rather than return rows computed from a silently-wrapped value.
    let mut overflow = 0_u32;
    check_cuda(unsafe {
        cu_memcpy_dtoh(
            (&mut overflow as *mut u32).cast::<c_void>(),
            overflow_buf.ptr,
            std::mem::size_of::<u32>(),
        )
    })?;
    if overflow != 0 {
        return Err(match elem {
            ResidentElemType::I32 => CudaRuntimeProbeError::IntegerOutOfRange,
            ResidentElemType::I64 => CudaRuntimeProbeError::BigintOutOfRange,
            ResidentElemType::I128 => CudaRuntimeProbeError::NumericFieldOverflow,
        });
    }

    Ok(stack)
}

/// Evaluate an arithmetic `program` to one value buffer, then compare it to `needle` -> row indices.
fn launch_cuda_resident_expr_arith_filter(
    resident: &CudaResidentDeviceMemory,
    program: &[ExprStep],
    n: u64,
    compare_code: u32,
    needle: i32,
) -> Result<Vec<u32>, CudaRuntimeProbeError> {
    if n == 0 {
        return Ok(Vec::new());
    }
    let mut stack = run_resident_arith_program(resident, program, n, ResidentElemType::I32)?;
    let value = stack
        .pop()
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(0))?;
    if !stack.is_empty() {
        // A well-formed arithmetic program leaves exactly one value on the stack.
        return Err(CudaRuntimeProbeError::InvalidInputLength(program.len()));
    }
    compact_buffer_i32_compare_to_indices(resident, value.ptr, n, needle, compare_code)
}

/// Evaluate an arithmetic `program` over all `n_rows`, then GATHER the resulting i32 value column at
/// the survivor `indices` (sign-extended to i64). The ORDER BY-expression key column: the device Expr
/// interpreter computes `a+b` etc. with CHECKED int4 arithmetic (overflow -> `IntegerOutOfRange`,
/// inherited from `run_resident_arith_program` -- no wrap, no CPU), and the result feeds the GPU sort
/// exactly like a materialized int key.
/// A resident arith-program result kept ON-DEVICE (the value buffer, one element per row) + its pooled
/// lease. Returned by [`CudaResidentDeviceMemory::arith_value_column_device`]; `device_ptr()` is read by
/// a LATER kernel launch (the GROUP BY group-key via `key_base_override`), so this MUST be kept alive
/// across every such launch -- dropping it returns the buffer to the pool (a UAF under reuse).
pub struct DeviceArithBuffer<'a> {
    _lease: PooledBufferLease<'a>,
    ptr: u64,
}

impl DeviceArithBuffer<'_> {
    /// Device address of the value buffer (one element per row; width = the program's element type).
    pub fn device_ptr(&self) -> u64 {
        self.ptr
    }
}

/// Run an arith program over all `n_rows` and return the result value buffer RESIDENT (no D2H). See
/// [`CudaResidentDeviceMemory::arith_value_column_device`]. cuCtxSynchronize'd so a later launch reads
/// valid keys. Checked overflow -> PG error inherited from `run_resident_arith_program`.
fn launch_cuda_arith_value_column_device<'r>(
    resident: &'r CudaResidentDeviceMemory,
    program: &[ExprStep],
    n_rows: u64,
    elem: ResidentElemType,
) -> Result<DeviceArithBuffer<'r>, CudaRuntimeProbeError> {
    type CuCtxSynchronize = unsafe extern "C" fn() -> i32;
    let n = usize::try_from(n_rows).map_err(|_| CudaRuntimeProbeError::InvalidInputLength(0))?;
    if n == 0 {
        return Err(CudaRuntimeProbeError::InvalidInputLength(0));
    }
    let mut stack = run_resident_arith_program(resident, program, n_rows, elem)?;
    let value = stack
        .pop()
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(0))?;
    if !stack.is_empty() {
        // A well-formed arithmetic program leaves exactly one value on the stack.
        return Err(CudaRuntimeProbeError::InvalidInputLength(program.len()));
    }
    // Block until the arith program finishes, so the SEPARATE GROUP BY launch that reads this buffer
    // sees the completed keys (not a racing/stale buffer).
    let cu_ctx_synchronize = unsafe {
        resident
            .lib()
            .get::<CuCtxSynchronize>(b"cuCtxSynchronize\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    check_cuda(unsafe { cu_ctx_synchronize() })?;
    let ptr = value.ptr;
    Ok(DeviceArithBuffer { _lease: value, ptr })
}

/// Run `gpu_db_resident_bool_to_mask` (negate=0) into a leased int4 buffer (it writes 0/1 per row) and
/// return it as a `DeviceArithBuffer` -- the derived int4 column for a bool GROUP BY key / bool MIN/MAX
/// value. Synchronizes so the SEPARATE GROUP BY launch (which reads it via key/value_base_override) sees
/// the completed buffer, not a racing/stale one. The lease lives in the returned buffer (caller-owned).
fn launch_cuda_bool_to_int4_column_device<'r>(
    resident: &'r CudaResidentDeviceMemory,
    bitmap_byte_offset: u64,
    n: u64,
) -> Result<DeviceArithBuffer<'r>, CudaRuntimeProbeError> {
    type CuLaunchKernel = unsafe extern "C" fn(
        *mut c_void,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        u32,
        *mut c_void,
        *mut *mut c_void,
        *mut *mut c_void,
    ) -> i32;
    type CuCtxSynchronize = unsafe extern "C" fn() -> i32;
    const PTX: &[u8] = include_bytes!("expr_proto.ptx");
    if n == 0 {
        return Err(CudaRuntimeProbeError::InvalidInputLength(0));
    }
    let n_usize = usize::try_from(n).map_err(|_| CudaRuntimeProbeError::InvalidInputLength(0))?;
    let out_bytes = n_usize
        .checked_mul(std::mem::size_of::<i32>())
        .ok_or(CudaRuntimeProbeError::InvalidInputLength(n_usize))?;
    let primary = resident.primary();
    primary.set_current()?;
    let cu_launch_kernel = unsafe {
        resident
            .lib()
            .get::<CuLaunchKernel>(b"cuLaunchKernel\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    let mut ptx = Vec::with_capacity(PTX.len() + 1);
    ptx.extend_from_slice(PTX);
    ptx.push(0);
    let kernel_fn = primary.cached_function(c"gpu_db_resident_bool_to_mask", &ptx)?;
    let out = primary.lease_device_buffer(out_bytes)?;
    const BLOCK: u32 = 256;
    let grid = n.div_ceil(u64::from(BLOCK)).clamp(1, 65_535) as u32;
    let mut a0 = resident.device_ptr();
    let mut a1 = bitmap_byte_offset;
    let mut a2 = 0u32; // negate = false: bool true -> int4 1, false -> 0
    let mut a3 = n;
    let mut a4 = out.ptr;
    let mut args = [
        (&mut a0 as *mut u64).cast::<c_void>(),
        (&mut a1 as *mut u64).cast::<c_void>(),
        (&mut a2 as *mut u32).cast::<c_void>(),
        (&mut a3 as *mut u64).cast::<c_void>(),
        (&mut a4 as *mut u64).cast::<c_void>(),
    ];
    launch_on_pooled_stream(resident, None, |stream, _scratch| unsafe {
        cu_launch_kernel(
            kernel_fn,
            grid,
            1,
            1,
            BLOCK,
            1,
            1,
            0,
            stream,
            args.as_mut_ptr(),
            std::ptr::null_mut(),
        )
    })?;
    let cu_ctx_synchronize = unsafe {
        resident
            .lib()
            .get::<CuCtxSynchronize>(b"cuCtxSynchronize\0")
            .map_err(|_| CudaRuntimeProbeError::DriverLibraryUnavailable)?
    };
    check_cuda(unsafe { cu_ctx_synchronize() })?;
    let ptr = out.ptr;
    Ok(DeviceArithBuffer { _lease: out, ptr })
}

